(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-057"]={"sura":57,"name_ar":"الحديد","name_en":"Al-Hadid","verses":29,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":29,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=57&ayah=3\" class=\"link\">57:3</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 57:3 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=57&ayah=3\" class=\"link\">57:3</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 57:3 ஐ பார்க்கவும்"},"3":{"html":"<strong>மதீனாவில் அருளப்பட்டது</strong><br />\r\n<br />\r\n<strong>ஸூரத்துல் ஹதீதின் சிறப்புகள்</strong><br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: இர்பாத் பின் சாரியா (ரழி) அவர்கள் கூறினார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தூங்கச் செல்வதற்கு முன்னால் 'அல்-முஸப்பிஹாத்' (அல்லாஹ்வைத் துதிக்கும் சொற்களுடன் தொடங்கும் அத்தியாயங்களை) ஓதுவார்கள். மேலும் அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِيهِنَّ</span> <span class=\"quran-arabic-font text-success\">آيَةً</span> <span class=\"quran-arabic-font text-success\">أَفْضَلُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَلْفِ</span> <span class=\"quran-arabic-font text-success\">آيَة</span>»<br />\r\n<br />\r\n(நிச்சயமாக அவற்றில் ஓராயிரம் வசனங்களை விடச் சிறந்த ஒரு வசனம் உள்ளது.) அபூ தாவூத், திர்மிதீ மற்றும் நஸாயீ ஆகியோரும் இந்த ஹதீஸைப் பதிவு செய்துள்ளனர். இமாம் திர்மிதீ அவர்கள் இது 'ஹஸன் ஃகரீப்' வகையைச் சார்ந்த ஹதீஸ் என்று குறிப்பிட்டுள்ளார். இந்த ஹதீஸில் குறிப்பிடப்பட்டுள்ள அந்த வசனம் - அல்லாஹ்வே மிக அறிந்தவன் - இதுவாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الاٌّوَّلُ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّخِرُ</span> <span class=\"quran-arabic-font text-success\">وَالظَّـهِرُ</span> <span class=\"quran-arabic-font text-success\">وَالْبَـطِنُ</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">بِكُلِّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">عَلِيمٌ</span><br />\r\n<br />\r\n(அவனே முந்தினவன் (அல்-அவ்வல்), பிந்தினவன் (அல்-ஆகிர்), பகிரங்கமானவன் (அழ்-ழாஹிர்) மற்றும் அந்தரங்கமானவன் (அல்-பாதின்). மேலும் அவன் அனைத்துப் பொருட்களையும் நன்கறிந்தவன்.) (<a href=\"qurandisp.php?sura=57&ayah=3\" class=\"link\">57:3</a>) அல்லாஹ் நாடினால், இந்த விஷயத்தை மீண்டும் நாம் விளக்குவோம். நாம் அல்லாஹ்வின் மீதே நம்பிக்கை வைத்துள்ளோம்; அவனையே முற்றிலும் சார்ந்துள்ளோம். நமக்கு ஆதரவாளனாகவும் உதவியாளனாகவும் அவனே போதுமானவன்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span><br />\r\n<br />\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.<br />\r\n<br />\r\n<strong>உள்ளவை அனைத்தும் அல்லாஹ்வைத் துதிப்பதும், அவனது சில பண்புகளைக் குறிப்பிடுவதும்</strong><br />\r\n<br />\r\nவானங்களிலும் பூமியிலும் உள்ள உயிரினங்கள் மற்றும் தாவரங்கள் உள்ளிட்ட அனைத்தும் அல்லாஹ்வைப் புகழ்ந்து துதிக்கின்றன என்று இந்த வசனத்தில் அல்லாஹ் கூறுகிறான். மற்றொரு வசனத்தில் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">تُسَبِّحُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتُ</span> <span class=\"quran-arabic-font text-success\">السَّبْعُ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّرْضُ</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">فِيهِنَّ</span> <span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">يُسَبِّحُ</span> <span class=\"quran-arabic-font text-success\">بِحَمْدَهِ</span> <span class=\"quran-arabic-font text-success\">وَلَـكِن</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">تَفْقَهُونَ</span> <span class=\"quran-arabic-font text-success\">تَسْبِيحَهُمْ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">حَلِيمًا</span> <span class=\"quran-arabic-font text-success\">غَفُورًا</span><br />\r\n<br />\r\n(ஏழு வானங்களும், பூமியும், அவற்றில் உள்ளவைகளும் அவனைத் துதிக்கின்றன. இன்னும் அவனது புகழைக் கொண்டு துதிக்காத பொருள் எதுவுமே இல்லை; எனினும் அவற்றின் துதித்தலை நீங்கள் புரிந்து கொள்ள மாட்டீர்கள். நிச்சயமாக அவன் சகிப்புத்தன்மை உடையவனாகவும், மிக மன்னிப்பவனாகவும் இருக்கிறான்.) (<a href=\"qurandisp.php?sura=17&ayah=44\" class=\"link\">17:44</a>) மேலும் அவனது கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزُ</span><br />\r\n<br />\r\n(அவன் யாவற்றையும் மிகைத்தவன்,) அதாவது அனைத்தும் அவனுக்குப் பணிந்து அடிபணிகின்றன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الْحَكِيمُ</span><br />\r\n<br />\r\n(ஞானமிக்கவன்.) அவன் படைப்பதிலும், கட்டளையிடுவதிலும், சட்டமியற்றுவதிலும் ஞானமிக்கவனாக இருக்கிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مُلْكُ</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّرْضِ</span> <span class=\"quran-arabic-font text-success\">يُحْىِ</span> <span class=\"quran-arabic-font text-success\">وَيُمِيتُ</span><br />\r\n<br />\r\n(வானங்கள் மற்றும் பூமியின் அதிகாரம் அவனுக்கே உரியது. அவனே உயிர்ப்பிக்கிறான், இன்னும் அவனே மரணிக்கச் செய்கிறான்.) அவன் தனது படைப்புகளின் முழுமையான உரிமையாளன்; அவன் வாழ்வையும் மரணத்தையும் வழங்குகிறான்; தான் நாடியதை நாடியவர்களுக்கு வழங்குகிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">قَدِيرٌ</span><br />\r\n<br />\r\n(அவன் அனைத்துப் பொருட்களின் மீதும் பேராற்றல் உடையவன்.) அவன் எதை நாடுகிறானோ அது நடக்கும், அவன் எதை நாடவில்லையோ அது ஒருபோதும் நடக்காது. அவன் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الاٌّوَّلُ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّخِرُ</span> <span class=\"quran-arabic-font text-success\">وَالظَّـهِرُ</span> <span class=\"quran-arabic-font text-success\">وَالْبَـطِنُ</span><br />\r\n<br />\r\n(அவனே முந்தினவன் (அல்-அவ்வல்), பிந்தினவன் (அல்-ஆகிர்), பகிரங்கமானவன் (அழ்-ழாஹிர்) மற்றும் அந்தரங்கமானவன் (அல்-பாதின்).) இதுதான் இர்பாத் பின் சாரியா (ரழி) அவர்களின் ஹதீஸில் ஓராயிரம் வசனங்களை விடச் சிறந்தது எனக் குறிப்பிடப்பட்ட வசனமாகும்.<br />\r\n<br />\r\nஅபூ ஸாமில் அவர்கள் கூறியதாக அபூ தாவூத் பதிவு செய்துள்ளார்: \"நான் இப்னு அப்பாஸ் (ரழி) அவர்களிடம், என் உள்ளத்தில் ஏதோ ஒரு சஞ்சலத்தை (சந்தேகத்தை) உணர்வதாகக் கூறினேன். அதற்கு அவர்கள் 'சந்தேகங்களா?' என்று கேட்டுவிட்டுச் சிரித்தார்கள். பிறகு, 'யாரும் இதிலிருந்து தப்ப முடியாது' என்று கூறிவிட்டு, கண்ணியமிக்க அல்லாஹ் கூறிய இந்த வசனத்தை ஓதினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِن</span> <span class=\"quran-arabic-font text-success\">كُنتَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">شَكٍّ</span> <span class=\"quran-arabic-font text-success\">مِّمَّآ</span> <span class=\"quran-arabic-font text-success\">أَنزَلْنَآ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكَ</span> <span class=\"quran-arabic-font text-success\">فَاسْأَلِ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَقْرَءُونَ</span> <span class=\"quran-arabic-font text-success\">الْكِتَـبَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِكَ</span> <span class=\"quran-arabic-font text-success\">لَقَدْ</span> <span class=\"quran-arabic-font text-success\">جَآءَكَ</span> <span class=\"quran-arabic-font text-success\">الْحَقُّ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رَّبِّكَ</span><br />\r\n<br />\r\n(எனவே, நாம் உமக்கு அருளிய வஹீ (இறைச்செய்தி)யைப் பற்றி நீர் சந்தேகத்தில் இருந்தால், உமக்கு முன்னுள்ள வேதத்தை ஓதுகின்றவர்களிடம் கேட்டுப்பாரும். நிச்சயமாக உம் இறைவனிடமிருந்து உம்மிடம் சத்தியம் வந்துள்ளது.) (<a href=\"qurandisp.php?sura=10&ayah=94\" class=\"link\">10:94</a>)\" பிறகு அவர்கள் என்னிடம், \"உமது உள்ளத்தில் இதுபோன்ற எதையேனும் நீர் உணர்ந்தால், இந்த வசனத்தை ஓதுவீராக\" என்று கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الاٌّوَّلُ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّخِرُ</span> <span class=\"quran-arabic-font text-success\">وَالظَّـهِرُ</span> <span class=\"quran-arabic-font text-success\">وَالْبَـطِنُ</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">بِكُلِّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">عَلِيمٌ</span><br />\r\n<br />\r\n(அவனே முந்தினவன், பிந்தினவன், பகிரங்கமானவன் மற்றும் அந்தரங்கமானவன். மேலும் அவன் அனைத்துப் பொருட்களையும் நன்கறிந்தவன்.)\" இந்த வசனத்தின் விளக்கத்தில் தஃப்ஸீர் அறிஞர்களிடமிருந்து பத்திற்கும் மேற்பட்ட கருத்துக்கள் பெறப்பட்டுள்ளன.<br />\r\n<br />\r\nஅல்-புகாரீ கூறுகிறார்: யஹ்யா அவர்கள் கூறினார்கள், \"அழ்-ழாஹிர்: அனைத்துப் பொருட்களையும் அறிந்தவன், அல்-பாதின்: அனைத்துப் பொருட்களையும் அறிந்தவன்.\" எமது ஆசிரியர் அல்-ஹாஃபிழ் அல்-மிஸ்ஸீ அவர்கள் கூறினார்கள்: \"இதில் குறிப்பிடப்படும் யஹ்யா என்பவர் 'மஆனில் குர்ஆன்' என்ற நூலை எழுதிய இப்னு ஸியாத் அல்-ஃபர்ரா ஆவார்.\"<br />\r\n<br />\r\nஇது குறித்து பல ஹதீஸ்கள் வந்துள்ளன. அவற்றில் ஒன்றாக, அபூ ஹுரைரா (ரழி) அவர்கள் அறிவித்ததை இமாம் அஹ்மத் பதிவு செய்துள்ளார்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் படுக்கைக்குச் செல்லும்போது இந்தத் துஆவை ஓதுவார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اللَّهُمَّ</span> <span class=\"quran-arabic-font text-success\">رَبَّ</span> <span class=\"quran-arabic-font text-success\">السَّموَاتِ</span> <span class=\"quran-arabic-font text-success\">السَّبْعِ،</span> <span class=\"quran-arabic-font text-success\">وَرَبَّ</span> <span class=\"quran-arabic-font text-success\">الْعَرْشِ</span> <span class=\"quran-arabic-font text-success\">الْعَظِيمِ،</span> <span class=\"quran-arabic-font text-success\">رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">وَرَبَّ</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ،</span> <span class=\"quran-arabic-font text-success\">مُنْزِلَ</span> <span class=\"quran-arabic-font text-success\">التَّوْرَاةِ</span> <span class=\"quran-arabic-font text-success\">وَالْإِنْجِيلِ</span> <span class=\"quran-arabic-font text-success\">وَالْفُرْقَانِ،</span> <span class=\"quran-arabic-font text-success\">فَالِقَ</span> <span class=\"quran-arabic-font text-success\">الْحَبِّ</span> <span class=\"quran-arabic-font text-success\">وَالنَّوَى،</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">إِلهَ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">أَنْتَ،</span> <span class=\"quran-arabic-font text-success\">أَعُوذُ</span> <span class=\"quran-arabic-font text-success\">بِكَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">شَرِّ</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">أَنْتَ</span> <span class=\"quran-arabic-font text-success\">آخِذٌ</span> <span class=\"quran-arabic-font text-success\">بِنَاصِيَتِهِ،</span> <span class=\"quran-arabic-font text-success\">أَنْتَ</span> <span class=\"quran-arabic-font text-success\">الْأَوَّلُ</span> <span class=\"quran-arabic-font text-success\">لَيْسَ</span> <span class=\"quran-arabic-font text-success\">قَبْلَكَ</span> <span class=\"quran-arabic-font text-success\">شَيْءٌ،</span> <span class=\"quran-arabic-font text-success\">وَأَنْتَ</span> <span class=\"quran-arabic-font text-success\">الْآخِرُ</span> <span class=\"quran-arabic-font text-success\">لَيْسَ</span> <span class=\"quran-arabic-font text-success\">بَعْدَكَ</span> <span class=\"quran-arabic-font text-success\">شَيْءٌ،</span> <span class=\"quran-arabic-font text-success\">وَأَنْتَ</span> <span class=\"quran-arabic-font text-success\">الظَّاهِرُ</span> <span class=\"quran-arabic-font text-success\">لَيْسَ</span> <span class=\"quran-arabic-font text-success\">فَوْقَكَ</span> <span class=\"quran-arabic-font text-success\">شَيْءٌ،</span> <span class=\"quran-arabic-font text-success\">وَأَنْتَ</span> <span class=\"quran-arabic-font text-success\">الْبَاطِنُ</span> <span class=\"quran-arabic-font text-success\">لَيْسَ</span> <span class=\"quran-arabic-font text-success\">دُونَكَ</span> <span class=\"quran-arabic-font text-success\">شَيْءٌ</span>. <span class=\"quran-arabic-font text-success\">اقْضِ</span> <span class=\"quran-arabic-font text-success\">عَنَّا</span> <span class=\"quran-arabic-font text-success\">الدَّيْنَ،</span> <span class=\"quran-arabic-font text-success\">وَأَغْنِنَا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْفَقْر</span>»<br />\r\n<br />\r\n(யா அல்லாஹ்! ஏழு வானங்களின் இறைவனே! மகத்தான அர்ஷின் இறைவனே! எங்களின் இறைவனே! அனைத்துப் பொருட்களின் இறைவனே! தவ்ராத், இன்ஜீல் மற்றும் ஃபுர்கானை இறக்கி வைத்தவனே! தானியங்களையும் விதைகளையும் பிளப்பவனே! வணக்கத்திற்குரியவன் நீயைத் தவிர வேறு யாருமில்லை; எவற்றின் முன்நெற்றியை நீ பிடித்துக் கொண்டிருக்கின்றாயோ (உன் கட்டுப்பாட்டில் உள்ளதோ) அத்தகைய அனைத்துப் பொருட்களின் தீங்கிலிருந்தும் உன்னிடம் நான் பாதுகாப்புத் தேடுகிறேன். யா அல்லாஹ்! நீயே முந்தினவன் (அல்-அவ்வல்), உனக்கு முன்னால் எதுவுமில்லை. நீயே பிந்தினவன் (அல்-ஆகிர்), உனக்குப் பின்னால் எதுவுமில்லை. நீயே மேலானவன்/பகிரங்கமானவன் (அழ்-ழாஹிர்), உனக்கு மேலாக எதுவுமில்லை. நீயே நெருக்கமானவன்/அந்தரங்கமானவன் (அல்-பாதின்), உனக்குக் கீழே எதுவுமில்லை. எங்களது கடனைத் தீர்ப்பாயாக, வறுமையிலிருந்து எங்களை விடுவித்துச் செல்வந்தர்களாக்குவாயாக.)<br />\r\n<br />\r\nஇமாம் முஸ்லிம் அவர்கள் ஸஹ்ல் வழியாகப் பதிவு செய்துள்ள ஹதீஸில் ஸஹ்ல் கூறுகிறார்: \"நாங்கள் தூங்கச் செல்லும்போது எங்களை வலது பக்கமாக ஒருக்களித்துப் படுக்குமாறு அபூ ஸாலிஹ் அவர்கள் பணிப்பார்கள். பிறகு இவ்வாறு கூறச் சொல்வார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اللَّهُمَّ</span> <span class=\"quran-arabic-font text-success\">رَبَّ</span> <span class=\"quran-arabic-font text-success\">السَّموَاتِ</span> <span class=\"quran-arabic-font text-success\">وَرَبَّ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَرَبَّ</span> <span class=\"quran-arabic-font text-success\">الْعَرْشِ</span> <span class=\"quran-arabic-font text-success\">الْعَظِيمِ،</span> <span class=\"quran-arabic-font text-success\">رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">وَرَبَّ</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ،</span> <span class=\"quran-arabic-font text-success\">فَالِقَ</span> <span class=\"quran-arabic-font text-success\">الْحَبِّ</span> <span class=\"quran-arabic-font text-success\">وَالنَّوَى،</span> <span class=\"quran-arabic-font text-success\">وَمُنْزِلَ</span> <span class=\"quran-arabic-font text-success\">التَّوْرَاةِ</span> <span class=\"quran-arabic-font text-success\">وَالْإِنْجِيلِ</span> <span class=\"quran-arabic-font text-success\">وَالْفُرْقَانِ،</span> <span class=\"quran-arabic-font text-success\">أَعُوذُ</span> <span class=\"quran-arabic-font text-success\">بِكَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">شَرِّ</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">ذِي</span> <span class=\"quran-arabic-font text-success\">شَرٍّ</span> <span class=\"quran-arabic-font text-success\">أَنْتَ</span> <span class=\"quran-arabic-font text-success\">آخِذٌ</span> <span class=\"quran-arabic-font text-success\">بِنَاصِيَتِهِ،</span> <span class=\"quran-arabic-font text-success\">اللَّهُمَّ</span> <span class=\"quran-arabic-font text-success\">أَنْتَ</span> <span class=\"quran-arabic-font text-success\">الْأَوَّلُ</span> <span class=\"quran-arabic-font text-success\">فَلَيْسَ</span> <span class=\"quran-arabic-font text-success\">قَبْلَكَ</span> <span class=\"quran-arabic-font text-success\">شَيْءٌ،</span> <span class=\"quran-arabic-font text-success\">وَأَنْتَ</span> <span class=\"quran-arabic-font text-success\">الْآخِرُ</span> <span class=\"quran-arabic-font text-success\">فَلَيْسَ</span> <span class=\"quran-arabic-font text-success\">بَعْدَكَ</span> <span class=\"quran-arabic-font text-success\">شَيْءٌ،</span> <span class=\"quran-arabic-font text-success\">وَأَنْتَ</span> <span class=\"quran-arabic-font text-success\">الظَّاهِرُ</span> <span class=\"quran-arabic-font text-success\">فَلَيْسَ</span> <span class=\"quran-arabic-font text-success\">فَوْقَكَ</span> <span class=\"quran-arabic-font text-success\">شَيْءٌ،</span> <span class=\"quran-arabic-font text-success\">وَأَنْتَ</span> <span class=\"quran-arabic-font text-success\">الْبَاطِنُ</span> <span class=\"quran-arabic-font text-success\">فَلَيْسَ</span> <span class=\"quran-arabic-font text-success\">دُونَكَ</span> <span class=\"quran-arabic-font text-success\">شَيْءٌ،</span> <span class=\"quran-arabic-font text-success\">اقْضِ</span> <span class=\"quran-arabic-font text-success\">عَنَّا</span> <span class=\"quran-arabic-font text-success\">الدَّيْنَ،</span> <span class=\"quran-arabic-font text-success\">وَأَغْنِنَا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْفَقْر</span>»<br />\r\n<br />\r\n(யா அல்லாஹ்! வானங்களின் இறைவனே! பூமியின் இறைவனே! மகத்தான அர்ஷின் இறைவனே! எங்களின் இறைவனே! அனைத்துப் பொருட்களின் இறைவனே! தானியத்தையும் விதைகளையும் பிளப்பவனே! தவ்ராத், இன்ஜீல் மற்றும் ஃபுர்கானை இறக்கி வைத்தவனே! எவற்றின் முன்நெற்றியை நீ பிடித்துக் கொண்டிருக்கின்றாயோ, அத்தகைய தீயவை அனைத்தின் தீங்கிலிருந்தும் உன்னிடம் நான் பாதுகாப்புத் தேடுகிறேன். யா அல்லாஹ்! நீயே முந்தினவன், உனக்கு முன்னால் எதுவுமில்லை. நீயே பிந்தினவன், உனக்குப் பின்னால் எதுவுமில்லை. நீயே மேலானவன், உனக்கு மேலாக எதுவுமில்லை. நீயே அந்தரங்கமானவன், உனக்குக் கீழே எதுவுமில்லை. எங்களது கடனைத் தீர்ப்பாயாக, வறுமையிலிருந்து எங்களை விடுவித்துச் செல்வந்தர்களாக்குவாயாக.) அபூ ஸாலிஹ் அவர்கள் இதனை அபூ ஹுரைரா (ரழி) அவர்கள் வழியாக நபி (ஸல்) அவர்களிடமிருந்து அறிவிப்பார்கள்.\"<br />\r\n<br />","text":"மதீனாவில் அருளப்பட்டது\n\r\n\n\r\nஸூரத்துல் ஹதீதின் சிறப்புகள்\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: இர்பாத் பின் சாரியா (ரழி) அவர்கள் கூறினார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தூங்கச் செல்வதற்கு முன்னால் 'அல்-முஸப்பிஹாத்' (அல்லாஹ்வைத் துதிக்கும் சொற்களுடன் தொடங்கும் அத்தியாயங்களை) ஓதுவார்கள். மேலும் அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنَّ فِيهِنَّ آيَةً أَفْضَلُ مِنْ أَلْفِ آيَة»\n\r\n\n\r\n(நிச்சயமாக அவற்றில் ஓராயிரம் வசனங்களை விடச் சிறந்த ஒரு வசனம் உள்ளது.) அபூ தாவூத், திர்மிதீ மற்றும் நஸாயீ ஆகியோரும் இந்த ஹதீஸைப் பதிவு செய்துள்ளனர். இமாம் திர்மிதீ அவர்கள் இது 'ஹஸன் ஃகரீப்' வகையைச் சார்ந்த ஹதீஸ் என்று குறிப்பிட்டுள்ளார். இந்த ஹதீஸில் குறிப்பிடப்பட்டுள்ள அந்த வசனம் - அல்லாஹ்வே மிக அறிந்தவன் - இதுவாகும்:\n\r\n\n\r\nهُوَ الاٌّوَّلُ وَالاٌّخِرُ وَالظَّـهِرُ وَالْبَـطِنُ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ\n\r\n\n\r\n(அவனே முந்தினவன் (அல்-அவ்வல்), பிந்தினவன் (அல்-ஆகிர்), பகிரங்கமானவன் (அழ்-ழாஹிர்) மற்றும் அந்தரங்கமானவன் (அல்-பாதின்). மேலும் அவன் அனைத்துப் பொருட்களையும் நன்கறிந்தவன்.) (57:3) அல்லாஹ் நாடினால், இந்த விஷயத்தை மீண்டும் நாம் விளக்குவோம். நாம் அல்லாஹ்வின் மீதே நம்பிக்கை வைத்துள்ளோம்; அவனையே முற்றிலும் சார்ந்துள்ளோம். நமக்கு ஆதரவாளனாகவும் உதவியாளனாகவும் அவனே போதுமானவன்.\n\r\n\n\r\nبِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ\n\r\n\n\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.\n\r\n\n\r\nஉள்ளவை அனைத்தும் அல்லாஹ்வைத் துதிப்பதும், அவனது சில பண்புகளைக் குறிப்பிடுவதும்\n\r\n\n\r\nவானங்களிலும் பூமியிலும் உள்ள உயிரினங்கள் மற்றும் தாவரங்கள் உள்ளிட்ட அனைத்தும் அல்லாஹ்வைப் புகழ்ந்து துதிக்கின்றன என்று இந்த வசனத்தில் அல்லாஹ் கூறுகிறான். மற்றொரு வசனத்தில் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nتُسَبِّحُ لَهُ السَّمَـوَتُ السَّبْعُ وَالاٌّرْضُ وَمَن فِيهِنَّ وَإِن مِّن شَىْءٍ إِلاَّ يُسَبِّحُ بِحَمْدَهِ وَلَـكِن لاَّ تَفْقَهُونَ تَسْبِيحَهُمْ إِنَّهُ كَانَ حَلِيمًا غَفُورًا\n\r\n\n\r\n(ஏழு வானங்களும், பூமியும், அவற்றில் உள்ளவைகளும் அவனைத் துதிக்கின்றன. இன்னும் அவனது புகழைக் கொண்டு துதிக்காத பொருள் எதுவுமே இல்லை; எனினும் அவற்றின் துதித்தலை நீங்கள் புரிந்து கொள்ள மாட்டீர்கள். நிச்சயமாக அவன் சகிப்புத்தன்மை உடையவனாகவும், மிக மன்னிப்பவனாகவும் இருக்கிறான்.) (17:44) மேலும் அவனது கூற்று:\n\r\n\n\r\nوَهُوَ الْعَزِيزُ\n\r\n\n\r\n(அவன் யாவற்றையும் மிகைத்தவன்,) அதாவது அனைத்தும் அவனுக்குப் பணிந்து அடிபணிகின்றன.\n\r\n\n\r\nالْحَكِيمُ\n\r\n\n\r\n(ஞானமிக்கவன்.) அவன் படைப்பதிலும், கட்டளையிடுவதிலும், சட்டமியற்றுவதிலும் ஞானமிக்கவனாக இருக்கிறான்.\n\r\n\n\r\nلَهُ مُلْكُ السَّمَـوَتِ وَالاٌّرْضِ يُحْىِ وَيُمِيتُ\n\r\n\n\r\n(வானங்கள் மற்றும் பூமியின் அதிகாரம் அவனுக்கே உரியது. அவனே உயிர்ப்பிக்கிறான், இன்னும் அவனே மரணிக்கச் செய்கிறான்.) அவன் தனது படைப்புகளின் முழுமையான உரிமையாளன்; அவன் வாழ்வையும் மரணத்தையும் வழங்குகிறான்; தான் நாடியதை நாடியவர்களுக்கு வழங்குகிறான்.\n\r\n\n\r\nوَهُوَ عَلَى كُلِّ شَىْءٍ قَدِيرٌ\n\r\n\n\r\n(அவன் அனைத்துப் பொருட்களின் மீதும் பேராற்றல் உடையவன்.) அவன் எதை நாடுகிறானோ அது நடக்கும், அவன் எதை நாடவில்லையோ அது ஒருபோதும் நடக்காது. அவன் கூறினான்:\n\r\n\n\r\nهُوَ الاٌّوَّلُ وَالاٌّخِرُ وَالظَّـهِرُ وَالْبَـطِنُ\n\r\n\n\r\n(அவனே முந்தினவன் (அல்-அவ்வல்), பிந்தினவன் (அல்-ஆகிர்), பகிரங்கமானவன் (அழ்-ழாஹிர்) மற்றும் அந்தரங்கமானவன் (அல்-பாதின்).) இதுதான் இர்பாத் பின் சாரியா (ரழி) அவர்களின் ஹதீஸில் ஓராயிரம் வசனங்களை விடச் சிறந்தது எனக் குறிப்பிடப்பட்ட வசனமாகும்.\n\r\n\n\r\nஅபூ ஸாமில் அவர்கள் கூறியதாக அபூ தாவூத் பதிவு செய்துள்ளார்: \"நான் இப்னு அப்பாஸ் (ரழி) அவர்களிடம், என் உள்ளத்தில் ஏதோ ஒரு சஞ்சலத்தை (சந்தேகத்தை) உணர்வதாகக் கூறினேன். அதற்கு அவர்கள் 'சந்தேகங்களா?' என்று கேட்டுவிட்டுச் சிரித்தார்கள். பிறகு, 'யாரும் இதிலிருந்து தப்ப முடியாது' என்று கூறிவிட்டு, கண்ணியமிக்க அல்லாஹ் கூறிய இந்த வசனத்தை ஓதினார்கள்:\n\r\n\n\r\nفَإِن كُنتَ فِي شَكٍّ مِّمَّآ أَنزَلْنَآ إِلَيْكَ فَاسْأَلِ الَّذِينَ يَقْرَءُونَ الْكِتَـبَ مِن قَبْلِكَ لَقَدْ جَآءَكَ الْحَقُّ مِن رَّبِّكَ\n\r\n\n\r\n(எனவே, நாம் உமக்கு அருளிய வஹீ (இறைச்செய்தி)யைப் பற்றி நீர் சந்தேகத்தில் இருந்தால், உமக்கு முன்னுள்ள வேதத்தை ஓதுகின்றவர்களிடம் கேட்டுப்பாரும். நிச்சயமாக உம் இறைவனிடமிருந்து உம்மிடம் சத்தியம் வந்துள்ளது.) (10:94)\" பிறகு அவர்கள் என்னிடம், \"உமது உள்ளத்தில் இதுபோன்ற எதையேனும் நீர் உணர்ந்தால், இந்த வசனத்தை ஓதுவீராக\" என்று கூறினார்கள்:\n\r\n\n\r\nهُوَ الاٌّوَّلُ وَالاٌّخِرُ وَالظَّـهِرُ وَالْبَـطِنُ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ\n\r\n\n\r\n(அவனே முந்தினவன், பிந்தினவன், பகிரங்கமானவன் மற்றும் அந்தரங்கமானவன். மேலும் அவன் அனைத்துப் பொருட்களையும் நன்கறிந்தவன்.)\" இந்த வசனத்தின் விளக்கத்தில் தஃப்ஸீர் அறிஞர்களிடமிருந்து பத்திற்கும் மேற்பட்ட கருத்துக்கள் பெறப்பட்டுள்ளன.\n\r\n\n\r\nஅல்-புகாரீ கூறுகிறார்: யஹ்யா அவர்கள் கூறினார்கள், \"அழ்-ழாஹிர்: அனைத்துப் பொருட்களையும் அறிந்தவன், அல்-பாதின்: அனைத்துப் பொருட்களையும் அறிந்தவன்.\" எமது ஆசிரியர் அல்-ஹாஃபிழ் அல்-மிஸ்ஸீ அவர்கள் கூறினார்கள்: \"இதில் குறிப்பிடப்படும் யஹ்யா என்பவர் 'மஆனில் குர்ஆன்' என்ற நூலை எழுதிய இப்னு ஸியாத் அல்-ஃபர்ரா ஆவார்.\"\n\r\n\n\r\nஇது குறித்து பல ஹதீஸ்கள் வந்துள்ளன. அவற்றில் ஒன்றாக, அபூ ஹுரைரா (ரழி) அவர்கள் அறிவித்ததை இமாம் அஹ்மத் பதிவு செய்துள்ளார்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் படுக்கைக்குச் செல்லும்போது இந்தத் துஆவை ஓதுவார்கள்:\n\r\n\n\r\n«اللَّهُمَّ رَبَّ السَّموَاتِ السَّبْعِ، وَرَبَّ الْعَرْشِ الْعَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، مُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ وَالْفُرْقَانِ، فَالِقَ الْحَبِّ وَالنَّوَى، لَا إِلهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ، أَنْتَ الْأَوَّلُ لَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ لَيْسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ لَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ لَيْسَ دُونَكَ شَيْءٌ. اقْضِ عَنَّا الدَّيْنَ، وَأَغْنِنَا مِنَ الْفَقْر»\n\r\n\n\r\n(யா அல்லாஹ்! ஏழு வானங்களின் இறைவனே! மகத்தான அர்ஷின் இறைவனே! எங்களின் இறைவனே! அனைத்துப் பொருட்களின் இறைவனே! தவ்ராத், இன்ஜீல் மற்றும் ஃபுர்கானை இறக்கி வைத்தவனே! தானியங்களையும் விதைகளையும் பிளப்பவனே! வணக்கத்திற்குரியவன் நீயைத் தவிர வேறு யாருமில்லை; எவற்றின் முன்நெற்றியை நீ பிடித்துக் கொண்டிருக்கின்றாயோ (உன் கட்டுப்பாட்டில் உள்ளதோ) அத்தகைய அனைத்துப் பொருட்களின் தீங்கிலிருந்தும் உன்னிடம் நான் பாதுகாப்புத் தேடுகிறேன். யா அல்லாஹ்! நீயே முந்தினவன் (அல்-அவ்வல்), உனக்கு முன்னால் எதுவுமில்லை. நீயே பிந்தினவன் (அல்-ஆகிர்), உனக்குப் பின்னால் எதுவுமில்லை. நீயே மேலானவன்/பகிரங்கமானவன் (அழ்-ழாஹிர்), உனக்கு மேலாக எதுவுமில்லை. நீயே நெருக்கமானவன்/அந்தரங்கமானவன் (அல்-பாதின்), உனக்குக் கீழே எதுவுமில்லை. எங்களது கடனைத் தீர்ப்பாயாக, வறுமையிலிருந்து எங்களை விடுவித்துச் செல்வந்தர்களாக்குவாயாக.)\n\r\n\n\r\nஇமாம் முஸ்லிம் அவர்கள் ஸஹ்ல் வழியாகப் பதிவு செய்துள்ள ஹதீஸில் ஸஹ்ல் கூறுகிறார்: \"நாங்கள் தூங்கச் செல்லும்போது எங்களை வலது பக்கமாக ஒருக்களித்துப் படுக்குமாறு அபூ ஸாலிஹ் அவர்கள் பணிப்பார்கள். பிறகு இவ்வாறு கூறச் சொல்வார்கள்:\n\r\n\n\r\n«اللَّهُمَّ رَبَّ السَّموَاتِ وَرَبَّ الْأَرْضِ وَرَبَّ الْعَرْشِ الْعَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، فَالِقَ الْحَبِّ وَالنَّوَى، وَمُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ وَالْفُرْقَانِ، أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ ذِي شَرٍّ أَنْتَ آخِذٌ بِنَاصِيَتِهِ، اللَّهُمَّ أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ عَنَّا الدَّيْنَ، وَأَغْنِنَا مِنَ الْفَقْر»\n\r\n\n\r\n(யா அல்லாஹ்! வானங்களின் இறைவனே! பூமியின் இறைவனே! மகத்தான அர்ஷின் இறைவனே! எங்களின் இறைவனே! அனைத்துப் பொருட்களின் இறைவனே! தானியத்தையும் விதைகளையும் பிளப்பவனே! தவ்ராத், இன்ஜீல் மற்றும் ஃபுர்கானை இறக்கி வைத்தவனே! எவற்றின் முன்நெற்றியை நீ பிடித்துக் கொண்டிருக்கின்றாயோ, அத்தகைய தீயவை அனைத்தின் தீங்கிலிருந்தும் உன்னிடம் நான் பாதுகாப்புத் தேடுகிறேன். யா அல்லாஹ்! நீயே முந்தினவன், உனக்கு முன்னால் எதுவுமில்லை. நீயே பிந்தினவன், உனக்குப் பின்னால் எதுவுமில்லை. நீயே மேலானவன், உனக்கு மேலாக எதுவுமில்லை. நீயே அந்தரங்கமானவன், உனக்குக் கீழே எதுவுமில்லை. எங்களது கடனைத் தீர்ப்பாயாக, வறுமையிலிருந்து எங்களை விடுவித்துச் செல்வந்தர்களாக்குவாயாக.) அபூ ஸாலிஹ் அவர்கள் இதனை அபூ ஹுரைரா (ரழி) அவர்கள் வழியாக நபி (ஸல்) அவர்களிடமிருந்து அறிவிப்பார்கள்.\""},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=57&ayah=6\" class=\"link\">57:6</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 57:6 ஐ பார்க்கவும்"},"5":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=57&ayah=6\" class=\"link\">57:6</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 57:6 ஐ பார்க்கவும்"},"6":{"html":"<strong>அல்லாஹ்வின் ஞானம், ஆற்றல் மற்றும் அரசாட்சி எல்லையற்றவை</strong><br />\r\n<br />\r\nவானங்களையும், பூமியையும், அவற்றுக்கு இடைப்பட்டவற்றையும் ஆறு நாட்களில் படைத்து, பின்னர் அர்ஷின் (சிம்மாசனத்தின்) மீது உயர்ந்ததாக உயர்ந்தோன் அல்லாஹ் கூறுகிறான். இதனைப் பற்றி நாம் ஏற்கனவே ஸூரத்துல் அஃராஃபின் விளக்கவுரையில் விவாதித்துள்ளோம், எனவே அதன் பொருளை இங்கு மீண்டும் குறிப்பிட வேண்டிய அவசியமில்லை. அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَلِجُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span><br />\r\n(பூமிக்குள் நுழைபவற்றை அவன் அறிகிறான்) என்பது, பூமியின் மேற்பரப்பிற்குள் செல்லும் விதைகள் மற்றும் நீர்த்துளிகளின் அளவைப் பற்றிய அவனது ஞானத்தைக் குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يَخْرُجُ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span><br />\r\n(மேலும் அதிலிருந்து வெளிவருபவற்றையும்) என்பது செடி கொடிகள், தாவரங்கள் மற்றும் கனிகளைக் குறிக்கிறது. உயர்ந்தோன் அல்லாஹ் மற்றொரு வசனத்தில் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَعِندَهُ</span> <span class=\"quran-arabic-font text-success\">مَفَاتِحُ</span> <span class=\"quran-arabic-font text-success\">الْغَيْبِ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُهَآ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">وَيَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْبَرِّ</span> <span class=\"quran-arabic-font text-success\">وَالْبَحْرِ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَسْقُطُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">وَرَقَةٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُهَا</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">حَبَّةٍ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ظُلُمَاتِ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">رَطْبٍ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَابِسٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">كِتَابٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span><br />\r\n(மறைவானவற்றின் திறவுகோல்கள் அவனிடமே உள்ளன; அவனைத் தவிர வேறு எவரும் அவற்றை அறியார். தரையிலும் கடலிலும் உள்ளவற்றை அவன் அறிகிறான்; அவனுக்குத் தெரியாமல் ஓர் இலை கூட உதிர்வதில்லை. பூமியின் இருள்களில் உள்ள ஒரு தானியமானாலும், பசுமையானதோ அல்லது காய்ந்ததோ எதுவானாலும் அவை தெளிவான ஒரு பதிவேட்டில் இல்லாமல் இல்லை.) (<a href=\"qurandisp.php?sura=6&ayah=59\" class=\"link\">6:59</a>) அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يَنزِلُ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَاءِ</span><br />\r\n(மேலும் வானத்திலிருந்து இறங்குபவற்றையும்) என்பது மழை, பனி, ஆலங்கட்டி மற்றும் கண்ணியமிக்க வானவர்களால் கொண்டு வரப்படும் அல்லாஹ்வின் முடிவுகள் மற்றும் கட்டளைகள் என வானத்திலிருந்து இறங்குவதாக அல்லாஹ் தீர்மானிக்கும் அனைத்தையும் குறிக்கிறது. அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يَعْرُجُ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span><br />\r\n(மேலும் அதன்பால் ஏறிச் செல்பவற்றையும்) என்பது வானவர்களையும் மனிதர்களின் செயல்களையும் குறிக்கிறது. ஸஹீஹ் நூல்களில் இடம்பெற்றுள்ள ஒரு ஹதீஸில் நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يُرْفَعُ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">عَمَلُ</span> <span class=\"quran-arabic-font text-success\">اللَّيْلِ</span> <span class=\"quran-arabic-font text-success\">قَبْلَ</span> <span class=\"quran-arabic-font text-success\">النَّهَارِ،</span> <span class=\"quran-arabic-font text-success\">وَعَمَلُ</span> <span class=\"quran-arabic-font text-success\">النَّهَارِ</span> <span class=\"quran-arabic-font text-success\">قَبْلَ</span> <span class=\"quran-arabic-font text-success\">اللَّيْل</span>»<br />\r\n(பகல் வருவதற்கு முன்பே இரவின் செயல்களும், இரவு வருவதற்கு முன்பே பகலின் செயல்களும் அவனிடம் உயர்த்தப்படுகின்றன.) அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">مَعَكُمْ</span> <span class=\"quran-arabic-font text-success\">أَيْنَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span> <span class=\"quran-arabic-font text-success\">بَصِيرٌ</span><br />\r\n(நீங்கள் எங்கிருந்தாலும் அவன் உங்களுடன் இருக்கிறான். மேலும் அல்லாஹ் நீங்கள் செய்பவற்றை உற்று நோக்குபவன்.) அதாவது, நீங்கள் தரையிலோ அல்லது கடலிலோ, இரவிலோ அல்லது பகலிலோ, வீட்டிலோ அல்லது திறந்த வெளியிலோ அல்லது பாலைவனத்திலோ என எங்கிருந்தாலும் அவன் உங்களைக் கண்காணித்துக் கொண்டும் உங்கள் செயல்களுக்குச் சாட்சியாகவும் இருக்கிறான். இவை அனைத்தும் அவனது ஞானத்திற்கு முன்னால் சமமானவையே; இவை யாவும் அவனது பார்வைக்கும் செவிக்கும் உட்பட்டவை. அவன் உங்கள் பேச்சைக் கேட்கிறான், நீங்கள் இருக்குமிடத்தைப் பார்க்கிறான். அவன் உங்கள் ரகசியங்களையும் பகிரங்கமான பேச்சுகளையும் அறிகிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَلَا</span> <span class=\"quran-arabic-font text-success\">إِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">يَثْنُونَ</span> <span class=\"quran-arabic-font text-success\">صُدُورَهُمْ</span> <span class=\"quran-arabic-font text-success\">لِيَسْتَخْفُواْ</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">أَلَا</span> <span class=\"quran-arabic-font text-success\">حِينَ</span> <span class=\"quran-arabic-font text-success\">يَسْتَغْشُونَ</span> <span class=\"quran-arabic-font text-success\">ثِيَابَهُمْ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يُسِرُّونَ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يُعْلِنُونَ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلِيمٌ</span> <span class=\"quran-arabic-font text-success\">بِذَاتِ</span> <span class=\"quran-arabic-font text-success\">الصُّدُورِ</span><br />\r\n(அறிந்து கொள்ளுங்கள்! நிச்சயமாக அவர்கள் அவனிடமிருந்து தங்களை மறைத்துக் கொள்வதற்காகத் தங்கள் நெஞ்சங்களை (மடக்கிக்) குறுக்கிக் கொள்கிறார்கள். கவனிங்கள்! அவர்கள் தங்கள் ஆடைகளால் தங்களை மூடிக்கொள்ளும் போதும், அவர்கள் எதை மறைக்கிறார்கள், எதை வெளிப்படுத்துகிறார்கள் என்பதை அவன் அறிகிறான். நிச்சயமாக அவன் இதயங்களில் உள்ளவற்றை நன்கு அறிபவன்.) (<a href=\"qurandisp.php?sura=11&ayah=5\" class=\"link\">11:5</a>) உயர்ந்தோன் அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سَوَاءٌ</span> <span class=\"quran-arabic-font text-success\">مِّنْكُمْ</span> <span class=\"quran-arabic-font text-success\">مَّنْ</span> <span class=\"quran-arabic-font text-success\">أَسَرَّ</span> <span class=\"quran-arabic-font text-success\">الْقَوْلَ</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">جَهَرَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">مُسْتَخْفٍ</span> <span class=\"quran-arabic-font text-success\">بِاللَّيْلِ</span> <span class=\"quran-arabic-font text-success\">وَسَارِبٌ</span> <span class=\"quran-arabic-font text-success\">بِالنَّهَارِ</span><br />\r\n(உங்களில் எவர் பேச்சை ரகசியமாக வைத்துக் கொண்டாலும், அல்லது எவர் அதை பகிரங்கமாக வெளியிட்டாலும், எவர் இரவில் மறைந்திருப்பாரோ அல்லது எவர் பகலில் நடமாடிக் கொண்டிருப்பாரோ, (அவர்கள் அனைவரும் அல்லாஹ்வுக்குச்) சமமானவர்களே.) (<a href=\"qurandisp.php?sura=13&ayah=10\" class=\"link\">13:10</a>) நிச்சயமாக, அல்லாஹ்வைத் தவிர வணக்கத்திற்குரிய இறைவன் வேறில்லை. ஸஹீஹ் நூலில் ஒரு ஹதீஸ் இடம்பெற்றுள்ளது; அதில் ஜிப்ரீல் (அலை) அவர்கள் இஹ்ஸான் பற்றி கேட்டபோது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவ்வாறு பதிலளித்தார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">تَعْبُدَ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">كَأَنَّكَ</span> <span class=\"quran-arabic-font text-success\">تَرَاهُ،</span> <span class=\"quran-arabic-font text-success\">فَإِنْ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">تَكُنْ</span> <span class=\"quran-arabic-font text-success\">تَرَاهُ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">يَرَاك</span>»<br />\r\n(அல்லாஹ்வை நீ பார்ப்பதைப் போன்ற உணர்வுடன் அவனை வணங்குவதாகும்; நீ அவனைப் பார்க்காவிட்டாலும், நிச்சயமாக அவன் உன்னைப் பார்க்கிறான்.) அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مُلْكُ</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَإِلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">تُرْجَعُ</span> <span class=\"quran-arabic-font text-success\">الْأُمُورُ</span><br />\r\n(வானங்கள் மற்றும் பூமியின் ஆட்சி அவனுக்கே உரியது. மேலும் காரியங்கள் அனைத்தும் அல்லாஹ்விடமே திருப்பப்படும்.) இவ்வுலக வாழ்விற்கும் மறுமைக்கும் அல்லாஹ்வே அரசன் மற்றும் உரிமையாளன் என்பதை இது உறுதிப்படுத்துகிறது. அல்லாஹ் மற்றொரு வசனத்தில் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">لَلْآخِرَةَ</span> <span class=\"quran-arabic-font text-success\">وَالْأُولَى</span><br />\r\n(நிச்சயமாக மறுமையும் இம்மையுமான இரு உலகங்களும் நமக்கே சொந்தமானவை.) (<a href=\"qurandisp.php?sura=92&ayah=13\" class=\"link\">92:13</a>) நிச்சயமாக அல்லாஹ் இப்பண்பிற்காகப் புகழப்படுகிறான். அவன் மற்ற வசனங்களில் கூறியது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">إِلَـهَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الْحَمْدُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأُولَى</span> <span class=\"quran-arabic-font text-success\">وَالْآخِرَةِ</span><br />\r\n(அவனே அல்லாஹ்; அவனைத் தவிர வேறு இறைவன் இல்லை; இம்மையிலும் மறுமையிலும் புகழனைத்தும் அவனுக்கே உரியன.) (<a href=\"qurandisp.php?sura=28&ayah=70\" class=\"link\">28:70</a>), மேலும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الْحَمْدُ</span> <span class=\"quran-arabic-font text-success\">لِلَّهِ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَلَهُ</span> <span class=\"quran-arabic-font text-success\">الْحَمْدُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْآخِرَةِ</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْحَكِيمُ</span> <span class=\"quran-arabic-font text-success\">الْخَبِيرُ</span><br />\r\n(புகழ் அனைத்தும் அல்லாஹ்வுக்கே உரியது; வானங்களிலும் பூமியிலும் உள்ளவை அனைத்தும் அவனுக்கே உரியன. மறுமையிலும் புகழ் அனைத்தும் அவனுக்கே உரியது; அவன் ஞானமிக்கவன்; (யாவற்றையும்) நன்கறிந்தவன்.) (<a href=\"qurandisp.php?sura=34&ayah=1\" class=\"link\">34:1</a>)<br />\r\n<br />\r\nவானங்களிலும் பூமியிலும் உள்ள அனைத்தையும் அல்லாஹ்வே சொந்தமாகக் கொண்டுள்ளான். அவற்றில் வசிப்பவர்கள் அனைவரும் அவனது அடிமைகளே, அவனுக்குப் பணிந்தவர்களே. அவன் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُلُّ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">آتِي</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">عَبْداً</span> - <span class=\"quran-arabic-font text-success\">لَقَدْ</span> <span class=\"quran-arabic-font text-success\">أَحْصَاهُمْ</span> <span class=\"quran-arabic-font text-success\">وَعَدَّهُمْ</span> <span class=\"quran-arabic-font text-success\">عَدّاً</span> - <span class=\"quran-arabic-font text-success\">وَكُلُّهُمْ</span> <span class=\"quran-arabic-font text-success\">آتِيهِ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ</span> <span class=\"quran-arabic-font text-success\">فَرْداً</span><br />\r\n(வானங்களிலும் பூமியிலும் உள்ள எவரும் அளவற்ற அருளாளனிடம் அடிமையாகவே வருவர். நிச்சயமாக அவன் அவர்களைச் சூழ்ந்திருக்கிறான்; அவர்களைத் துல்லியமாக எண்ணி வைத்திருக்கிறான். அவர்கள் ஒவ்வொருவரும் மறுமை நாளில் அவனிடம் தனித்தனியாக வருவார்கள்.) (<a href=\"qurandisp.php?sura=19&ayah=93\" class=\"link\">19:93</a>-95)<br />\r\n<br />\r\nஇதனால்தான் அல்லாஹ் இங்கு கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">تُرْجَعُ</span> <span class=\"quran-arabic-font text-success\">الْأُمُورُ</span><br />\r\n(மேலும் காரியங்கள் அனைத்தும் அல்லாஹ்விடமே திருப்பப்படும்.) அதாவது, மறுமை நாளில் அனைத்துக் காரியங்களும் அவனிடம் கொண்டு செல்லப்படும், அவன் தனது படைப்புகளுக்குத் தான் நாடியபடி தீர்ப்பளிப்பான். நிச்சயமாக அவன் மகா நீதியாளன், அவன் எவருக்கும் அணுவளவு கூட அநீதி இழைக்க மாட்டான்; யாரேனும் ஒரு நற்செயல் செய்திருந்தால், அல்லாஹ் அதனைப் பத்து மடங்கு வரை பெருக்குவான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيُؤْتِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">لَّدُنْهُ</span> <span class=\"quran-arabic-font text-success\">أَجْراً</span> <span class=\"quran-arabic-font text-success\">عَظِيماً</span><br />\r\n(மேலும் அவன் தன்னிடமிருந்து மகத்தான கூலியையும் வழங்குகிறான்.) (<a href=\"qurandisp.php?sura=4&ayah=40\" class=\"link\">4:40</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَنَضَعُ</span> <span class=\"quran-arabic-font text-success\">الْمَوَازِينَ</span> <span class=\"quran-arabic-font text-success\">الْقِسْطَ</span> <span class=\"quran-arabic-font text-success\">لِيَوْمِ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ</span> <span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">تُظْلَمُ</span> <span class=\"quran-arabic-font text-success\">نَفْسٌ</span> <span class=\"quran-arabic-font text-success\">شَيْئاً</span> <span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">مِثْقَالَ</span> <span class=\"quran-arabic-font text-success\">حَبَّةٍ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">خَرْدَلٍ</span> <span class=\"quran-arabic-font text-success\">أَتَيْنَا</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">وَكَفَى</span> <span class=\"quran-arabic-font text-success\">بِنَا</span> <span class=\"quran-arabic-font text-success\">حَاسِبِينَ</span><br />\r\n(மேலும் மறுமை நாளில் நீதியான தராசுகளை நாம் நிறுவுவோம்; எந்த ஓர் ஆத்மாவும் எவ்விதத்திலும் அநீதி இழைக்கப்பட மாட்டாது. ஒரு கடுகு விதையளவு எடையுள்ளதாக இருப்பினும் அதையும் நாம் கொண்டு வருவோம்; கணக்கெடுக்க நாமே போதுமானவர்கள்.) (<a href=\"qurandisp.php?sura=21&ayah=47\" class=\"link\">21:47</a>) அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يُولِجُ</span> <span class=\"quran-arabic-font text-success\">اللَّيْلَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">النَّهَارِ</span> <span class=\"quran-arabic-font text-success\">وَيُولِجُ</span> <span class=\"quran-arabic-font text-success\">النَّهَارَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">اللَّيْلِ</span><br />\r\n(அவன் இரவைப் பகலில் புகுத்துகிறான்; பகலை இரவில் புகுத்துகிறான்.) அதாவது, தனது படைப்புகளில் அவன் நாடியதைச் செய்கிறான். இரவையும் பகலையும் ஒன்றன்பின் ஒன்றாக மாற்றி அமைத்து, தனது ஞானத்தின்படி அவன் நாடியவாறு அவற்றை அளவிடுகிறான். சில நேரங்களில் அவன் இரவைப் பகலை விட நீளமாக்குகிறான், சில நேரங்களில் அதற்கு நேர்மாறாகச் செய்கிறான். சில நேரங்களில் இரவையும் பகலையும் சமமாக ஆக்குகிறான். சில சமயம் குளிர் காலமாகவும், பின்னர் அதனை வசந்த காலமாகவும், பிறகு கோடை மற்றும் இலையுதிர் காலமாகவும் மாற்றுகிறான். இவை அனைத்தையும் அவன் தனது ஞானத்தின் மூலமும், தனது படைப்பில் உள்ள ஒவ்வொன்றையும் சரியான அளவோடும் செய்கிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">عَلِيمٌ</span> <span class=\"quran-arabic-font text-success\">بِذَاتِ</span> <span class=\"quran-arabic-font text-success\">الصُّدُورِ</span><br />\r\n(மேலும் அவன் உள்ளங்களில் உள்ளவற்றை நன்கு அறிபவன்.) ரகசியங்கள் எவ்வளவு மறைக்கப்பட்டிருந்தாலும் அவன் அவற்றை அறிகிறான்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"அல்லாஹ்வின் ஞானம், ஆற்றல் மற்றும் அரசாட்சி எல்லையற்றவை\n\r\n\n\r\nவானங்களையும், பூமியையும், அவற்றுக்கு இடைப்பட்டவற்றையும் ஆறு நாட்களில் படைத்து, பின்னர் அர்ஷின் (சிம்மாசனத்தின்) மீது உயர்ந்ததாக உயர்ந்தோன் அல்லாஹ் கூறுகிறான். இதனைப் பற்றி நாம் ஏற்கனவே ஸூரத்துல் அஃராஃபின் விளக்கவுரையில் விவாதித்துள்ளோம், எனவே அதன் பொருளை இங்கு மீண்டும் குறிப்பிட வேண்டிய அவசியமில்லை. அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nيَعْلَمُ مَا يَلِجُ فِي الْأَرْضِ\n\r\n(பூமிக்குள் நுழைபவற்றை அவன் அறிகிறான்) என்பது, பூமியின் மேற்பரப்பிற்குள் செல்லும் விதைகள் மற்றும் நீர்த்துளிகளின் அளவைப் பற்றிய அவனது ஞானத்தைக் குறிக்கிறது.\n\r\n\n\r\nوَمَا يَخْرُجُ مِنْهَا\n\r\n(மேலும் அதிலிருந்து வெளிவருபவற்றையும்) என்பது செடி கொடிகள், தாவரங்கள் மற்றும் கனிகளைக் குறிக்கிறது. உயர்ந்தோன் அல்லாஹ் மற்றொரு வசனத்தில் கூறினான்:\n\r\n\n\r\nوَعِندَهُ مَفَاتِحُ الْغَيْبِ لاَ يَعْلَمُهَآ إِلاَّ هُوَ وَيَعْلَمُ مَا فِي الْبَرِّ وَالْبَحْرِ وَمَا تَسْقُطُ مِن وَرَقَةٍ إِلاَّ يَعْلَمُهَا وَلاَ حَبَّةٍ فِي ظُلُمَاتِ الْأَرْضِ وَلاَ رَطْبٍ وَلاَ يَابِسٍ إِلاَّ فِي كِتَابٍ مُّبِينٍ\n\r\n(மறைவானவற்றின் திறவுகோல்கள் அவனிடமே உள்ளன; அவனைத் தவிர வேறு எவரும் அவற்றை அறியார். தரையிலும் கடலிலும் உள்ளவற்றை அவன் அறிகிறான்; அவனுக்குத் தெரியாமல் ஓர் இலை கூட உதிர்வதில்லை. பூமியின் இருள்களில் உள்ள ஒரு தானியமானாலும், பசுமையானதோ அல்லது காய்ந்ததோ எதுவானாலும் அவை தெளிவான ஒரு பதிவேட்டில் இல்லாமல் இல்லை.) (6:59) அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nوَمَا يَنزِلُ مِنَ السَّمَاءِ\n\r\n(மேலும் வானத்திலிருந்து இறங்குபவற்றையும்) என்பது மழை, பனி, ஆலங்கட்டி மற்றும் கண்ணியமிக்க வானவர்களால் கொண்டு வரப்படும் அல்லாஹ்வின் முடிவுகள் மற்றும் கட்டளைகள் என வானத்திலிருந்து இறங்குவதாக அல்லாஹ் தீர்மானிக்கும் அனைத்தையும் குறிக்கிறது. அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nوَمَا يَعْرُجُ فِيهَا\n\r\n(மேலும் அதன்பால் ஏறிச் செல்பவற்றையும்) என்பது வானவர்களையும் மனிதர்களின் செயல்களையும் குறிக்கிறது. ஸஹீஹ் நூல்களில் இடம்பெற்றுள்ள ஒரு ஹதீஸில் நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«يُرْفَعُ إِلَيْهِ عَمَلُ اللَّيْلِ قَبْلَ النَّهَارِ، وَعَمَلُ النَّهَارِ قَبْلَ اللَّيْل»\n\r\n(பகல் வருவதற்கு முன்பே இரவின் செயல்களும், இரவு வருவதற்கு முன்பே பகலின் செயல்களும் அவனிடம் உயர்த்தப்படுகின்றன.) அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَهُوَ مَعَكُمْ أَيْنَ مَا كُنتُمْ وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ\n\r\n(நீங்கள் எங்கிருந்தாலும் அவன் உங்களுடன் இருக்கிறான். மேலும் அல்லாஹ் நீங்கள் செய்பவற்றை உற்று நோக்குபவன்.) அதாவது, நீங்கள் தரையிலோ அல்லது கடலிலோ, இரவிலோ அல்லது பகலிலோ, வீட்டிலோ அல்லது திறந்த வெளியிலோ அல்லது பாலைவனத்திலோ என எங்கிருந்தாலும் அவன் உங்களைக் கண்காணித்துக் கொண்டும் உங்கள் செயல்களுக்குச் சாட்சியாகவும் இருக்கிறான். இவை அனைத்தும் அவனது ஞானத்திற்கு முன்னால் சமமானவையே; இவை யாவும் அவனது பார்வைக்கும் செவிக்கும் உட்பட்டவை. அவன் உங்கள் பேச்சைக் கேட்கிறான், நீங்கள் இருக்குமிடத்தைப் பார்க்கிறான். அவன் உங்கள் ரகசியங்களையும் பகிரங்கமான பேச்சுகளையும் அறிகிறான்.\n\r\n\n\r\nأَلَا إِنَّهُمْ يَثْنُونَ صُدُورَهُمْ لِيَسْتَخْفُواْ مِنْهُ أَلَا حِينَ يَسْتَغْشُونَ ثِيَابَهُمْ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ إِنَّهُ عَلِيمٌ بِذَاتِ الصُّدُورِ\n\r\n(அறிந்து கொள்ளுங்கள்! நிச்சயமாக அவர்கள் அவனிடமிருந்து தங்களை மறைத்துக் கொள்வதற்காகத் தங்கள் நெஞ்சங்களை (மடக்கிக்) குறுக்கிக் கொள்கிறார்கள். கவனிங்கள்! அவர்கள் தங்கள் ஆடைகளால் தங்களை மூடிக்கொள்ளும் போதும், அவர்கள் எதை மறைக்கிறார்கள், எதை வெளிப்படுத்துகிறார்கள் என்பதை அவன் அறிகிறான். நிச்சயமாக அவன் இதயங்களில் உள்ளவற்றை நன்கு அறிபவன்.) (11:5) உயர்ந்தோன் அல்லாஹ் கூறினான்:\n\r\n\n\r\nسَوَاءٌ مِّنْكُمْ مَّنْ أَسَرَّ الْقَوْلَ وَمَنْ جَهَرَ بِهِ وَمَنْ هُوَ مُسْتَخْفٍ بِاللَّيْلِ وَسَارِبٌ بِالنَّهَارِ\n\r\n(உங்களில் எவர் பேச்சை ரகசியமாக வைத்துக் கொண்டாலும், அல்லது எவர் அதை பகிரங்கமாக வெளியிட்டாலும், எவர் இரவில் மறைந்திருப்பாரோ அல்லது எவர் பகலில் நடமாடிக் கொண்டிருப்பாரோ, (அவர்கள் அனைவரும் அல்லாஹ்வுக்குச்) சமமானவர்களே.) (13:10) நிச்சயமாக, அல்லாஹ்வைத் தவிர வணக்கத்திற்குரிய இறைவன் வேறில்லை. ஸஹீஹ் நூலில் ஒரு ஹதீஸ் இடம்பெற்றுள்ளது; அதில் ஜிப்ரீல் (அலை) அவர்கள் இஹ்ஸான் பற்றி கேட்டபோது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவ்வாறு பதிலளித்தார்கள்:\n\r\n\n\r\n«أَنْ تَعْبُدَ اللهَ كَأَنَّكَ تَرَاهُ، فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاك»\n\r\n(அல்லாஹ்வை நீ பார்ப்பதைப் போன்ற உணர்வுடன் அவனை வணங்குவதாகும்; நீ அவனைப் பார்க்காவிட்டாலும், நிச்சயமாக அவன் உன்னைப் பார்க்கிறான்.) அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nلَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ وَإِلَى اللَّهِ تُرْجَعُ الْأُمُورُ\n\r\n(வானங்கள் மற்றும் பூமியின் ஆட்சி அவனுக்கே உரியது. மேலும் காரியங்கள் அனைத்தும் அல்லாஹ்விடமே திருப்பப்படும்.) இவ்வுலக வாழ்விற்கும் மறுமைக்கும் அல்லாஹ்வே அரசன் மற்றும் உரிமையாளன் என்பதை இது உறுதிப்படுத்துகிறது. அல்லாஹ் மற்றொரு வசனத்தில் கூறினான்:\n\r\n\n\r\nوَإِنَّ لَنَا لَلْآخِرَةَ وَالْأُولَى\n\r\n(நிச்சயமாக மறுமையும் இம்மையுமான இரு உலகங்களும் நமக்கே சொந்தமானவை.) (92:13) நிச்சயமாக அல்லாஹ் இப்பண்பிற்காகப் புகழப்படுகிறான். அவன் மற்ற வசனங்களில் கூறியது போல:\n\r\n\n\r\nوَهُوَ اللَّهُ لَا إِلَـهَ إِلاَّ هُوَ لَهُ الْحَمْدُ فِي الْأُولَى وَالْآخِرَةِ\n\r\n(அவனே அல்லாஹ்; அவனைத் தவிர வேறு இறைவன் இல்லை; இம்மையிலும் மறுமையிலும் புகழனைத்தும் அவனுக்கே உரியன.) (28:70), மேலும்:\n\r\n\n\r\nالْحَمْدُ لِلَّهِ الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَلَهُ الْحَمْدُ فِي الْآخِرَةِ وَهُوَ الْحَكِيمُ الْخَبِيرُ\n\r\n(புகழ் அனைத்தும் அல்லாஹ்வுக்கே உரியது; வானங்களிலும் பூமியிலும் உள்ளவை அனைத்தும் அவனுக்கே உரியன. மறுமையிலும் புகழ் அனைத்தும் அவனுக்கே உரியது; அவன் ஞானமிக்கவன்; (யாவற்றையும்) நன்கறிந்தவன்.) (34:1)\n\r\n\n\r\nவானங்களிலும் பூமியிலும் உள்ள அனைத்தையும் அல்லாஹ்வே சொந்தமாகக் கொண்டுள்ளான். அவற்றில் வசிப்பவர்கள் அனைவரும் அவனது அடிமைகளே, அவனுக்குப் பணிந்தவர்களே. அவன் கூறுவது போல:\n\r\n\n\r\nإِن كُلُّ مَن فِي السَّمَاوَاتِ وَالْأَرْضِ إِلاَّ آتِي الرَّحْمَـنِ عَبْداً - لَقَدْ أَحْصَاهُمْ وَعَدَّهُمْ عَدّاً - وَكُلُّهُمْ آتِيهِ يَوْمَ الْقِيَامَةِ فَرْداً\n\r\n(வானங்களிலும் பூமியிலும் உள்ள எவரும் அளவற்ற அருளாளனிடம் அடிமையாகவே வருவர். நிச்சயமாக அவன் அவர்களைச் சூழ்ந்திருக்கிறான்; அவர்களைத் துல்லியமாக எண்ணி வைத்திருக்கிறான். அவர்கள் ஒவ்வொருவரும் மறுமை நாளில் அவனிடம் தனித்தனியாக வருவார்கள்.) (19:93-95)\n\r\n\n\r\nஇதனால்தான் அல்லாஹ் இங்கு கூறினான்:\n\r\n\n\r\nوَإِلَى اللَّهِ تُرْجَعُ الْأُمُورُ\n\r\n(மேலும் காரியங்கள் அனைத்தும் அல்லாஹ்விடமே திருப்பப்படும்.) அதாவது, மறுமை நாளில் அனைத்துக் காரியங்களும் அவனிடம் கொண்டு செல்லப்படும், அவன் தனது படைப்புகளுக்குத் தான் நாடியபடி தீர்ப்பளிப்பான். நிச்சயமாக அவன் மகா நீதியாளன், அவன் எவருக்கும் அணுவளவு கூட அநீதி இழைக்க மாட்டான்; யாரேனும் ஒரு நற்செயல் செய்திருந்தால், அல்லாஹ் அதனைப் பத்து மடங்கு வரை பெருக்குவான்.\n\r\n\n\r\nوَيُؤْتِ مِن لَّدُنْهُ أَجْراً عَظِيماً\n\r\n(மேலும் அவன் தன்னிடமிருந்து மகத்தான கூலியையும் வழங்குகிறான்.) (4:40)\n\r\n\n\r\nوَنَضَعُ الْمَوَازِينَ الْقِسْطَ لِيَوْمِ الْقِيَامَةِ فَلاَ تُظْلَمُ نَفْسٌ شَيْئاً وَإِن كَانَ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ أَتَيْنَا بِهَا وَكَفَى بِنَا حَاسِبِينَ\n\r\n(மேலும் மறுமை நாளில் நீதியான தராசுகளை நாம் நிறுவுவோம்; எந்த ஓர் ஆத்மாவும் எவ்விதத்திலும் அநீதி இழைக்கப்பட மாட்டாது. ஒரு கடுகு விதையளவு எடையுள்ளதாக இருப்பினும் அதையும் நாம் கொண்டு வருவோம்; கணக்கெடுக்க நாமே போதுமானவர்கள்.) (21:47) அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nيُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ\n\r\n(அவன் இரவைப் பகலில் புகுத்துகிறான்; பகலை இரவில் புகுத்துகிறான்.) அதாவது, தனது படைப்புகளில் அவன் நாடியதைச் செய்கிறான். இரவையும் பகலையும் ஒன்றன்பின் ஒன்றாக மாற்றி அமைத்து, தனது ஞானத்தின்படி அவன் நாடியவாறு அவற்றை அளவிடுகிறான். சில நேரங்களில் அவன் இரவைப் பகலை விட நீளமாக்குகிறான், சில நேரங்களில் அதற்கு நேர்மாறாகச் செய்கிறான். சில நேரங்களில் இரவையும் பகலையும் சமமாக ஆக்குகிறான். சில சமயம் குளிர் காலமாகவும், பின்னர் அதனை வசந்த காலமாகவும், பிறகு கோடை மற்றும் இலையுதிர் காலமாகவும் மாற்றுகிறான். இவை அனைத்தையும் அவன் தனது ஞானத்தின் மூலமும், தனது படைப்பில் உள்ள ஒவ்வொன்றையும் சரியான அளவோடும் செய்கிறான்.\n\r\n\n\r\nوَهُوَ عَلِيمٌ بِذَاتِ الصُّدُورِ\n\r\n(மேலும் அவன் உள்ளங்களில் உள்ளவற்றை நன்கு அறிபவன்.) ரகசியங்கள் எவ்வளவு மறைக்கப்பட்டிருந்தாலும் அவன் அவற்றை அறிகிறான்."},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=57&ayah=11\" class=\"link\">57:11</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 57:11 ஐ பார்க்கவும்"},"8":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=57&ayah=11\" class=\"link\">57:11</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 57:11 ஐ பார்க்கவும்"},"9":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=57&ayah=11\" class=\"link\">57:11</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 57:11 ஐ பார்க்கவும்"},"10":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=57&ayah=11\" class=\"link\">57:11</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 57:11 ஐ பார்க்கவும்"},"11":{"html":"<strong>ஈமான் கொள்வதற்கும் செலவு செய்வதற்கும் ஏவுதல்</strong><br />\r\n<br />\r\nமேன்மையும் பாக்கியமும் மிக்க அல்லாஹ், தன் மீதும் தன் தூதர் (ஸல்) மீதும் முழுமையான ஈமான் (நம்பிக்கை) கொள்ளுமாறும், அந்தப் பாதையில் உறுதியாக நிலைத்திருக்குமாறும் கட்டளையிடுகிறான். அல்லாஹ் மனிதர்களை எதற்குப் பொறுப்பாளர்களாக ஆக்கினானோ, உங்களிடம் அவன் ஒப்படைத்துள்ள அந்தச் செல்வத்திலிருந்து செலவு செய்யுமாறு அவன் தூண்டுகிறான். இந்தச் செல்வம் உங்களுக்கு முன்பிருந்தவர்களின் கைகளில் இருந்தது, பின்னர் அது உங்களிடம் கைமாறியது. எனவே, மனிதர்களே! அல்லாஹ் தனக்குக் கீழ்ப்படிவதற்காக உங்களிடம் ஒப்படைத்த செல்வத்திலிருந்து, அவன் கட்டளையிட்டபடி செலவு செய்யுங்கள். இல்லையெனில், இது குறித்து அவன் உங்களுக்கு விதித்தவற்றை நீங்கள் புறக்கணித்ததற்காக அவன் உங்களைக் கேள்வி கேட்டுத் தண்டிப்பான். அல்லாஹ்வின் கூற்று,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مِمَّا</span> <span class=\"quran-arabic-font text-success\">جَعَلَكُم</span> <span class=\"quran-arabic-font text-success\">مُّسْتَخْلَفِينَ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span><br />\r\n<br />\r\n(எதில் அவன் உங்களைப் பிரதிநிதிகளாக ஆக்கினானோ அதிலிருந்து), என்பது, மனிதர்களாகிய நீங்கள் இந்தச் செல்வத்தை வேறொருவரிடம் ஒப்படைத்துவிடுவீர்கள் என்பதைக் குறிக்கிறது. அவ்வாறு நிகழும்போது, உங்களிடமிருந்து வாரிசாகப் பெறுபவர்கள் அந்தச் செல்வத்தைக் கொண்டு அல்லாஹ்வுக்குக் கீழ்ப்படியக்கூடும்; அதன் மூலம் அல்லாஹ் அவர்களுக்கு வழங்கிய அருட்கொடைகளால் உங்களை விட அதிக மகிழ்ச்சியை அவர்கள் பெறலாம். அல்லது அவர்கள் அல்லாஹ்வுக்கு மாறு செய்யலாம்; அவ்வாறாயின் அவர்கள் தீமையும் வரம்பு மீறலும் செய்வதற்கு நீங்கள் உதவியவர் ஆகிவிடுவீர்கள். இமாம் அஹ்மத் அவர்கள் அப்துல்லாஹ் பின் அஷ்-ஷிக்கீர் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஓதிக்கொண்டிருந்தபோது நான் அவர்களிடம் வந்தேன், அவர்கள் கூறினார்கள்:\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَلْهَاكُمُ</span> <span class=\"quran-arabic-font text-success\">التَّكَاثُرُ</span><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَقُولُ</span> <span class=\"quran-arabic-font text-success\">ابْنُ</span> <span class=\"quran-arabic-font text-success\">آدَمَ</span>: <span class=\"quran-arabic-font text-success\">مَالِي</span> <span class=\"quran-arabic-font text-success\">مَالِي،</span> <span class=\"quran-arabic-font text-success\">وَهَلْ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مَالِكَ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">مَاأَكَلْتَ</span> <span class=\"quran-arabic-font text-success\">فَأَفْنَيْتَ،</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">لَبِسْتَ</span> <span class=\"quran-arabic-font text-success\">فَأَبْلَيْتَ،</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">تَصَدَّقْتَ</span> <span class=\"quran-arabic-font text-success\">فَأَمْضَيْتَ؟</span>»<br />\r\n<br />\r\n((பெருமையுடன் எண்ணிக்கையை அதிகரிப்பது உங்களை பராக்காக்கிவிட்டது.) ஆதமின் மகன், 'எனது செல்வம், எனது செல்வம்' என்று உரிமை கோருகிறான். ஆனால் உனது செல்வத்தில் நீ உண்டு அழித்தவை, அல்லது உடுத்திக் கிழித்தவை, அல்லது தர்மம் செய்து மறுமைக்காக அனுப்பி வைத்தவை தவிர உனக்குரியது என்று ஏதேனும் உண்டா?) இமாம் முஸ்லிம் அவர்களும் இதனுடன் பின்வரும் கூடுதல் செய்தியை அறிவித்துள்ளார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">سِوَى</span> <span class=\"quran-arabic-font text-success\">ذلِكَ،</span> <span class=\"quran-arabic-font text-success\">فَذَاهِبٌ</span> <span class=\"quran-arabic-font text-success\">وَتَارِكُهُ</span> <span class=\"quran-arabic-font text-success\">لِلنَّاس</span>»<br />\r\n<br />\r\n(அதைத் தவிர மற்றவற்றை நீ விட்டுவிட்டுப் பிரிந்துவிடுவாய், அவை மற்ற மக்களுக்குப் போய்விடும்.) அல்லாஹ்வின் கூற்று,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">مِنكُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَنفَقُواْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَجْرٌ</span> <span class=\"quran-arabic-font text-success\">كَبِيرٌ</span><br />\r\n<br />\r\n(ஆகவே, உங்களில் எவர் ஈமான் கொண்டு செலவு செய்கிறார்களோ, அவர்களுக்கு மகத்தான நற்கூலி உண்டு.) என்பது ஈமான் கொள்வதையும், நற்செயல்களில் செலவு செய்வதையும் ஊக்குவிக்கிறது. உயர்ந்தோனாகிய அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَالرَّسُولُ</span> <span class=\"quran-arabic-font text-success\">يَدْعُوكُمْ</span> <span class=\"quran-arabic-font text-success\">لِتُؤْمِنُواْ</span> <span class=\"quran-arabic-font text-success\">بِرَبِّكُمْ</span><br />\r\n<br />\r\n(அல்லாஹ்வை நீங்கள் ஈமான் கொள்ளாதிருக்க உங்களுக்கு என்ன நேர்ந்தது? தூதரோ (ஸல்) உங்கள் இறைவனை நீங்கள் ஈமான் கொள்ளுமாறு உங்களை அழைக்கிறார்களே;) இதன் பொருள், \"தூதர் (ஸல்) உங்களுக்கு இடையில் இருந்து, ஈமானின் பக்கம் உங்களை அழைத்து, அவர் கொண்டு வந்ததன் உண்மையை உறுதிப்படுத்தும் தெளிவான சான்றுகளையும் ஆதாரங்களையும் முன்வைக்கும்போது, நீங்கள் ஈமான் கொள்வதை எது தடுக்கிறது?\" என்பதாகும். சஹீஹ் அல்-புகாரியில் ஈமான் பற்றிய அத்தியாயத்தின் விளக்கத்தில், நாம் இந்த ஹதீஸை பல்வேறு அறிவிப்பாளர் தொடர்கள் வழியாகக் குறிப்பிட்டுள்ளோம். ஒரு நாள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தங்கள் தோழர்களிடம் (ஸஹாபாக்கள்) கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَيُّ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">أَعْجَبُ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">إِيمَانًا؟</span>»<br />\r\n<br />\r\n(இறைநம்பிக்கையாளர்களில் யாருடைய ஈமான் உங்களுக்கு மிகவும் ஆச்சரியமானதாகத் தெரிகிறது?) அவர்கள், \"வானவர்கள்\" என்று கூறினார்கள். நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">عِنْدَ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِمْ؟</span>»<br />\r\n<br />\r\n(அவர்கள் தங்கள் இறைவனிடம் இருக்கும்போது, அவர்கள் ஈமான் கொள்ளாமல் எப்படி இருப்பார்கள்?) அவர்கள், \"அப்படியானால் நபிமார்கள் (அலை)\" என்றார்கள். நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَمَالَهُمْ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">وَالْوَحْيُ</span> <span class=\"quran-arabic-font text-success\">يَنْزِلُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ؟</span>»<br />\r\n<br />\r\n(அவர்களுக்கு வஹீ (இறைச்செய்தி) இறங்கிக் கொண்டிருக்கும்போது அவர்கள் ஈமான் கொள்ளாமல் எப்படி இருப்பார்கள்?) அவர்கள், \"அப்படியானால் நாங்கள் தான்\" என்றார்கள். நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَمَالَكُمْ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">وَأَنَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">أَظْهُرِكُمْ؟</span> <span class=\"quran-arabic-font text-success\">وَلكِنْ</span> <span class=\"quran-arabic-font text-success\">أَعْجَبُ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">إِيمَانًا،</span> <span class=\"quran-arabic-font text-success\">قَوْمٌ</span> <span class=\"quran-arabic-font text-success\">يَجِيئُونَ</span> <span class=\"quran-arabic-font text-success\">بَعْدَكُمْ،</span> <span class=\"quran-arabic-font text-success\">يَجِدُونَ</span> <span class=\"quran-arabic-font text-success\">صُحُفًا</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span>»<br />\r\n<br />\r\n(நான் உங்களுக்கு மத்தியில் இருக்கும்போது நீங்கள் ஈமான் கொள்ளாமல் எப்படி இருப்பீர்கள்? உண்மையில் மிகவும் ஆச்சரியமான ஈமான் கொண்டவர்கள் யாரென்றால், உங்களுக்குப் பிறகு வரும் மக்களே; அவர்கள் சில ஏடுகளைக் காண்பார்கள், அதில் உள்ளவற்றை அவர்கள் ஈமான் கொள்வார்கள்.) ஸூரத்துல் பகராவில் அல்லாஹ்வின் பின்வரும் வசனத்தை விளக்கும்போது இந்த ஹதீஸின் ஒரு பகுதியை நாம் குறிப்பிட்டுள்ளோம்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">بِالْغَيْبِ</span><br />\r\n<br />\r\n(அவர்கள் மறைவானவற்றை ஈமான் கொள்வார்கள்.)(<a href=\"qurandisp.php?sura=2&ayah=3\" class=\"link\">2:3</a>). அல்லாஹ்வின் கூற்று,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَدْ</span> <span class=\"quran-arabic-font text-success\">أَخَذَ</span> <span class=\"quran-arabic-font text-success\">مِيثَاقَكُمْ</span><br />\r\n<br />\r\n(மேலும் அவன் உங்களிடம் உறுதிமொழி வாங்கியுள்ளான்,) என்பது அவனுடைய மற்றொரு வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاذْكُرُواْ</span> <span class=\"quran-arabic-font text-success\">نِعْمَةَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">وَمِيثَاقَهُ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">وَاثَقَكُم</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">قُلْتُمْ</span> <span class=\"quran-arabic-font text-success\">سَمِعْنَا</span> <span class=\"quran-arabic-font text-success\">وَأَطَعْنَا</span><br />\r\n<br />\r\n(உங்கள் மீதுள்ள அல்லாஹ்வின் அருட்கொடையையும், 'நாங்கள் செவியுற்றோம், நாங்கள் கீழ்ப்படிந்தோம்' என்று நீங்கள் கூறியபோது, அவன் உங்களிடம் வாங்கிய உறுதிமொழியையும் நினைவு கூருங்கள்.)(<a href=\"qurandisp.php?sura=5&ayah=7\" class=\"link\">5:7</a>). இது நபி (ஸல்) அவர்களுக்கு வழங்கப்படும் விசுவாசப் பிரமாணத்தைக் குறிக்கிறது. இப்னு ஜரீர் அவர்கள், இங்கு குறிப்பிடப்படும் உடன்படிக்கை, மனிதர்கள் அனைவரும் ஆதம் (அலை) அவர்களின் முதுகில் இருந்தபோது அவர்களிடமிருந்து எடுக்கப்பட்டது என்று கூறினார்கள். இது முஜாஹித் அவர்களின் கருத்தும் ஆகும், அல்லாஹ்வே நன்கு அறிந்தவன். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يُنَزِّلُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">عَبْدِهِ</span> <span class=\"quran-arabic-font text-success\">آيَاتٍ</span> <span class=\"quran-arabic-font text-success\">بَيِّنَاتٍ</span><br />\r\n<br />\r\n(அவனே தன் அடியார் மீது தெளிவான வசனங்களை (ஆயத்துகளை) இறக்குகிறான்.) அதாவது தெளிவான சான்றுகள், ஐயமற்ற ஆதாரங்கள் மற்றும் வெளிப்படையான அத்தாட்சிகள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِيُخْرِجَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الظُّلُمَاتِ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">النُّورِ</span><br />\r\n<br />\r\n(அவன் உங்களை இருள்களிலிருந்து ஒளியின் பக்கம் கொண்டு வருவதற்காக.) அறியாமை, நிராகரிப்பு மற்றும் முரண்பாடான கொள்கைகளின் இருள்களிலிருந்து நேர்வழி, உறுதி மற்றும் ஈமானின் ஒளியின் பக்கம் உங்களை இட்டுச் செல்லவே அவன் இவ்வாறு செய்கிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">بِكُمْ</span> <span class=\"quran-arabic-font text-success\">لَرَءُوفٌ</span> <span class=\"quran-arabic-font text-success\">رَّحِيمٌ</span><br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் உங்கள் மீது மிக்க கனிவுடையவன், நிகரற்ற கருணையாளன்.) வேதங்களை அருளியும், மனிதர்களுக்கு வழிகாட்ட தூதர்களை அனுப்பியும், சந்தேகங்களை அகற்றி குழப்பங்களை நீக்கியும் அல்லாஹ் உங்கள் மீது கருணை காட்டுகிறான். முதலில் ஈமான் கொள்ளுமாறும் செலவு செய்யுமாறும் மனிதர்களுக்குக் கட்டளையிட்ட அல்லாஹ், பிறகு ஈமானைப் பெறுவதற்கு இடையில் இருந்த அனைத்துத் தடைகளையும் தான் நீக்கிவிட்டதாகக் கூறி, மீண்டும் அவர்களை ஈமான் கொள்ள ஊக்குவித்தான். அதனைத் தொடர்ந்து மீண்டும் அவர்களைச் செலவு செய்ய அல்லாஹ் தூண்டுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">أَلاَّ</span> <span class=\"quran-arabic-font text-success\">تُنفِقُواْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">سَبِيلِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَلِلَّهِ</span> <span class=\"quran-arabic-font text-success\">مِيرَاثُ</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ</span><br />\r\n<br />\r\n(அல்லாஹ்வின் பாதையில் நீங்கள் செலவு செய்யாதிருக்க உங்களுக்கு என்ன நேர்ந்தது? வானங்கள் மற்றும் பூமியின் வாரிசுரிமை அல்லாஹ்வுக்கே உரியது.) இதன் பொருள், செலவு செய்யுங்கள், வறுமைக்கோ பற்றாக்குறைக்கோ அஞ்சாதீர்கள். நிச்சயமாக, யாருடைய பாதையில் நீங்கள் செலவு செய்கிறீர்களோ அவன் வானங்கள் மற்றும் பூமியின் அரசனும் உரிமையாளனும் ஆவான். கருவூலங்கள் உட்பட அவற்றின் ஒவ்வோர் விவகாரத்திலும் அவனுக்கே முழுமையான அதிகாரம் உள்ளது. அவன் அர்ஷின் உரிமையாளன், அளப்பரிய வல்லமை கொண்டவன். அவனே இவ்வாறு கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَنفَقْتُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">فَهُوَ</span> <span class=\"quran-arabic-font text-success\">يُخْلِفُهُ</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">خَيْرُ</span> <span class=\"quran-arabic-font text-success\">الرَّازِقِينَ</span><br />\r\n<br />\r\n(நீங்கள் எப்பொருளைச் செலவு செய்தாலும், அவன் அதற்குப் பதிலாக வேறொன்றை உங்களுக்குத் தருவான். அவனே வழங்குவோரில் சிறந்தவன்.)(<a href=\"qurandisp.php?sura=34&ayah=39\" class=\"link\">34:39</a>). மேலும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">عِندَكُمْ</span> <span class=\"quran-arabic-font text-success\">يَنفَدُ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">بَاقٍ</span><br />\r\n<br />\r\n(உங்களிடம் இருப்பது தீர்ந்துவிடும், அல்லாஹ்விடம் இருப்பது நிலையானது.)(<a href=\"qurandisp.php?sura=16&ayah=96\" class=\"link\">16:96</a>). எனவே அல்லாஹ்வின் மீது நம்பிக்கை வைத்து அவனைச் சார்ந்திருப்பவர்கள் செலவு செய்வார்கள்; அர்ஷின் உரிமையாளனிடமிருந்து தங்களுக்கு வறுமை வரும் என்று அவர்கள் அஞ்ச மாட்டார்கள். தாங்கள் செலவு செய்யும் ஒவ்வொன்றுக்கும் அல்லாஹ் நிச்சயமாக ஈடுசெய்வான் என்பதை அவர்கள் அறிவார்கள்.<br />\r\n<br />\r\n<strong>மக்கா வெற்றிக்கு முன் செலவு செய்தல் மற்றும் போரிடுவதன் சிறப்புகள்</strong><br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்று,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَسْتَوِى</span> <span class=\"quran-arabic-font text-success\">مِنكُم</span> <span class=\"quran-arabic-font text-success\">مَّنْ</span> <span class=\"quran-arabic-font text-success\">أَنفَقَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِ</span> <span class=\"quran-arabic-font text-success\">الْفَتْحِ</span> <span class=\"quran-arabic-font text-success\">وَقَاتَلَ</span><br />\r\n<br />\r\n(உங்களில் வெற்றிக்கு முன் செலவு செய்து போரிட்டவர்களுக்கு (மற்றவர்கள்) சமமாக மாட்டார்கள்.) அதாவது, மக்கா வெற்றிக்கு முன்னர் செலவு செய்து போரிட்டவர்களுக்கு, அதற்குப் பின்னர் செலவு செய்து போரிட்டவர்கள் சமமாக மாட்டார்கள். மக்கா வெற்றிக்கு முன்னால் முஸ்லிம்களின் நிலைமை மிகவும் கடினமாக இருந்தது; அச்சமயத்தில் உண்மையான இறைப்பற்றுடையவர்கள் மட்டுமே இஸ்லாத்தைத் தழுவினார்கள். மக்கா வெற்றிக்குப் பிறகு, இஸ்லாம் உலகம் முழுவதும் மிக வேகமாகப் பரவியது; மக்கள் கூட்டம் கூட்டமாக அல்லாஹ்வின் மார்க்கத்தில் இணைந்தனர். இதைப் போலவே அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أُولَئِكَ</span> <span class=\"quran-arabic-font text-success\">أَعْظَمُ</span> <span class=\"quran-arabic-font text-success\">دَرَجَةً</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">أَنفَقُواْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدُ</span> <span class=\"quran-arabic-font text-success\">وَقَاتَلُواْ</span> <span class=\"quran-arabic-font text-success\">وَكُلًّا</span> <span class=\"quran-arabic-font text-success\">وَعَدَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الْحُسْنَى</span><br />\r\n<br />\r\n(அவர்கள், பின்னர் செலவு செய்து போரிட்டவர்களை விட அந்தஸ்தில் உயர்ந்தவர்கள். எனினும், அனைவருக்கும் அல்லாஹ் நன்மையானதையே (நற்கூலியை) வாக்களித்துள்ளான்.) இங்கு குறிப்பிடப்படும் வெற்றி என்பது 'மக்கா வெற்றி' என்றே பெரும்பான்மையானோர் கருதுகின்றனர். அஷ்-ஷஃபி மற்றும் பலர், இந்த வசனம் ஹுதைபிய்யா உடன்படிக்கையைக் குறிக்கிறது என்று கூறினர். இக்கருத்திற்கு ஆதரவாக இமாம் அஹ்மத் அவர்கள் பதிவு செய்த அனஸ் (ரழி) அவர்களின் ஹதீஸ் ஒன்று உள்ளது. அனஸ் (ரழி) அவர்கள் கூறினார்கள்: \"காலித் பின் அல்-வலீத் (ரழி) அவர்களுக்கும் அப்துர் ரஹ்மான் பின் அவ்ஃப் (ரழி) அவர்களுக்கும் இடையே ஒரு சர்ச்சை ஏற்பட்டது. காலித் (ரழி) அவர்கள் அப்துர் ரஹ்மான் (ரழி) அவர்களிடம், 'எங்களுக்கு முன்பே நீங்கள் பங்கேற்ற போர்களைப் பற்றி பெருமை பேசுகிறீர்களா?' என்று கேட்டார்கள். இந்தச் செய்தி நபி (ஸல்) அவர்களுக்கு எட்டியபோது, அவர்கள் கூறினார்கள்:\"<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">دَعُوا</span> <span class=\"quran-arabic-font text-success\">لِي</span> <span class=\"quran-arabic-font text-success\">أَصْحَابِي،</span> <span class=\"quran-arabic-font text-success\">فَوَالَّذِي</span> <span class=\"quran-arabic-font text-success\">نَفْسِي</span> <span class=\"quran-arabic-font text-success\">بِيَدِهِ</span> <span class=\"quran-arabic-font text-success\">لَوْ</span> <span class=\"quran-arabic-font text-success\">أَنْفَقْتُمْ</span> <span class=\"quran-arabic-font text-success\">مِثْلَ</span> <span class=\"quran-arabic-font text-success\">أُحُدٍ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">مِثْلَ</span> <span class=\"quran-arabic-font text-success\">الْجِبَالِ</span> <span class=\"quran-arabic-font text-success\">ذَهَبًا،</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">بَلَغْتُمْ</span> <span class=\"quran-arabic-font text-success\">أَعْمَالَهُم</span>»<br />\r\n<br />\r\n(\"எனது தோழர்களைக் குறை கூறாதீர்கள்! என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது ஆணையாக! நீங்கள் உஹுத் மலை அளவுக்கோ அல்லது மலைகள் அளவுக்கோ தங்கத்தைச் செலவு செய்தாலும், அவர்களுடைய நற்செயல்களின் தகுதியை நீங்கள் அடைய முடியாது.\") நபி (ஸல்) அவர்கள் யாரிடம் இவ்வாறு கூறினார்களோ, அந்த காலித் பின் அல்-வலீத் (ரழி) அவர்கள் ஹுதைபிய்யா உடன்படிக்கைக்கும் மக்கா வெற்றிக்கும் இடைப்பட்ட காலத்தில் இஸ்லாத்தை ஏற்றார் என்பது குறிப்பிடத்தக்கது. காலித் (ரழி) அவர்களுக்கும் அப்துர் ரஹ்மான் (ரழி) அவர்களுக்கும் இடையிலான சர்ச்சை பனூ ஜதீமா போரின்போது ஏற்பட்டது. மக்கா வெற்றிக்குப் பிறகு நபி (ஸல்) அவர்கள் காலித் பின் அல்-வலீத் (ரழி) அவர்களை அவர்களிடம் அனுப்பினார்கள்; அவர்கள் 'அஸ்லம்னா' (நாங்கள் இஸ்லாத்தை ஏற்றோம்) என்று சொல்வதற்குப் பதிலாக 'ஸபஃனா' என்று கூறினர். எனவே காலித் (ரழி) அவர்கள் அவர்களைக் கொல்லவும், போர் கைதிகளைக் கொல்லவும் உத்தரவிட்டார்கள். அப்துர் ரஹ்மான் பின் அவ்ஃப் (ரழி) அவர்களும் அப்துல்லாஹ் பின் உமர் (ரழி) அவர்களும் இதை எதிர்த்தனர். இதுவே அவர்களுக்கு இடையிலான சர்ச்சைக்குக் காரணமாக அமைந்தது. சஹீஹ் புகாரியில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாகப் பதிவாகியுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَسُبُّوا</span> <span class=\"quran-arabic-font text-success\">أَصْحَابِي،</span> <span class=\"quran-arabic-font text-success\">فَوَالَّذِي</span> <span class=\"quran-arabic-font text-success\">نَفْسِي</span> <span class=\"quran-arabic-font text-success\">بِيَدِهِ</span> <span class=\"quran-arabic-font text-success\">لَوْ</span> <span class=\"quran-arabic-font text-success\">أَنْفَقَ</span> <span class=\"quran-arabic-font text-success\">أَحَدُكُمْ</span> <span class=\"quran-arabic-font text-success\">مِثْلَ</span> <span class=\"quran-arabic-font text-success\">أُحُدٍ</span> <span class=\"quran-arabic-font text-success\">ذَهَبًا،</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">بَلَغَ</span> <span class=\"quran-arabic-font text-success\">مُدَّ</span> <span class=\"quran-arabic-font text-success\">أَحَدِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">نَصِيفَه</span>»<br />\r\n<br />\r\n(\"எனது தோழர்களை யாரும் திட்ட வேண்டாம்! என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது ஆணையாக! உங்களில் ஒருவர் உஹுத் மலை அளவு தங்கத்தைச் செலவு செய்தாலும், அது அவர்களில் ஒருவர் வழங்கிய ஒரு 'முத்' (ஒரு கை அளவு) அல்லது அதில் பாதிக்குக் கூட சமமாகாது.\") அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكُلًّا</span> <span class=\"quran-arabic-font text-success\">وَعَدَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الْحُسْنَى</span><br />\r\n<br />\r\n(எனினும், அனைவருக்கும் அல்லாஹ் நன்மையானதையே (நற்கூலியை) வாக்களித்துள்ளான்.) இதன் பொருள், மக்கா வெற்றிக்கு முன்னும் பின்னும் செலவு செய்தவர்கள் அனைவரும் தங்கள் நற்செயல்களுக்குரிய கூலியைப் பெறுவார்கள். அவர்களுக்கிடையே அந்தஸ்துகள் மாறுபட்டு ஒருவரை விட மற்றொருவர் சிறந்த கூலியைப் பெற்றாலும், அல்லாஹ் கூறியது போல்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يَسْتَوِى</span> <span class=\"quran-arabic-font text-success\">الْقَـعِدُونَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">غَيْرُ</span> <span class=\"quran-arabic-font text-success\">أُوْلِى</span> <span class=\"quran-arabic-font text-success\">الضَّرَرِ</span> <span class=\"quran-arabic-font text-success\">وَالْمُجَـهِدُونَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">سَبِيلِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">بِأَمْوَلِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَأَنفُسِهِمْ</span> <span class=\"quran-arabic-font text-success\">فَضَّلَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الْمُجَـهِدِينَ</span> <span class=\"quran-arabic-font text-success\">بِأَمْوَلِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَأَنفُسِهِمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْقَـعِدِينَ</span> <span class=\"quran-arabic-font text-success\">دَرَجَةً</span> <span class=\"quran-arabic-font text-success\">وَكُـلاًّ</span> <span class=\"quran-arabic-font text-success\">وَعَدَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الْحُسْنَى</span> <span class=\"quran-arabic-font text-success\">وَفَضَّلَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الْمُجَـهِدِينَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْقَـعِدِينَ</span> <span class=\"quran-arabic-font text-success\">أَجْراً</span> <span class=\"quran-arabic-font text-success\">عَظِيماً</span><br />\r\n<br />\r\n(இறைநம்பிக்கையாளர்களில் (வீட்டில்) அமர்ந்திருப்பவர்கள் - ஊனமுற்றோரைத் தவிர - மற்றும் அல்லாஹ்வின் பாதையில் தங்கள் செல்வங்களையும் உயிர்களையும் கொண்டு போரிடுபவர்கள் சமமாக மாட்டார்கள். தங்கள் செல்வங்களையும் உயிர்களையும் கொண்டு போரிடுபவர்களை, (வீட்டில்) அமர்ந்திருப்பவர்களை விட அல்லாஹ் அந்தஸ்தில் மேன்மையாக்கினான். அனைவருக்கும் அல்லாஹ் நன்மையை வாக்களித்துள்ளான். இருப்பினும் போரிடுபவர்களை, (வீட்டில்) அமர்ந்திருப்பவர்களை விட மகத்தான நற்கூலியைக் கொண்டு அல்லாஹ் மேன்மையாக்கினான்.)(<a href=\"qurandisp.php?sura=4&ayah=95\" class=\"link\">4:95</a>). சஹீஹ் முஸ்லிமில் ஒரு ஹதீஸ் இவ்வாறு கூறுகிறது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الْمُؤْمِنُ</span> <span class=\"quran-arabic-font text-success\">الْقَوِيُّ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">وَأَحَبُّ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِ</span> <span class=\"quran-arabic-font text-success\">الضَّعِيفِ،</span> <span class=\"quran-arabic-font text-success\">وَفِي</span> <span class=\"quran-arabic-font text-success\">كُلَ</span> <span class=\"quran-arabic-font text-success\">خَيْر</span>»<br />\r\n<br />\r\n(பலமான இறைநம்பிக்கையாளர் பலவீனமான இறைநம்பிக்கையாளரை விட அல்லாஹ்வுக்குச் சிறந்தவரும் மிகவும் பிரியமானவரும் ஆவார்; எனினும் இருவரிடமுமே நன்மை இருக்கிறது.) நபி (ஸல்) அவர்கள் தனது கூற்றை இவ்வாறு முடித்தது, இரண்டாவது வகை இறைநம்பிக்கையாளர்களின் மீதும் கவனத்தைத் திருப்பவே; இதன் மூலம் முதல் வகையினருக்கு முன்னுரிமை அளிக்கும்போது இரண்டாவது வகையினரின் சிறப்புகள் மறக்கப்படாமலும், அவர்கள் தரம் குறைந்தவர்களாகக் கருதப்படாமலும் இருப்பார்கள். எனவே நபி (ஸல்) அவர்கள் முதல் வகையினருக்குச் சிறப்பளித்த பிறகு, பலவீனமான இறைநம்பிக்கையாளர்களாகிய இரண்டாவது வகையினரையும் புகழ்ந்து முடித்தார்கள். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span> <span class=\"quran-arabic-font text-success\">خَبِيرٌ</span><br />\r\n<br />\r\n(நீங்கள் செய்வதை அல்லாஹ் நன்கறிந்தவன்.) இதன் பொருள், அல்லாஹ் எல்லாவற்றையும் முழுமையாக அறிபவன் என்பதால், மக்கா வெற்றிக்கு முன் செலவு செய்து போரிட்டவர்களுக்கும் அதற்குப் பிறகு அவ்வாறு செய்தவர்களுக்கும் இடையிலான நற்கூலிகளில் அவன் வேறுபாடுகளை ஏற்படுத்தினான். நிச்சயமாக அல்லாஹ், முந்தையவர்களின் தூய எண்ணத்தையும் அவனிடம் அவர்கள் கொண்டிருந்த நேர்மையையும் அறிந்து வைத்துள்ளான்; அவர்கள் வறுமை மற்றும் கடும் சிரமமான காலங்களில் செலவு செய்தவர்களாவர். இது ஹதீஸிலும் காணப்படுகிறது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">سَبَقَ</span> <span class=\"quran-arabic-font text-success\">دِرْهَمٌ</span> <span class=\"quran-arabic-font text-success\">مِائَةَ</span> <span class=\"quran-arabic-font text-success\">أَلْف</span>»<br />\r\n<br />\r\n(ஒரு திர்ஹம் செலவு செய்வது ஒரு லட்சம் திர்ஹங்களை முந்திவிட்டது.) ஈமான் கொண்ட மக்கள், இந்த வசனத்தின் பொருளின்படி அபூபக்கர் அஸ்-சித்தீக் (ரழி) அவர்களுக்கே சிறந்த பங்கு உண்டு என்பதில் எவ்வித சந்தேகமும் கொள்வதில்லை. எல்லா நபிமார்களின் பின்பற்றுபவர்களுக்கும் மத்தியில், இந்த வசனத்தைச் செயல்படுத்தியவர்களில் அவர் தலைவராகத் திகழ்ந்தார். அவர் தனது செல்வங்கள் அனைத்தையும் உயர்ந்தோனும் கண்ணியமானவனுமாகிய அல்லாஹ்வின் திருமுகத்தை நாடியே செலவிட்டார். மனிதர்களில் எவரும் அவருக்குச் செய்த உதவிக்கோ கடனுக்கோ கைமாறாக அல்லாமல், அவர் அதனைத் தானாகவே முன்வந்து செய்தார். அல்லாஹ் அவரைப் பொருந்திக் கொள்வானாக.<br />\r\n<br />\r\n<strong>அல்லாஹ்வின் பாதையில் அழகிய கடன் வழங்கத் தூண்டுதல்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَّن</span> <span class=\"quran-arabic-font text-success\">ذَا</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يُقْرِضُ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">قَرْضًا</span> <span class=\"quran-arabic-font text-success\">حَسَنًا</span><br />\r\n<br />\r\n(அல்லாஹ்வுக்கு அழகிய கடன் கொடுப்பவர் யார்?) உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள், இந்த வசனம் அல்லாஹ்வின் பாதையில் செலவு செய்வதைக் குறிப்பதாகக் கூறினார்கள். இது குழந்தைகள் மீது செலவு செய்வதைக் குறிப்பதாகவும் சொல்லப்பட்டது. ஆனால் இதன் சரியான கருத்து என்னவென்றால், இது ஒரு பொதுவான சொல்லாகும். நல் எண்ணத்துடனும் நேர்மையான இதயத்துடனும் அல்லாஹ்வின் பாதையில் செலவு செய்யும் அனைவரும் இந்த வசனத்தின் பொதுவான வரம்பிற்குள் வருகிறார்கள். இதனால்தான் உயர்ந்தோனாகிய அல்லாஹ் மற்றொரு வசனத்தில் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَّن</span> <span class=\"quran-arabic-font text-success\">ذَا</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يُقْرِضُ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">قَرْضًا</span> <span class=\"quran-arabic-font text-success\">حَسَنًا</span> <span class=\"quran-arabic-font text-success\">فَيُضَاعِفَهُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">وَلَهُ</span> <span class=\"quran-arabic-font text-success\">أَجْرٌ</span> <span class=\"quran-arabic-font text-success\">كَرِيمٌ</span><br />\r\n<br />\r\n(அல்லாஹ்வுக்கு அழகிய கடன் கொடுப்பவர் யார்? அல்லாஹ் அதனை அவருக்குப் பல மடங்காக (மறுமையில்) அதிகப்படுத்துவான். மேலும் அவனுக்குக் கண்ணியமான நற்கூலி உண்டு.) மேலும் மற்றோர் இடத்தில்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَضْعَافًا</span> <span class=\"quran-arabic-font text-success\">كَثِيرَةً</span><br />\r\n<br />\r\n(பல மடங்கு) (<a href=\"qurandisp.php?sura=2&ayah=245\" class=\"link\">2:245</a>), இதன் பொருள் அழகிய நற்கூலியும் மகத்தான ஏற்பாடுகளும் ஆகும், அதாவது மறுமை நாளில் சொர்க்கம். இப்னு அபி ஹாதிம் அவர்கள் அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"இந்த வசனம்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَّن</span> <span class=\"quran-arabic-font text-success\">ذَا</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يُقْرِضُ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">قَرْضًا</span> <span class=\"quran-arabic-font text-success\">حَسَنًا</span> <span class=\"quran-arabic-font text-success\">فَيُضَاعِفَهُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span><br />\r\n<br />\r\nஅருளப்பட்டபோது, அபூ அத்-தஹ்தாஹ் அல்-அன்சாரி (ரழி) அவர்கள், 'அல்லாஹ்வின் தூதரே! அல்லாஹ் எங்களிடம் கடன் கேட்கிறானா?' என்று கேட்டார்கள். நபி (ஸல்) அவர்கள் கூறினார்கள்:\"<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">نَعَمْ،</span> <span class=\"quran-arabic-font text-success\">يَاأَبَا</span> <span class=\"quran-arabic-font text-success\">الدَّحْدَاح</span>»<br />\r\n<br />\r\n(\"ஆம், அபூ அத்-தஹ்தாஹ்வே!\") அதற்கு அவர், 'அல்லாஹ்வின் தூதரே! உமது கையைத் தாருங்கள்' என்று கூறி, நபி (ஸல்) அவர்களின் கையைப் பிடித்துக்கொண்டார். பிறகு அபூ அத்-தஹ்தாஹ் (ரழி) அவர்கள், 'நிச்சயமாக நான் எனது தோட்டத்தையே எனது இறைவனுக்குக் கடனாகக் கொடுத்துவிட்டேன்' என்றார். அதற்கு அவர், 'இதோ நான் இருக்கிறேன்' என்றார். அதற்கு அவர், 'இந்தத் தோட்டத்தை விட்டு வெளியேறிவிடு, ஏனெனில் நான் இதனை மேன்மையும் கண்ணியமும் மிக்க எனது இறைவனுக்குக் கடனாகக் கொடுத்துவிட்டேன்' என்றார். அதற்கு அவர், 'அபூ அத்-தஹ்தாஹ்வே! அது ஒரு லாபகரமான வணிகம்!' என்று கூறி, தனது பொருட்களையும் குழந்தைகளையும் அங்கிருந்து மாற்றிக்கொண்டார். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">كَمْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عَذْقٍ</span> <span class=\"quran-arabic-font text-success\">رَدَاحٍ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">لِأَبِي</span> <span class=\"quran-arabic-font text-success\">الدَّحْدَاح</span>»<br />\r\n<br />\r\n(\"சொர்க்கத்தில் அபூ அத்-தஹ்தாஹ்வுக்காக எவ்வளவு செழுமையான பேரீச்சைக் குலைகள் காத்திருக்கின்றன!\") மற்றோர் அறிவிப்பில் நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">رُبَّ</span> <span class=\"quran-arabic-font text-success\">نَخْلَةٍ</span> <span class=\"quran-arabic-font text-success\">مُدَلَّاةٍ،</span> <span class=\"quran-arabic-font text-success\">عُرُوقُهَا</span> <span class=\"quran-arabic-font text-success\">دُرٌّ</span> <span class=\"quran-arabic-font text-success\">وَيَاقُوتٌ،</span> <span class=\"quran-arabic-font text-success\">لِأَبِي</span> <span class=\"quran-arabic-font text-success\">الدَّحْدَاحِ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْجَنَّة</span>»<br />\r\n<br />\r\n(\"சொர்க்கத்தில் அபூ அத்-தஹ்தாஹ்வுக்காக முத்துக்களாலும் மாணிக்கங்களாலும் நிறைந்த தனது குலைகளைத் தாழ்த்தியிருக்கும் எத்தனை பேரீச்சை மரங்கள் உள்ளன!\")<br />\r\n<br />","text":"ஈமான் கொள்வதற்கும் செலவு செய்வதற்கும் ஏவுதல்\n\r\n\n\r\nமேன்மையும் பாக்கியமும் மிக்க அல்லாஹ், தன் மீதும் தன் தூதர் (ஸல்) மீதும் முழுமையான ஈமான் (நம்பிக்கை) கொள்ளுமாறும், அந்தப் பாதையில் உறுதியாக நிலைத்திருக்குமாறும் கட்டளையிடுகிறான். அல்லாஹ் மனிதர்களை எதற்குப் பொறுப்பாளர்களாக ஆக்கினானோ, உங்களிடம் அவன் ஒப்படைத்துள்ள அந்தச் செல்வத்திலிருந்து செலவு செய்யுமாறு அவன் தூண்டுகிறான். இந்தச் செல்வம் உங்களுக்கு முன்பிருந்தவர்களின் கைகளில் இருந்தது, பின்னர் அது உங்களிடம் கைமாறியது. எனவே, மனிதர்களே! அல்லாஹ் தனக்குக் கீழ்ப்படிவதற்காக உங்களிடம் ஒப்படைத்த செல்வத்திலிருந்து, அவன் கட்டளையிட்டபடி செலவு செய்யுங்கள். இல்லையெனில், இது குறித்து அவன் உங்களுக்கு விதித்தவற்றை நீங்கள் புறக்கணித்ததற்காக அவன் உங்களைக் கேள்வி கேட்டுத் தண்டிப்பான். அல்லாஹ்வின் கூற்று,\n\r\n\n\r\nمِمَّا جَعَلَكُم مُّسْتَخْلَفِينَ فِيهِ\n\r\n\n\r\n(எதில் அவன் உங்களைப் பிரதிநிதிகளாக ஆக்கினானோ அதிலிருந்து), என்பது, மனிதர்களாகிய நீங்கள் இந்தச் செல்வத்தை வேறொருவரிடம் ஒப்படைத்துவிடுவீர்கள் என்பதைக் குறிக்கிறது. அவ்வாறு நிகழும்போது, உங்களிடமிருந்து வாரிசாகப் பெறுபவர்கள் அந்தச் செல்வத்தைக் கொண்டு அல்லாஹ்வுக்குக் கீழ்ப்படியக்கூடும்; அதன் மூலம் அல்லாஹ் அவர்களுக்கு வழங்கிய அருட்கொடைகளால் உங்களை விட அதிக மகிழ்ச்சியை அவர்கள் பெறலாம். அல்லது அவர்கள் அல்லாஹ்வுக்கு மாறு செய்யலாம்; அவ்வாறாயின் அவர்கள் தீமையும் வரம்பு மீறலும் செய்வதற்கு நீங்கள் உதவியவர் ஆகிவிடுவீர்கள். இமாம் அஹ்மத் அவர்கள் அப்துல்லாஹ் பின் அஷ்-ஷிக்கீர் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஓதிக்கொண்டிருந்தபோது நான் அவர்களிடம் வந்தேன், அவர்கள் கூறினார்கள்:\"\n\r\n\n\r\nأَلْهَاكُمُ التَّكَاثُرُ\n\r\n\n\r\nيَقُولُ ابْنُ آدَمَ: مَالِي مَالِي، وَهَلْ لَكَ مِن مَالِكَ إِلَّا مَاأَكَلْتَ فَأَفْنَيْتَ، أَوْ لَبِسْتَ فَأَبْلَيْتَ، أَوْ تَصَدَّقْتَ فَأَمْضَيْتَ؟»\n\r\n\n\r\n((பெருமையுடன் எண்ணிக்கையை அதிகரிப்பது உங்களை பராக்காக்கிவிட்டது.) ஆதமின் மகன், 'எனது செல்வம், எனது செல்வம்' என்று உரிமை கோருகிறான். ஆனால் உனது செல்வத்தில் நீ உண்டு அழித்தவை, அல்லது உடுத்திக் கிழித்தவை, அல்லது தர்மம் செய்து மறுமைக்காக அனுப்பி வைத்தவை தவிர உனக்குரியது என்று ஏதேனும் உண்டா?) இமாம் முஸ்லிம் அவர்களும் இதனுடன் பின்வரும் கூடுதல் செய்தியை அறிவித்துள்ளார்கள்:\n\r\n\n\r\n«وَمَا سِوَى ذلِكَ، فَذَاهِبٌ وَتَارِكُهُ لِلنَّاس»\n\r\n\n\r\n(அதைத் தவிர மற்றவற்றை நீ விட்டுவிட்டுப் பிரிந்துவிடுவாய், அவை மற்ற மக்களுக்குப் போய்விடும்.) அல்லாஹ்வின் கூற்று,\n\r\n\n\r\nفَالَّذِينَ ءَامَنُواْ مِنكُمْ وَأَنفَقُواْ لَهُمْ أَجْرٌ كَبِيرٌ\n\r\n\n\r\n(ஆகவே, உங்களில் எவர் ஈமான் கொண்டு செலவு செய்கிறார்களோ, அவர்களுக்கு மகத்தான நற்கூலி உண்டு.) என்பது ஈமான் கொள்வதையும், நற்செயல்களில் செலவு செய்வதையும் ஊக்குவிக்கிறது. உயர்ந்தோனாகிய அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَمَا لَكُمْ لاَ تُؤْمِنُونَ بِاللَّهِ وَالرَّسُولُ يَدْعُوكُمْ لِتُؤْمِنُواْ بِرَبِّكُمْ\n\r\n\n\r\n(அல்லாஹ்வை நீங்கள் ஈமான் கொள்ளாதிருக்க உங்களுக்கு என்ன நேர்ந்தது? தூதரோ (ஸல்) உங்கள் இறைவனை நீங்கள் ஈமான் கொள்ளுமாறு உங்களை அழைக்கிறார்களே;) இதன் பொருள், \"தூதர் (ஸல்) உங்களுக்கு இடையில் இருந்து, ஈமானின் பக்கம் உங்களை அழைத்து, அவர் கொண்டு வந்ததன் உண்மையை உறுதிப்படுத்தும் தெளிவான சான்றுகளையும் ஆதாரங்களையும் முன்வைக்கும்போது, நீங்கள் ஈமான் கொள்வதை எது தடுக்கிறது?\" என்பதாகும். சஹீஹ் அல்-புகாரியில் ஈமான் பற்றிய அத்தியாயத்தின் விளக்கத்தில், நாம் இந்த ஹதீஸை பல்வேறு அறிவிப்பாளர் தொடர்கள் வழியாகக் குறிப்பிட்டுள்ளோம். ஒரு நாள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தங்கள் தோழர்களிடம் (ஸஹாபாக்கள்) கூறினார்கள்:\n\r\n\n\r\n«أَيُّ الْمُؤْمِنِينَ أَعْجَبُ إِلَيْكُمْ إِيمَانًا؟»\n\r\n\n\r\n(இறைநம்பிக்கையாளர்களில் யாருடைய ஈமான் உங்களுக்கு மிகவும் ஆச்சரியமானதாகத் தெரிகிறது?) அவர்கள், \"வானவர்கள்\" என்று கூறினார்கள். நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«وَمَا لَهُمْ لَا يُؤْمِنُونَ وَهُمْ عِنْدَ رَبِّهِمْ؟»\n\r\n\n\r\n(அவர்கள் தங்கள் இறைவனிடம் இருக்கும்போது, அவர்கள் ஈமான் கொள்ளாமல் எப்படி இருப்பார்கள்?) அவர்கள், \"அப்படியானால் நபிமார்கள் (அலை)\" என்றார்கள். நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«وَمَالَهُمْ لَا يُؤْمِنُونَ وَالْوَحْيُ يَنْزِلُ عَلَيْهِمْ؟»\n\r\n\n\r\n(அவர்களுக்கு வஹீ (இறைச்செய்தி) இறங்கிக் கொண்டிருக்கும்போது அவர்கள் ஈமான் கொள்ளாமல் எப்படி இருப்பார்கள்?) அவர்கள், \"அப்படியானால் நாங்கள் தான்\" என்றார்கள். நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«وَمَالَكُمْ لَا تُؤْمِنُونَ وَأَنَا بَيْنَ أَظْهُرِكُمْ؟ وَلكِنْ أَعْجَبُ الْمُؤْمِنِينَ إِيمَانًا، قَوْمٌ يَجِيئُونَ بَعْدَكُمْ، يَجِدُونَ صُحُفًا يُؤْمِنُونَ بِمَا فِيهَا»\n\r\n\n\r\n(நான் உங்களுக்கு மத்தியில் இருக்கும்போது நீங்கள் ஈமான் கொள்ளாமல் எப்படி இருப்பீர்கள்? உண்மையில் மிகவும் ஆச்சரியமான ஈமான் கொண்டவர்கள் யாரென்றால், உங்களுக்குப் பிறகு வரும் மக்களே; அவர்கள் சில ஏடுகளைக் காண்பார்கள், அதில் உள்ளவற்றை அவர்கள் ஈமான் கொள்வார்கள்.) ஸூரத்துல் பகராவில் அல்லாஹ்வின் பின்வரும் வசனத்தை விளக்கும்போது இந்த ஹதீஸின் ஒரு பகுதியை நாம் குறிப்பிட்டுள்ளோம்:\n\r\n\n\r\nالَّذِينَ يُؤْمِنُونَ بِالْغَيْبِ\n\r\n\n\r\n(அவர்கள் மறைவானவற்றை ஈமான் கொள்வார்கள்.)(2:3). அல்லாஹ்வின் கூற்று,\n\r\n\n\r\nوَقَدْ أَخَذَ مِيثَاقَكُمْ\n\r\n\n\r\n(மேலும் அவன் உங்களிடம் உறுதிமொழி வாங்கியுள்ளான்,) என்பது அவனுடைய மற்றொரு வசனத்தைப் போன்றது:\n\r\n\n\r\nوَاذْكُرُواْ نِعْمَةَ اللَّهِ عَلَيْكُمْ وَمِيثَاقَهُ الَّذِى وَاثَقَكُم بِهِ إِذْ قُلْتُمْ سَمِعْنَا وَأَطَعْنَا\n\r\n\n\r\n(உங்கள் மீதுள்ள அல்லாஹ்வின் அருட்கொடையையும், 'நாங்கள் செவியுற்றோம், நாங்கள் கீழ்ப்படிந்தோம்' என்று நீங்கள் கூறியபோது, அவன் உங்களிடம் வாங்கிய உறுதிமொழியையும் நினைவு கூருங்கள்.)(5:7). இது நபி (ஸல்) அவர்களுக்கு வழங்கப்படும் விசுவாசப் பிரமாணத்தைக் குறிக்கிறது. இப்னு ஜரீர் அவர்கள், இங்கு குறிப்பிடப்படும் உடன்படிக்கை, மனிதர்கள் அனைவரும் ஆதம் (அலை) அவர்களின் முதுகில் இருந்தபோது அவர்களிடமிருந்து எடுக்கப்பட்டது என்று கூறினார்கள். இது முஜாஹித் அவர்களின் கருத்தும் ஆகும், அல்லாஹ்வே நன்கு அறிந்தவன். அல்லாஹ் கூறினான்:\n\r\n\n\r\nهُوَ الَّذِى يُنَزِّلُ عَلَى عَبْدِهِ آيَاتٍ بَيِّنَاتٍ\n\r\n\n\r\n(அவனே தன் அடியார் மீது தெளிவான வசனங்களை (ஆயத்துகளை) இறக்குகிறான்.) அதாவது தெளிவான சான்றுகள், ஐயமற்ற ஆதாரங்கள் மற்றும் வெளிப்படையான அத்தாட்சிகள்.\n\r\n\n\r\nلِيُخْرِجَكُمْ مِّنَ الظُّلُمَاتِ إِلَى النُّورِ\n\r\n\n\r\n(அவன் உங்களை இருள்களிலிருந்து ஒளியின் பக்கம் கொண்டு வருவதற்காக.) அறியாமை, நிராகரிப்பு மற்றும் முரண்பாடான கொள்கைகளின் இருள்களிலிருந்து நேர்வழி, உறுதி மற்றும் ஈமானின் ஒளியின் பக்கம் உங்களை இட்டுச் செல்லவே அவன் இவ்வாறு செய்கிறான்.\n\r\n\n\r\nوَإِنَّ اللَّهَ بِكُمْ لَرَءُوفٌ رَّحِيمٌ\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் உங்கள் மீது மிக்க கனிவுடையவன், நிகரற்ற கருணையாளன்.) வேதங்களை அருளியும், மனிதர்களுக்கு வழிகாட்ட தூதர்களை அனுப்பியும், சந்தேகங்களை அகற்றி குழப்பங்களை நீக்கியும் அல்லாஹ் உங்கள் மீது கருணை காட்டுகிறான். முதலில் ஈமான் கொள்ளுமாறும் செலவு செய்யுமாறும் மனிதர்களுக்குக் கட்டளையிட்ட அல்லாஹ், பிறகு ஈமானைப் பெறுவதற்கு இடையில் இருந்த அனைத்துத் தடைகளையும் தான் நீக்கிவிட்டதாகக் கூறி, மீண்டும் அவர்களை ஈமான் கொள்ள ஊக்குவித்தான். அதனைத் தொடர்ந்து மீண்டும் அவர்களைச் செலவு செய்ய அல்லாஹ் தூண்டுகிறான்:\n\r\n\n\r\nوَمَا لَكُمْ أَلاَّ تُنفِقُواْ فِى سَبِيلِ اللَّهِ وَلِلَّهِ مِيرَاثُ السَّمَاوَاتِ وَالْأَرْضِ\n\r\n\n\r\n(அல்லாஹ்வின் பாதையில் நீங்கள் செலவு செய்யாதிருக்க உங்களுக்கு என்ன நேர்ந்தது? வானங்கள் மற்றும் பூமியின் வாரிசுரிமை அல்லாஹ்வுக்கே உரியது.) இதன் பொருள், செலவு செய்யுங்கள், வறுமைக்கோ பற்றாக்குறைக்கோ அஞ்சாதீர்கள். நிச்சயமாக, யாருடைய பாதையில் நீங்கள் செலவு செய்கிறீர்களோ அவன் வானங்கள் மற்றும் பூமியின் அரசனும் உரிமையாளனும் ஆவான். கருவூலங்கள் உட்பட அவற்றின் ஒவ்வோர் விவகாரத்திலும் அவனுக்கே முழுமையான அதிகாரம் உள்ளது. அவன் அர்ஷின் உரிமையாளன், அளப்பரிய வல்லமை கொண்டவன். அவனே இவ்வாறு கூறினான்:\n\r\n\n\r\nوَمَآ أَنفَقْتُمْ مِّن شَىْءٍ فَهُوَ يُخْلِفُهُ وَهُوَ خَيْرُ الرَّازِقِينَ\n\r\n\n\r\n(நீங்கள் எப்பொருளைச் செலவு செய்தாலும், அவன் அதற்குப் பதிலாக வேறொன்றை உங்களுக்குத் தருவான். அவனே வழங்குவோரில் சிறந்தவன்.)(34:39). மேலும்,\n\r\n\n\r\nمَا عِندَكُمْ يَنفَدُ وَمَا عِندَ اللَّهِ بَاقٍ\n\r\n\n\r\n(உங்களிடம் இருப்பது தீர்ந்துவிடும், அல்லாஹ்விடம் இருப்பது நிலையானது.)(16:96). எனவே அல்லாஹ்வின் மீது நம்பிக்கை வைத்து அவனைச் சார்ந்திருப்பவர்கள் செலவு செய்வார்கள்; அர்ஷின் உரிமையாளனிடமிருந்து தங்களுக்கு வறுமை வரும் என்று அவர்கள் அஞ்ச மாட்டார்கள். தாங்கள் செலவு செய்யும் ஒவ்வொன்றுக்கும் அல்லாஹ் நிச்சயமாக ஈடுசெய்வான் என்பதை அவர்கள் அறிவார்கள்.\n\r\n\n\r\nமக்கா வெற்றிக்கு முன் செலவு செய்தல் மற்றும் போரிடுவதன் சிறப்புகள்\n\r\n\n\r\nஅல்லாஹ்வின் கூற்று,\n\r\n\n\r\nلاَ يَسْتَوِى مِنكُم مَّنْ أَنفَقَ مِن قَبْلِ الْفَتْحِ وَقَاتَلَ\n\r\n\n\r\n(உங்களில் வெற்றிக்கு முன் செலவு செய்து போரிட்டவர்களுக்கு (மற்றவர்கள்) சமமாக மாட்டார்கள்.) அதாவது, மக்கா வெற்றிக்கு முன்னர் செலவு செய்து போரிட்டவர்களுக்கு, அதற்குப் பின்னர் செலவு செய்து போரிட்டவர்கள் சமமாக மாட்டார்கள். மக்கா வெற்றிக்கு முன்னால் முஸ்லிம்களின் நிலைமை மிகவும் கடினமாக இருந்தது; அச்சமயத்தில் உண்மையான இறைப்பற்றுடையவர்கள் மட்டுமே இஸ்லாத்தைத் தழுவினார்கள். மக்கா வெற்றிக்குப் பிறகு, இஸ்லாம் உலகம் முழுவதும் மிக வேகமாகப் பரவியது; மக்கள் கூட்டம் கூட்டமாக அல்லாஹ்வின் மார்க்கத்தில் இணைந்தனர். இதைப் போலவே அல்லாஹ் கூறினான்:\n\r\n\n\r\nأُولَئِكَ أَعْظَمُ دَرَجَةً مِّنَ الَّذِينَ أَنفَقُواْ مِن بَعْدُ وَقَاتَلُواْ وَكُلًّا وَعَدَ اللَّهُ الْحُسْنَى\n\r\n\n\r\n(அவர்கள், பின்னர் செலவு செய்து போரிட்டவர்களை விட அந்தஸ்தில் உயர்ந்தவர்கள். எனினும், அனைவருக்கும் அல்லாஹ் நன்மையானதையே (நற்கூலியை) வாக்களித்துள்ளான்.) இங்கு குறிப்பிடப்படும் வெற்றி என்பது 'மக்கா வெற்றி' என்றே பெரும்பான்மையானோர் கருதுகின்றனர். அஷ்-ஷஃபி மற்றும் பலர், இந்த வசனம் ஹுதைபிய்யா உடன்படிக்கையைக் குறிக்கிறது என்று கூறினர். இக்கருத்திற்கு ஆதரவாக இமாம் அஹ்மத் அவர்கள் பதிவு செய்த அனஸ் (ரழி) அவர்களின் ஹதீஸ் ஒன்று உள்ளது. அனஸ் (ரழி) அவர்கள் கூறினார்கள்: \"காலித் பின் அல்-வலீத் (ரழி) அவர்களுக்கும் அப்துர் ரஹ்மான் பின் அவ்ஃப் (ரழி) அவர்களுக்கும் இடையே ஒரு சர்ச்சை ஏற்பட்டது. காலித் (ரழி) அவர்கள் அப்துர் ரஹ்மான் (ரழி) அவர்களிடம், 'எங்களுக்கு முன்பே நீங்கள் பங்கேற்ற போர்களைப் பற்றி பெருமை பேசுகிறீர்களா?' என்று கேட்டார்கள். இந்தச் செய்தி நபி (ஸல்) அவர்களுக்கு எட்டியபோது, அவர்கள் கூறினார்கள்:\"\n\r\n\n\r\n«دَعُوا لِي أَصْحَابِي، فَوَالَّذِي نَفْسِي بِيَدِهِ لَوْ أَنْفَقْتُمْ مِثْلَ أُحُدٍ أَوْ مِثْلَ الْجِبَالِ ذَهَبًا، مَا بَلَغْتُمْ أَعْمَالَهُم»\n\r\n\n\r\n(\"எனது தோழர்களைக் குறை கூறாதீர்கள்! என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது ஆணையாக! நீங்கள் உஹுத் மலை அளவுக்கோ அல்லது மலைகள் அளவுக்கோ தங்கத்தைச் செலவு செய்தாலும், அவர்களுடைய நற்செயல்களின் தகுதியை நீங்கள் அடைய முடியாது.\") நபி (ஸல்) அவர்கள் யாரிடம் இவ்வாறு கூறினார்களோ, அந்த காலித் பின் அல்-வலீத் (ரழி) அவர்கள் ஹுதைபிய்யா உடன்படிக்கைக்கும் மக்கா வெற்றிக்கும் இடைப்பட்ட காலத்தில் இஸ்லாத்தை ஏற்றார் என்பது குறிப்பிடத்தக்கது. காலித் (ரழி) அவர்களுக்கும் அப்துர் ரஹ்மான் (ரழி) அவர்களுக்கும் இடையிலான சர்ச்சை பனூ ஜதீமா போரின்போது ஏற்பட்டது. மக்கா வெற்றிக்குப் பிறகு நபி (ஸல்) அவர்கள் காலித் பின் அல்-வலீத் (ரழி) அவர்களை அவர்களிடம் அனுப்பினார்கள்; அவர்கள் 'அஸ்லம்னா' (நாங்கள் இஸ்லாத்தை ஏற்றோம்) என்று சொல்வதற்குப் பதிலாக 'ஸபஃனா' என்று கூறினர். எனவே காலித் (ரழி) அவர்கள் அவர்களைக் கொல்லவும், போர் கைதிகளைக் கொல்லவும் உத்தரவிட்டார்கள். அப்துர் ரஹ்மான் பின் அவ்ஃப் (ரழி) அவர்களும் அப்துல்லாஹ் பின் உமர் (ரழி) அவர்களும் இதை எதிர்த்தனர். இதுவே அவர்களுக்கு இடையிலான சர்ச்சைக்குக் காரணமாக அமைந்தது. சஹீஹ் புகாரியில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாகப் பதிவாகியுள்ளது:\n\r\n\n\r\n«لَا تَسُبُّوا أَصْحَابِي، فَوَالَّذِي نَفْسِي بِيَدِهِ لَوْ أَنْفَقَ أَحَدُكُمْ مِثْلَ أُحُدٍ ذَهَبًا، مَا بَلَغَ مُدَّ أَحَدِهِمْ وَلَا نَصِيفَه»\n\r\n\n\r\n(\"எனது தோழர்களை யாரும் திட்ட வேண்டாம்! என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது ஆணையாக! உங்களில் ஒருவர் உஹுத் மலை அளவு தங்கத்தைச் செலவு செய்தாலும், அது அவர்களில் ஒருவர் வழங்கிய ஒரு 'முத்' (ஒரு கை அளவு) அல்லது அதில் பாதிக்குக் கூட சமமாகாது.\") அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَكُلًّا وَعَدَ اللَّهُ الْحُسْنَى\n\r\n\n\r\n(எனினும், அனைவருக்கும் அல்லாஹ் நன்மையானதையே (நற்கூலியை) வாக்களித்துள்ளான்.) இதன் பொருள், மக்கா வெற்றிக்கு முன்னும் பின்னும் செலவு செய்தவர்கள் அனைவரும் தங்கள் நற்செயல்களுக்குரிய கூலியைப் பெறுவார்கள். அவர்களுக்கிடையே அந்தஸ்துகள் மாறுபட்டு ஒருவரை விட மற்றொருவர் சிறந்த கூலியைப் பெற்றாலும், அல்லாஹ் கூறியது போல்:\n\r\n\n\r\nلاَّ يَسْتَوِى الْقَـعِدُونَ مِنَ الْمُؤْمِنِينَ غَيْرُ أُوْلِى الضَّرَرِ وَالْمُجَـهِدُونَ فِى سَبِيلِ اللَّهِ بِأَمْوَلِهِمْ وَأَنفُسِهِمْ فَضَّلَ اللَّهُ الْمُجَـهِدِينَ بِأَمْوَلِهِمْ وَأَنفُسِهِمْ عَلَى الْقَـعِدِينَ دَرَجَةً وَكُـلاًّ وَعَدَ اللَّهُ الْحُسْنَى وَفَضَّلَ اللَّهُ الْمُجَـهِدِينَ عَلَى الْقَـعِدِينَ أَجْراً عَظِيماً\n\r\n\n\r\n(இறைநம்பிக்கையாளர்களில் (வீட்டில்) அமர்ந்திருப்பவர்கள் - ஊனமுற்றோரைத் தவிர - மற்றும் அல்லாஹ்வின் பாதையில் தங்கள் செல்வங்களையும் உயிர்களையும் கொண்டு போரிடுபவர்கள் சமமாக மாட்டார்கள். தங்கள் செல்வங்களையும் உயிர்களையும் கொண்டு போரிடுபவர்களை, (வீட்டில்) அமர்ந்திருப்பவர்களை விட அல்லாஹ் அந்தஸ்தில் மேன்மையாக்கினான். அனைவருக்கும் அல்லாஹ் நன்மையை வாக்களித்துள்ளான். இருப்பினும் போரிடுபவர்களை, (வீட்டில்) அமர்ந்திருப்பவர்களை விட மகத்தான நற்கூலியைக் கொண்டு அல்லாஹ் மேன்மையாக்கினான்.)(4:95). சஹீஹ் முஸ்லிமில் ஒரு ஹதீஸ் இவ்வாறு கூறுகிறது:\n\r\n\n\r\n«الْمُؤْمِنُ الْقَوِيُّ خَيْرٌ وَأَحَبُّ إِلَى اللهِ مِنَ الْمُؤْمِنِ الضَّعِيفِ، وَفِي كُلَ خَيْر»\n\r\n\n\r\n(பலமான இறைநம்பிக்கையாளர் பலவீனமான இறைநம்பிக்கையாளரை விட அல்லாஹ்வுக்குச் சிறந்தவரும் மிகவும் பிரியமானவரும் ஆவார்; எனினும் இருவரிடமுமே நன்மை இருக்கிறது.) நபி (ஸல்) அவர்கள் தனது கூற்றை இவ்வாறு முடித்தது, இரண்டாவது வகை இறைநம்பிக்கையாளர்களின் மீதும் கவனத்தைத் திருப்பவே; இதன் மூலம் முதல் வகையினருக்கு முன்னுரிமை அளிக்கும்போது இரண்டாவது வகையினரின் சிறப்புகள் மறக்கப்படாமலும், அவர்கள் தரம் குறைந்தவர்களாகக் கருதப்படாமலும் இருப்பார்கள். எனவே நபி (ஸல்) அவர்கள் முதல் வகையினருக்குச் சிறப்பளித்த பிறகு, பலவீனமான இறைநம்பிக்கையாளர்களாகிய இரண்டாவது வகையினரையும் புகழ்ந்து முடித்தார்கள். அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ\n\r\n\n\r\n(நீங்கள் செய்வதை அல்லாஹ் நன்கறிந்தவன்.) இதன் பொருள், அல்லாஹ் எல்லாவற்றையும் முழுமையாக அறிபவன் என்பதால், மக்கா வெற்றிக்கு முன் செலவு செய்து போரிட்டவர்களுக்கும் அதற்குப் பிறகு அவ்வாறு செய்தவர்களுக்கும் இடையிலான நற்கூலிகளில் அவன் வேறுபாடுகளை ஏற்படுத்தினான். நிச்சயமாக அல்லாஹ், முந்தையவர்களின் தூய எண்ணத்தையும் அவனிடம் அவர்கள் கொண்டிருந்த நேர்மையையும் அறிந்து வைத்துள்ளான்; அவர்கள் வறுமை மற்றும் கடும் சிரமமான காலங்களில் செலவு செய்தவர்களாவர். இது ஹதீஸிலும் காணப்படுகிறது:\n\r\n\n\r\n«سَبَقَ دِرْهَمٌ مِائَةَ أَلْف»\n\r\n\n\r\n(ஒரு திர்ஹம் செலவு செய்வது ஒரு லட்சம் திர்ஹங்களை முந்திவிட்டது.) ஈமான் கொண்ட மக்கள், இந்த வசனத்தின் பொருளின்படி அபூபக்கர் அஸ்-சித்தீக் (ரழி) அவர்களுக்கே சிறந்த பங்கு உண்டு என்பதில் எவ்வித சந்தேகமும் கொள்வதில்லை. எல்லா நபிமார்களின் பின்பற்றுபவர்களுக்கும் மத்தியில், இந்த வசனத்தைச் செயல்படுத்தியவர்களில் அவர் தலைவராகத் திகழ்ந்தார். அவர் தனது செல்வங்கள் அனைத்தையும் உயர்ந்தோனும் கண்ணியமானவனுமாகிய அல்லாஹ்வின் திருமுகத்தை நாடியே செலவிட்டார். மனிதர்களில் எவரும் அவருக்குச் செய்த உதவிக்கோ கடனுக்கோ கைமாறாக அல்லாமல், அவர் அதனைத் தானாகவே முன்வந்து செய்தார். அல்லாஹ் அவரைப் பொருந்திக் கொள்வானாக.\n\r\n\n\r\nஅல்லாஹ்வின் பாதையில் அழகிய கடன் வழங்கத் தூண்டுதல்\n\r\n\n\r\nஅல்லாஹ் கூறினான்:\n\r\n\n\r\nمَّن ذَا الَّذِى يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا\n\r\n\n\r\n(அல்லாஹ்வுக்கு அழகிய கடன் கொடுப்பவர் யார்?) உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள், இந்த வசனம் அல்லாஹ்வின் பாதையில் செலவு செய்வதைக் குறிப்பதாகக் கூறினார்கள். இது குழந்தைகள் மீது செலவு செய்வதைக் குறிப்பதாகவும் சொல்லப்பட்டது. ஆனால் இதன் சரியான கருத்து என்னவென்றால், இது ஒரு பொதுவான சொல்லாகும். நல் எண்ணத்துடனும் நேர்மையான இதயத்துடனும் அல்லாஹ்வின் பாதையில் செலவு செய்யும் அனைவரும் இந்த வசனத்தின் பொதுவான வரம்பிற்குள் வருகிறார்கள். இதனால்தான் உயர்ந்தோனாகிய அல்லாஹ் மற்றொரு வசனத்தில் கூறினான்:\n\r\n\n\r\nمَّن ذَا الَّذِى يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ لَهُ وَلَهُ أَجْرٌ كَرِيمٌ\n\r\n\n\r\n(அல்லாஹ்வுக்கு அழகிய கடன் கொடுப்பவர் யார்? அல்லாஹ் அதனை அவருக்குப் பல மடங்காக (மறுமையில்) அதிகப்படுத்துவான். மேலும் அவனுக்குக் கண்ணியமான நற்கூலி உண்டு.) மேலும் மற்றோர் இடத்தில்,\n\r\n\n\r\nأَضْعَافًا كَثِيرَةً\n\r\n\n\r\n(பல மடங்கு) (2:245), இதன் பொருள் அழகிய நற்கூலியும் மகத்தான ஏற்பாடுகளும் ஆகும், அதாவது மறுமை நாளில் சொர்க்கம். இப்னு அபி ஹாதிம் அவர்கள் அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"இந்த வசனம்,\n\r\n\n\r\nمَّن ذَا الَّذِى يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ لَهُ\n\r\n\n\r\nஅருளப்பட்டபோது, அபூ அத்-தஹ்தாஹ் அல்-அன்சாரி (ரழி) அவர்கள், 'அல்லாஹ்வின் தூதரே! அல்லாஹ் எங்களிடம் கடன் கேட்கிறானா?' என்று கேட்டார்கள். நபி (ஸல்) அவர்கள் கூறினார்கள்:\"\n\r\n\n\r\n«نَعَمْ، يَاأَبَا الدَّحْدَاح»\n\r\n\n\r\n(\"ஆம், அபூ அத்-தஹ்தாஹ்வே!\") அதற்கு அவர், 'அல்லாஹ்வின் தூதரே! உமது கையைத் தாருங்கள்' என்று கூறி, நபி (ஸல்) அவர்களின் கையைப் பிடித்துக்கொண்டார். பிறகு அபூ அத்-தஹ்தாஹ் (ரழி) அவர்கள், 'நிச்சயமாக நான் எனது தோட்டத்தையே எனது இறைவனுக்குக் கடனாகக் கொடுத்துவிட்டேன்' என்றார். அதற்கு அவர், 'இதோ நான் இருக்கிறேன்' என்றார். அதற்கு அவர், 'இந்தத் தோட்டத்தை விட்டு வெளியேறிவிடு, ஏனெனில் நான் இதனை மேன்மையும் கண்ணியமும் மிக்க எனது இறைவனுக்குக் கடனாகக் கொடுத்துவிட்டேன்' என்றார். அதற்கு அவர், 'அபூ அத்-தஹ்தாஹ்வே! அது ஒரு லாபகரமான வணிகம்!' என்று கூறி, தனது பொருட்களையும் குழந்தைகளையும் அங்கிருந்து மாற்றிக்கொண்டார். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«كَمْ مِنْ عَذْقٍ رَدَاحٍ فِي الْجَنَّةِ لِأَبِي الدَّحْدَاح»\n\r\n\n\r\n(\"சொர்க்கத்தில் அபூ அத்-தஹ்தாஹ்வுக்காக எவ்வளவு செழுமையான பேரீச்சைக் குலைகள் காத்திருக்கின்றன!\") மற்றோர் அறிவிப்பில் நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«رُبَّ نَخْلَةٍ مُدَلَّاةٍ، عُرُوقُهَا دُرٌّ وَيَاقُوتٌ، لِأَبِي الدَّحْدَاحِ فِي الْجَنَّة»\n\r\n\n\r\n(\"சொர்க்கத்தில் அபூ அத்-தஹ்தாஹ்வுக்காக முத்துக்களாலும் மாணிக்கங்களாலும் நிறைந்த தனது குலைகளைத் தாழ்த்தியிருக்கும் எத்தனை பேரீச்சை மரங்கள் உள்ளன!\")"},"12":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=57&ayah=15\" class=\"link\">57:15</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 57:15 ஐ பார்க்கவும்"},"13":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=57&ayah=15\" class=\"link\">57:15</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 57:15 ஐ பார்க்கவும்"},"14":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=57&ayah=15\" class=\"link\">57:15</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 57:15 ஐ பார்க்கவும்"},"15":{"html":"<strong>மறுமை நாளில் நம்பிக்கையாளர்களுக்கு அவர்களின் நற்செயல்களுக்கு ஏற்ப ஒளி வழங்கப்படும்<br />\r\n</strong><br />\r\n<br />\r\n<br />\r\nஉயர்ந்தோனாகிய அல்லாஹ் கூறுகிறான்: தர்மம் செய்யும் நம்பிக்கையாளர்கள் மறுமை நாளில் அவர்கள் ஒன்றுதிரட்டப்படும் மஹ்ஷர் மைதானத்தில், தங்களின் நற்செயல்களின் அளவிற்கு ஏற்ப தங்களுக்கு முன்னால் ஒளி வீச வருவார்கள். அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: <span class=\"quran-arabic-font text-success\">﴾يَسْعَى</span> <span class=\"quran-arabic-font text-success\">نُورُهُم</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">أَيْدِيهِمْ﴿</span><br />\r\n<br />\r\n<br />\r\n(அவர்களுடைய ஒளி அவர்களுக்கு முன்னால் விரைந்து செல்லும்), இது குறித்து அவர்கள் கூறினார்கள்: \"அவர்கள் தங்களின் செயல்களுக்கு ஏற்ப ஸிராத் பாலத்தைக் கடப்பார்கள். அவர்களில் சிலருக்கு மலை போன்ற பிரம்மாண்டமான ஒளி இருக்கும்; சிலருக்குப் பேரீச்சை மரத்தைப் போன்றும், சிலருக்கு நின்றுகொண்டிருக்கும் மனிதனின் உயரத்தைப் போன்றும் ஒளி இருக்கும். அவர்களில் மிகக் குறைந்த ஒளி உடையவருக்கு, அவரது கால் பெருவிரல் நுனியில் இருக்கும் ஒளியைப் போன்றே இருக்கும்; அது சில நேரங்களில் ஒளிரும், சில நேரங்களில் அணைந்துவிடும்.\" இப்னு அபீ ஹாதிம் மற்றும் இப்னு ஜரீர் ஆகியோர் இந்த ஹதீஸைப் பதிவு செய்துள்ளனர். அத்-தஹ்ஹாக் இந்த வசனத்திற்கு விளக்கமளிக்கையில், \"மறுமை நாளில் ஒவ்வொருவருக்கும் ஒரு ஒளி வழங்கப்படும். அவர்கள் ஸிராத் பாலத்தை அடையும்போது, நயவஞ்சகர்களின் ஒளி அணைக்கப்பட்டுவிடும். இதைக் காணும் நம்பிக்கையாளர்கள், நயவஞ்சகர்களின் ஒளி அணைக்கப்பட்டது போல் தங்களின் ஒளியும் அணைந்துவிடுமோ என்று அஞ்சுவார்கள். அந்த நேரத்தில் நம்பிக்கையாளர்கள் அல்லாஹ்விடம், 'எங்கள் இறைவனே! எங்களுடைய ஒளியை எங்களுக்குப் பரிபூரணமாக்கி வைப்பாயாக!' என்று பிரார்த்திப்பார்கள்\" எனக் கூறினார். அல்லாஹ்வின் கூற்று: <span class=\"quran-arabic-font text-success\">﴾وَبِأَيْمَـنِهِم﴿</span><br />\r\n<br />\r\n<br />\r\n(மேலும் அவர்களின் வலது கரங்களிலும்.) இதற்கு அத்-தஹ்ஹாக், \"அவர்களின் வினைப்பதிவேடுகள்\" என்று கூறினார். அல்லாஹ் கூறுவது போல: <span class=\"quran-arabic-font text-success\">﴾فَمَنْ</span> <span class=\"quran-arabic-font text-success\">أُوتِىَ</span> <span class=\"quran-arabic-font text-success\">كِتَـبَهُ</span> <span class=\"quran-arabic-font text-success\">بِيَمِينِهِ﴿</span><br />\r\n<br />\r\n<br />\r\n(எவருடைய வினைப்பதிவேடு அவரது வலது கையில் வழங்கப்படுகிறதோ...)(<a href=\"qurandisp.php?sura=17&ayah=71\" class=\"link\">17:71</a>). அல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾بُشْرَاكُمُ</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">جَنَّـتٌ</span> <span class=\"quran-arabic-font text-success\">تَجْرِى</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">تَحْتِهَا</span> <span class=\"quran-arabic-font text-success\">الْأَنْهَارُ﴿</span><br />\r\n<br />\r\n<br />\r\n(இன்று உங்களுக்கு நற்செய்தி! அதன் கீழே ஆறுகள் ஓடிக்கொண்டிருக்கும் சுவனச்சோலைகள்,) அதாவது, அவர்களிடம், \"இன்று உங்களுக்கு நற்செய்தி! அதன் கீழே ஆறுகள் ஓடிக்கொண்டிருக்கும் சுவனச்சோலைகள் உங்களுக்கு உண்டு; <span class=\"quran-arabic-font text-success\">﴾خَـلِدِينَ</span> <span class=\"quran-arabic-font text-success\">فِيهَآ﴿</span><br />\r\n<br />\r\n<br />\r\n(அதில் அவர்கள் என்றென்றும் தங்குவார்கள்!), நீங்கள் அதில் நிரந்தரமாகத் தங்கியிருப்பீர்கள்\" என்று கூறப்படும். <span class=\"quran-arabic-font text-success\">﴾ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الْفَوْزُ</span> <span class=\"quran-arabic-font text-success\">الْعَظِيمُ﴿</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக இதுவே மகத்தான வெற்றியாகும்!)<br />\r\n<br />\r\n<br />\r\n<strong><br />\r\nமறுமை நாளில் நயவஞ்சகர்களின் நிலை<br />\r\n</strong><br />\r\n<br />\r\n<br />\r\nஅல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَقُولُ</span> <span class=\"quran-arabic-font text-success\">الْمُنَـفِقُونَ</span> <span class=\"quran-arabic-font text-success\">وَالْمُنَـفِقَـتُ</span> <span class=\"quran-arabic-font text-success\">لِلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">انظُرُونَا</span> <span class=\"quran-arabic-font text-success\">نَقْتَبِسْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">نُّورِكُمْ﴿</span><br />\r\n<br />\r\n<br />\r\n(நயவஞ்சகர்களான ஆண்களும் பெண்களும் நம்பிக்கையாளர்களிடம்: \"எங்களுக்காகக் காத்திருங்கள்! உங்கள் ஒளியிலிருந்து நாங்களும் சிறிதளவு பெற்றுக்கொள்கிறோம்\" என்று கூறும் நாளில்...) மறுமை நாளில் மஹ்ஷர் மைதானத்தில் நிகழவிருக்கும் பயங்கரமான நடுக்கங்கள், கொடூரமான சம்பவங்கள் மற்றும் மகத்தான நிகழ்வுகளைப் பற்றி இந்த வசனத்தில் அல்லாஹ் நமக்குத் தெரிவிக்கிறான். அந்த நாளில் அல்லாஹ்வையும் அவனது தூதரையும் (ஸல்) ஈமான் கொண்டு, அல்லாஹ்வின் கட்டளைகளுக்குக் கீழ்ப்படிந்து, அவனது விலக்கல்களைத் தவிர்த்தவர்களைத் தவிர வேறு யாரும் தப்ப முடியாது. அல்-அவ்ஃபி, அத்-தஹ்ஹாக் மற்றும் பலர் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள்: \"மக்கள் இருளில் ஒன்றுதிரட்டப்படும்போது, அல்லாஹ் ஓர் ஒளியை வழங்குவான். நம்பிக்கையாளர்கள் அந்த ஒளியைக் கண்டதும் அதை நோக்கிச் செல்வார்கள். அந்த ஒளி அல்லாஹ்விடமிருந்து சுவனத்திற்கு இட்டுச் செல்லும் வழிகாட்டியாக அவர்களுக்கு அமையும். நம்பிக்கையாளர்கள் அந்த ஒளியைப் பின்தொடர்வதைக் காணும் நயவஞ்சகர்கள், அவர்களையும் பின்தொடர்வார்கள். ஆனால், அல்லாஹ் நயவஞ்சகர்களின் ஒளியை அணைத்துவிடுவான். அப்போது அவர்கள் (நம்பிக்கையாளர்களிடம்), <span class=\"quran-arabic-font text-success\">﴾انظُرُونَا</span> <span class=\"quran-arabic-font text-success\">نَقْتَبِسْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">نُّورِكُمْ﴿</span><br />\r\n<br />\r\n<br />\r\n(எங்களுக்காகக் காத்திருங்கள்! உங்கள் ஒளியிலிருந்து நாங்களும் சிறிதளவு பெற்றுக்கொள்கிறோம்) என்று கூறுவார்கள். அதற்கு நம்பிக்கையாளர்கள், <span class=\"quran-arabic-font text-success\">﴾ارْجِعُواْ</span> <span class=\"quran-arabic-font text-success\">وَرَآءَكُمْ﴿</span><br />\r\n<br />\r\n<br />\r\n(உங்களுக்குப் பின்னால் திரும்பிச் செல்லுங்கள்!) நீங்கள் வந்த அந்த இருளுக்கே திரும்பிச் சென்று அங்கே ஒளியைத் தேடிக்கொள்ளுங்கள்!\" என்று பதிலளிப்பார்கள்.<br />\r\n<br />\r\n<br />\r\nஅல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾فَضُرِبَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُم</span> <span class=\"quran-arabic-font text-success\">بِسُورٍ</span> <span class=\"quran-arabic-font text-success\">لَّهُ</span> <span class=\"quran-arabic-font text-success\">بَابٌ</span> <span class=\"quran-arabic-font text-success\">بَاطِنُهُ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَةُ</span> <span class=\"quran-arabic-font text-success\">وَظَـهِرُهُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قِبَلِهِ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابُ﴿</span><br />\r\n<br />\r\n<br />\r\n(ஆகவே, அவர்களுக்கு இடையே ஒரு சுவர் எழுப்பப்படும்; அதில் ஒரு வாசலும் இருக்கும். அதன் உட்புறத்தில் அருள் இருக்கும், அதன் வெளிப்புறத்தில் வேதனை இருக்கும்.) அல்-ஹஸன் மற்றும் கதாதா ஆகியோர், இங்கு குறிப்பிடப்பட்டுள்ள சுவர் சுவனத்திற்கும் நரகத்திற்கும் இடையில் அமைந்துள்ளது என்று கூறினர். அப்துர் ரஹ்மான் பின் ஸைத் பின் அஸ்லம் அவர்கள், இந்த வசனத்தில் உள்ள சுவர்தான் அல்லாஹ் பின்வரும் வசனத்தில் குறிப்பிடும் திரையாகும் என்று கூறினார்: <span class=\"quran-arabic-font text-success\">﴾وَبَيْنَهُمَا</span> <span class=\"quran-arabic-font text-success\">حِجَابٌ﴿</span><br />\r\n<br />\r\n<br />\r\n(அவ்விரண்டுக்கும் இடையே ஒரு திரை இருக்கும்.)(<a href=\"qurandisp.php?sura=7&ayah=46\" class=\"link\">7:46</a>). முஜாஹித் மற்றும் பலரிடமிருந்தும் இக்கருத்து வந்துள்ளது, இதுவே சரியானதுமாகும். அல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾بَاطِنُهُ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَةُ﴿</span><br />\r\n<br />\r\n<br />\r\n(அதன் உட்புறத்தில் அருள் இருக்கும்,) அதாவது சுவனமும் அதிலுள்ள பாக்கியங்களும்; <span class=\"quran-arabic-font text-success\">﴾وَظَـهِرُهُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قِبَلِهِ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابُ﴿</span><br />\r\n<br />\r\n<br />\r\n(அதன் வெளிப்புறத்தில் வேதனை இருக்கும்,) அதாவது நரக நெருப்பு என்று கதாதா, இப்னு ஸைத் மற்றும் பலர் விளக்கியுள்ளனர். அல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾يُنَـدُونَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَلَمْ</span> <span class=\"quran-arabic-font text-success\">نَكُن</span> <span class=\"quran-arabic-font text-success\">مَّعَكُمْ﴿</span><br />\r\n<br />\r\n<br />\r\n((நயவஞ்சகர்கள்) நம்பிக்கையாளர்களை நோக்கிக் கூவுவார்கள்: \"நாங்கள் உங்களுடன் இருக்கவில்லையா?\") அதாவது, நயவஞ்சகர்கள் நம்பிக்கையாளர்களைப் பார்த்து, \"நாங்கள் இவ்வுலக வாழ்வில் உங்களுடன் சேர்ந்து ஜும்ஆ மற்றும் ஜமாஅத் தொழுகைகளில் பங்கேற்கவில்லையா? ஹஜ்ஜின் போது அரஃபா மைதானத்தில் உங்களுடன் நிற்கவில்லையா? உங்களுடன் இணைந்து போர்க்களங்களில் பங்கெடுக்கவில்லையா? மற்ற வணக்க வழிபாடுகளையும் உங்களுடன் சேர்ந்து செய்யவில்லையா?\" என்று கேட்பார்கள். <span class=\"quran-arabic-font text-success\">﴾قَالُواْ</span> <span class=\"quran-arabic-font text-success\">بَلَى﴿</span><br />\r\n<br />\r\n<br />\r\n(நம்பிக்கையாளர்கள் பதிலளிப்பார்கள்: \"ஆம்!...\")<br />\r\n<br />\r\n<br />\r\nநம்பிக்கையாளர்கள் அவர்களுக்குப் பதிலளிக்கும்போது, \"ஆம், நீங்கள் எங்களுடன் உடலால் இருந்தீர்கள், <span class=\"quran-arabic-font text-success\">﴾وَلَـكِنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">فَتَنتُمْ</span> <span class=\"quran-arabic-font text-success\">أَنفُسَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَتَرَبَّصْتُمْ</span> <span class=\"quran-arabic-font text-success\">وَارْتَبْتُمْ</span> <span class=\"quran-arabic-font text-success\">وَغرَّتْكُمُ</span> <span class=\"quran-arabic-font text-success\">الْأَمَانِيُّ﴿</span><br />\r\n<br />\r\n<br />\r\n(ஆனால், நீங்கள் உங்களையே சோதனையில் ஆழ்த்திக்கொண்டீர்கள்; எங்களுக்குத் தீமை விளையும் என்று காத்திருந்தீர்கள்; (சத்தியத்தில்) சந்தேகம் கொண்டீர்கள்; வீணான ஆசைகள் உங்களை ஏமாற்றிவிட்டன)\" என்பார்கள். கதாதா கூறும்போது, <span class=\"quran-arabic-font text-success\">﴾وَتَرَبَّصْتُمْ﴿</span> (காத்திருந்தீர்கள்) என்பதற்கு, \"சத்தியத்திற்கும் சத்தியவாதிகளுக்கும் அழிவு வரும் என்று காத்திருந்தீர்கள்\" என்று விளக்கமளித்தார். <span class=\"quran-arabic-font text-success\">﴾وَارْتَبْتُمْ﴿</span> (சந்தேகம் கொண்டீர்கள்,) அதாவது மரணத்திற்குப் பின் மீண்டும் உயிர் பெறுவதை சந்தேகித்தீர்கள். <span class=\"quran-arabic-font text-success\">﴾وَغرَّتْكُمُ</span> <span class=\"quran-arabic-font text-success\">الْأَمَانِيُّ﴿</span> (வீணான ஆசைகள் உங்களை ஏமாற்றிவிட்டன,) அதாவது உங்கள் பாவங்கள் மன்னிக்கப்படும் என்று நீங்களாகவே எண்ணிக் கொண்டீர்கள்; அல்லது இவ்வுலக வாழ்க்கை உங்களை ஏமாற்றிவிட்டது. <span class=\"quran-arabic-font text-success\">﴾حَتَّى</span> <span class=\"quran-arabic-font text-success\">جَآءَ</span> <span class=\"quran-arabic-font text-success\">أَمْرُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ﴿</span><br />\r\n<br />\r\n<br />\r\n(அல்லாஹ்வின் கட்டளை வரும் வரை.) அதாவது உங்களுக்கு மரணம் வரும் வரை நீங்கள் இதே நிலையில் இருந்தீர்கள். <span class=\"quran-arabic-font text-success\">﴾وَغَرَّكُم</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">الْغَرُورُ﴿</span><br />\r\n<br />\r\n<br />\r\n(மேலும் அந்த ஏமாற்றுக்காரன் அல்லாஹ்வைக் குறித்து உங்களை ஏமாற்றிவிட்டான்.) இங்கு 'ஏமாற்றுக்காரன்' என்பது ஷைத்தானைக் குறிக்கும். கதாதா கூறினார்கள்: \"அவர்கள் ஷைத்தானால் வஞ்சிக்கப்பட்டார்கள். அல்லாஹ்வின் மீது சத்தியமாக! அல்லாஹ் அவர்களை நரக நெருப்பில் தள்ளும் வரை அவர்கள் ஏமாற்றப்பட்ட நிலையிலேயே இருந்தார்கள்.\"<br />\r\n<br />\r\n<br />\r\nஇதன் பொருள் என்னவென்றால், நம்பிக்கையாளர்கள் நயவஞ்சகர்களுக்குப் பதில் சொல்லும்போது, \"நீங்கள் இதயமற்ற உடல்களாகவும், தூய எண்ணம் அற்றவர்களாகவும் எங்களுடன் இருந்தீர்கள். நீங்கள் எப்போதும் சந்தேகத்திலும் ஐயத்திலும் மூழ்கியிருந்தீர்கள். நீங்கள் மக்களுக்காகவே அமல் செய்தீர்கள், அல்லாஹ்வை மிகக் குறைவாகவே நினைவுகூர்ந்தீர்கள்\" என்பார்கள். முஜாஹித் அவர்கள் கூறும்போது: \"நயவஞ்சகர்கள் இவ்வுலகில் நம்பிக்கையாளர்களுடன் கலந்து வாழ்ந்தனர், அவர்களுடன் திருமண உறவு கொண்டனர்; ஆனால் அவர்களுடன் இருந்துகொண்டே அவர்களுக்குத் துரோகம் செய்தனர். அவர்கள் உள்ளத்தால் செத்தவர்களாக இருந்தனர். மறுமை நாளில் இரு தரப்பினருக்கும் ஒளி வழங்கப்படும், ஆனால் அந்தச் சுவரை அடையும்போது நயவஞ்சகர்களின் ஒளி அணைந்துவிடும்; அப்போதுதான் இரு தரப்பினரும் ஒருவரை ஒருவர் விட்டுப் பிரிவார்கள்!\" என்றார்.<br />\r\n<br />\r\nஅல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾فَالْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُؤْخَذُ</span> <span class=\"quran-arabic-font text-success\">مِنكُمْ</span> <span class=\"quran-arabic-font text-success\">فِدْيَةٌ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ﴿</span><br />\r\n<br />\r\n(ஆகவே, இன்று உங்களிடமிருந்தோ, அல்லது நிராகரிப்பவர்களிடமிருந்தோ எந்த ஈட்டுத்தொகையும் பெற்றுக்கொள்ளப்பட மாட்டாது.) அதாவது, உங்களுக்குக் கிடைத்திருக்கும் தண்டனையிலிருந்து தப்பிப்பதற்காக நீங்கள் பூமி நிரம்பத் தங்கத்தைக் கொடுத்தாலும், அது உங்களிடமிருந்து ஏற்றுக்கொள்ளப்பட மாட்டாது.<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்று: <span class=\"quran-arabic-font text-success\">﴾مَأْوَاكُمُ</span> <span class=\"quran-arabic-font text-success\">النَّارُ﴿</span><br />\r\n<br />\r\n<br />\r\n(உங்கள் தங்குமிடம் நரகமே.) அதாவது, நரகமே உங்கள் இறுதி இலக்கு, அங்கேயே நீங்கள் நிரந்தரமாகத் தங்குவீர்கள். <span class=\"quran-arabic-font text-success\">﴾هِىَ</span> <span class=\"quran-arabic-font text-success\">مَوْلَـكُمْ﴿</span><br />\r\n<br />\r\n<br />\r\n(அதுவே உங்களுக்குத் தகுதியான இடமாகும்,) அதாவது உங்கள் நிராகரிப்பு மற்றும் சந்தேகத்தின் காரணமாக, மற்ற எல்லா இடங்களை விடவும் அதுவே உங்களுக்கு உகந்த புகலிடமாகும். <span class=\"quran-arabic-font text-success\">﴾وَبِئْسَ</span> <span class=\"quran-arabic-font text-success\">الْمَصِيرُ﴿</span><br />\r\n<br />\r\n<br />\r\n(அது சேருமிடத்தில் மிகக் கெட்டதாகும்!)<br />\r\n<br />","text":"மறுமை நாளில் நம்பிக்கையாளர்களுக்கு அவர்களின் நற்செயல்களுக்கு ஏற்ப ஒளி வழங்கப்படும்\n\r\n\n\r\n\n\r\n\n\r\nஉயர்ந்தோனாகிய அல்லாஹ் கூறுகிறான்: தர்மம் செய்யும் நம்பிக்கையாளர்கள் மறுமை நாளில் அவர்கள் ஒன்றுதிரட்டப்படும் மஹ்ஷர் மைதானத்தில், தங்களின் நற்செயல்களின் அளவிற்கு ஏற்ப தங்களுக்கு முன்னால் ஒளி வீச வருவார்கள். அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: ﴾يَسْعَى نُورُهُم بَيْنَ أَيْدِيهِمْ﴿\n\r\n\n\r\n\n\r\n(அவர்களுடைய ஒளி அவர்களுக்கு முன்னால் விரைந்து செல்லும்), இது குறித்து அவர்கள் கூறினார்கள்: \"அவர்கள் தங்களின் செயல்களுக்கு ஏற்ப ஸிராத் பாலத்தைக் கடப்பார்கள். அவர்களில் சிலருக்கு மலை போன்ற பிரம்மாண்டமான ஒளி இருக்கும்; சிலருக்குப் பேரீச்சை மரத்தைப் போன்றும், சிலருக்கு நின்றுகொண்டிருக்கும் மனிதனின் உயரத்தைப் போன்றும் ஒளி இருக்கும். அவர்களில் மிகக் குறைந்த ஒளி உடையவருக்கு, அவரது கால் பெருவிரல் நுனியில் இருக்கும் ஒளியைப் போன்றே இருக்கும்; அது சில நேரங்களில் ஒளிரும், சில நேரங்களில் அணைந்துவிடும்.\" இப்னு அபீ ஹாதிம் மற்றும் இப்னு ஜரீர் ஆகியோர் இந்த ஹதீஸைப் பதிவு செய்துள்ளனர். அத்-தஹ்ஹாக் இந்த வசனத்திற்கு விளக்கமளிக்கையில், \"மறுமை நாளில் ஒவ்வொருவருக்கும் ஒரு ஒளி வழங்கப்படும். அவர்கள் ஸிராத் பாலத்தை அடையும்போது, நயவஞ்சகர்களின் ஒளி அணைக்கப்பட்டுவிடும். இதைக் காணும் நம்பிக்கையாளர்கள், நயவஞ்சகர்களின் ஒளி அணைக்கப்பட்டது போல் தங்களின் ஒளியும் அணைந்துவிடுமோ என்று அஞ்சுவார்கள். அந்த நேரத்தில் நம்பிக்கையாளர்கள் அல்லாஹ்விடம், 'எங்கள் இறைவனே! எங்களுடைய ஒளியை எங்களுக்குப் பரிபூரணமாக்கி வைப்பாயாக!' என்று பிரார்த்திப்பார்கள்\" எனக் கூறினார். அல்லாஹ்வின் கூற்று: ﴾وَبِأَيْمَـنِهِم﴿\n\r\n\n\r\n\n\r\n(மேலும் அவர்களின் வலது கரங்களிலும்.) இதற்கு அத்-தஹ்ஹாக், \"அவர்களின் வினைப்பதிவேடுகள்\" என்று கூறினார். அல்லாஹ் கூறுவது போல: ﴾فَمَنْ أُوتِىَ كِتَـبَهُ بِيَمِينِهِ﴿\n\r\n\n\r\n\n\r\n(எவருடைய வினைப்பதிவேடு அவரது வலது கையில் வழங்கப்படுகிறதோ...)(17:71). அல்லாஹ் கூறினான்: ﴾بُشْرَاكُمُ الْيَوْمَ جَنَّـتٌ تَجْرِى مِن تَحْتِهَا الْأَنْهَارُ﴿\n\r\n\n\r\n\n\r\n(இன்று உங்களுக்கு நற்செய்தி! அதன் கீழே ஆறுகள் ஓடிக்கொண்டிருக்கும் சுவனச்சோலைகள்,) அதாவது, அவர்களிடம், \"இன்று உங்களுக்கு நற்செய்தி! அதன் கீழே ஆறுகள் ஓடிக்கொண்டிருக்கும் சுவனச்சோலைகள் உங்களுக்கு உண்டு; ﴾خَـلِدِينَ فِيهَآ﴿\n\r\n\n\r\n\n\r\n(அதில் அவர்கள் என்றென்றும் தங்குவார்கள்!), நீங்கள் அதில் நிரந்தரமாகத் தங்கியிருப்பீர்கள்\" என்று கூறப்படும். ﴾ذَلِكَ هُوَ الْفَوْزُ الْعَظِيمُ﴿\n\r\n\n\r\n\n\r\n(நிச்சயமாக இதுவே மகத்தான வெற்றியாகும்!)\n\r\n\n\r\n\n\r\n\n\r\nமறுமை நாளில் நயவஞ்சகர்களின் நிலை\n\r\n\n\r\n\n\r\n\n\r\nஅல்லாஹ் கூறினான்: ﴾يَوْمَ يَقُولُ الْمُنَـفِقُونَ وَالْمُنَـفِقَـتُ لِلَّذِينَ ءَامَنُواْ انظُرُونَا نَقْتَبِسْ مِن نُّورِكُمْ﴿\n\r\n\n\r\n\n\r\n(நயவஞ்சகர்களான ஆண்களும் பெண்களும் நம்பிக்கையாளர்களிடம்: \"எங்களுக்காகக் காத்திருங்கள்! உங்கள் ஒளியிலிருந்து நாங்களும் சிறிதளவு பெற்றுக்கொள்கிறோம்\" என்று கூறும் நாளில்...) மறுமை நாளில் மஹ்ஷர் மைதானத்தில் நிகழவிருக்கும் பயங்கரமான நடுக்கங்கள், கொடூரமான சம்பவங்கள் மற்றும் மகத்தான நிகழ்வுகளைப் பற்றி இந்த வசனத்தில் அல்லாஹ் நமக்குத் தெரிவிக்கிறான். அந்த நாளில் அல்லாஹ்வையும் அவனது தூதரையும் (ஸல்) ஈமான் கொண்டு, அல்லாஹ்வின் கட்டளைகளுக்குக் கீழ்ப்படிந்து, அவனது விலக்கல்களைத் தவிர்த்தவர்களைத் தவிர வேறு யாரும் தப்ப முடியாது. அல்-அவ்ஃபி, அத்-தஹ்ஹாக் மற்றும் பலர் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள்: \"மக்கள் இருளில் ஒன்றுதிரட்டப்படும்போது, அல்லாஹ் ஓர் ஒளியை வழங்குவான். நம்பிக்கையாளர்கள் அந்த ஒளியைக் கண்டதும் அதை நோக்கிச் செல்வார்கள். அந்த ஒளி அல்லாஹ்விடமிருந்து சுவனத்திற்கு இட்டுச் செல்லும் வழிகாட்டியாக அவர்களுக்கு அமையும். நம்பிக்கையாளர்கள் அந்த ஒளியைப் பின்தொடர்வதைக் காணும் நயவஞ்சகர்கள், அவர்களையும் பின்தொடர்வார்கள். ஆனால், அல்லாஹ் நயவஞ்சகர்களின் ஒளியை அணைத்துவிடுவான். அப்போது அவர்கள் (நம்பிக்கையாளர்களிடம்), ﴾انظُرُونَا نَقْتَبِسْ مِن نُّورِكُمْ﴿\n\r\n\n\r\n\n\r\n(எங்களுக்காகக் காத்திருங்கள்! உங்கள் ஒளியிலிருந்து நாங்களும் சிறிதளவு பெற்றுக்கொள்கிறோம்) என்று கூறுவார்கள். அதற்கு நம்பிக்கையாளர்கள், ﴾ارْجِعُواْ وَرَآءَكُمْ﴿\n\r\n\n\r\n\n\r\n(உங்களுக்குப் பின்னால் திரும்பிச் செல்லுங்கள்!) நீங்கள் வந்த அந்த இருளுக்கே திரும்பிச் சென்று அங்கே ஒளியைத் தேடிக்கொள்ளுங்கள்!\" என்று பதிலளிப்பார்கள்.\n\r\n\n\r\n\n\r\nஅல்லாஹ் கூறினான்: ﴾فَضُرِبَ بَيْنَهُم بِسُورٍ لَّهُ بَابٌ بَاطِنُهُ فِيهِ الرَّحْمَةُ وَظَـهِرُهُ مِن قِبَلِهِ الْعَذَابُ﴿\n\r\n\n\r\n\n\r\n(ஆகவே, அவர்களுக்கு இடையே ஒரு சுவர் எழுப்பப்படும்; அதில் ஒரு வாசலும் இருக்கும். அதன் உட்புறத்தில் அருள் இருக்கும், அதன் வெளிப்புறத்தில் வேதனை இருக்கும்.) அல்-ஹஸன் மற்றும் கதாதா ஆகியோர், இங்கு குறிப்பிடப்பட்டுள்ள சுவர் சுவனத்திற்கும் நரகத்திற்கும் இடையில் அமைந்துள்ளது என்று கூறினர். அப்துர் ரஹ்மான் பின் ஸைத் பின் அஸ்லம் அவர்கள், இந்த வசனத்தில் உள்ள சுவர்தான் அல்லாஹ் பின்வரும் வசனத்தில் குறிப்பிடும் திரையாகும் என்று கூறினார்: ﴾وَبَيْنَهُمَا حِجَابٌ﴿\n\r\n\n\r\n\n\r\n(அவ்விரண்டுக்கும் இடையே ஒரு திரை இருக்கும்.)(7:46). முஜாஹித் மற்றும் பலரிடமிருந்தும் இக்கருத்து வந்துள்ளது, இதுவே சரியானதுமாகும். அல்லாஹ் கூறினான்: ﴾بَاطِنُهُ فِيهِ الرَّحْمَةُ﴿\n\r\n\n\r\n\n\r\n(அதன் உட்புறத்தில் அருள் இருக்கும்,) அதாவது சுவனமும் அதிலுள்ள பாக்கியங்களும்; ﴾وَظَـهِرُهُ مِن قِبَلِهِ الْعَذَابُ﴿\n\r\n\n\r\n\n\r\n(அதன் வெளிப்புறத்தில் வேதனை இருக்கும்,) அதாவது நரக நெருப்பு என்று கதாதா, இப்னு ஸைத் மற்றும் பலர் விளக்கியுள்ளனர். அல்லாஹ் கூறினான்: ﴾يُنَـدُونَهُمْ أَلَمْ نَكُن مَّعَكُمْ﴿\n\r\n\n\r\n\n\r\n((நயவஞ்சகர்கள்) நம்பிக்கையாளர்களை நோக்கிக் கூவுவார்கள்: \"நாங்கள் உங்களுடன் இருக்கவில்லையா?\") அதாவது, நயவஞ்சகர்கள் நம்பிக்கையாளர்களைப் பார்த்து, \"நாங்கள் இவ்வுலக வாழ்வில் உங்களுடன் சேர்ந்து ஜும்ஆ மற்றும் ஜமாஅத் தொழுகைகளில் பங்கேற்கவில்லையா? ஹஜ்ஜின் போது அரஃபா மைதானத்தில் உங்களுடன் நிற்கவில்லையா? உங்களுடன் இணைந்து போர்க்களங்களில் பங்கெடுக்கவில்லையா? மற்ற வணக்க வழிபாடுகளையும் உங்களுடன் சேர்ந்து செய்யவில்லையா?\" என்று கேட்பார்கள். ﴾قَالُواْ بَلَى﴿\n\r\n\n\r\n\n\r\n(நம்பிக்கையாளர்கள் பதிலளிப்பார்கள்: \"ஆம்!...\")\n\r\n\n\r\n\n\r\nநம்பிக்கையாளர்கள் அவர்களுக்குப் பதிலளிக்கும்போது, \"ஆம், நீங்கள் எங்களுடன் உடலால் இருந்தீர்கள், ﴾وَلَـكِنَّكُمْ فَتَنتُمْ أَنفُسَكُمْ وَتَرَبَّصْتُمْ وَارْتَبْتُمْ وَغرَّتْكُمُ الْأَمَانِيُّ﴿\n\r\n\n\r\n\n\r\n(ஆனால், நீங்கள் உங்களையே சோதனையில் ஆழ்த்திக்கொண்டீர்கள்; எங்களுக்குத் தீமை விளையும் என்று காத்திருந்தீர்கள்; (சத்தியத்தில்) சந்தேகம் கொண்டீர்கள்; வீணான ஆசைகள் உங்களை ஏமாற்றிவிட்டன)\" என்பார்கள். கதாதா கூறும்போது, ﴾وَتَرَبَّصْتُمْ﴿ (காத்திருந்தீர்கள்) என்பதற்கு, \"சத்தியத்திற்கும் சத்தியவாதிகளுக்கும் அழிவு வரும் என்று காத்திருந்தீர்கள்\" என்று விளக்கமளித்தார். ﴾وَارْتَبْتُمْ﴿ (சந்தேகம் கொண்டீர்கள்,) அதாவது மரணத்திற்குப் பின் மீண்டும் உயிர் பெறுவதை சந்தேகித்தீர்கள். ﴾وَغرَّتْكُمُ الْأَمَانِيُّ﴿ (வீணான ஆசைகள் உங்களை ஏமாற்றிவிட்டன,) அதாவது உங்கள் பாவங்கள் மன்னிக்கப்படும் என்று நீங்களாகவே எண்ணிக் கொண்டீர்கள்; அல்லது இவ்வுலக வாழ்க்கை உங்களை ஏமாற்றிவிட்டது. ﴾حَتَّى جَآءَ أَمْرُ اللَّهِ﴿\n\r\n\n\r\n\n\r\n(அல்லாஹ்வின் கட்டளை வரும் வரை.) அதாவது உங்களுக்கு மரணம் வரும் வரை நீங்கள் இதே நிலையில் இருந்தீர்கள். ﴾وَغَرَّكُم بِاللَّهِ الْغَرُورُ﴿\n\r\n\n\r\n\n\r\n(மேலும் அந்த ஏமாற்றுக்காரன் அல்லாஹ்வைக் குறித்து உங்களை ஏமாற்றிவிட்டான்.) இங்கு 'ஏமாற்றுக்காரன்' என்பது ஷைத்தானைக் குறிக்கும். கதாதா கூறினார்கள்: \"அவர்கள் ஷைத்தானால் வஞ்சிக்கப்பட்டார்கள். அல்லாஹ்வின் மீது சத்தியமாக! அல்லாஹ் அவர்களை நரக நெருப்பில் தள்ளும் வரை அவர்கள் ஏமாற்றப்பட்ட நிலையிலேயே இருந்தார்கள்.\"\n\r\n\n\r\n\n\r\nஇதன் பொருள் என்னவென்றால், நம்பிக்கையாளர்கள் நயவஞ்சகர்களுக்குப் பதில் சொல்லும்போது, \"நீங்கள் இதயமற்ற உடல்களாகவும், தூய எண்ணம் அற்றவர்களாகவும் எங்களுடன் இருந்தீர்கள். நீங்கள் எப்போதும் சந்தேகத்திலும் ஐயத்திலும் மூழ்கியிருந்தீர்கள். நீங்கள் மக்களுக்காகவே அமல் செய்தீர்கள், அல்லாஹ்வை மிகக் குறைவாகவே நினைவுகூர்ந்தீர்கள்\" என்பார்கள். முஜாஹித் அவர்கள் கூறும்போது: \"நயவஞ்சகர்கள் இவ்வுலகில் நம்பிக்கையாளர்களுடன் கலந்து வாழ்ந்தனர், அவர்களுடன் திருமண உறவு கொண்டனர்; ஆனால் அவர்களுடன் இருந்துகொண்டே அவர்களுக்குத் துரோகம் செய்தனர். அவர்கள் உள்ளத்தால் செத்தவர்களாக இருந்தனர். மறுமை நாளில் இரு தரப்பினருக்கும் ஒளி வழங்கப்படும், ஆனால் அந்தச் சுவரை அடையும்போது நயவஞ்சகர்களின் ஒளி அணைந்துவிடும்; அப்போதுதான் இரு தரப்பினரும் ஒருவரை ஒருவர் விட்டுப் பிரிவார்கள்!\" என்றார்.\n\r\n\n\r\nஅல்லாஹ் கூறினான்: ﴾فَالْيَوْمَ لاَ يُؤْخَذُ مِنكُمْ فِدْيَةٌ وَلاَ مِنَ الَّذِينَ كَفَرُواْ﴿\n\r\n\n\r\n(ஆகவே, இன்று உங்களிடமிருந்தோ, அல்லது நிராகரிப்பவர்களிடமிருந்தோ எந்த ஈட்டுத்தொகையும் பெற்றுக்கொள்ளப்பட மாட்டாது.) அதாவது, உங்களுக்குக் கிடைத்திருக்கும் தண்டனையிலிருந்து தப்பிப்பதற்காக நீங்கள் பூமி நிரம்பத் தங்கத்தைக் கொடுத்தாலும், அது உங்களிடமிருந்து ஏற்றுக்கொள்ளப்பட மாட்டாது.\n\r\n\n\r\nஅல்லாஹ்வின் கூற்று: ﴾مَأْوَاكُمُ النَّارُ﴿\n\r\n\n\r\n\n\r\n(உங்கள் தங்குமிடம் நரகமே.) அதாவது, நரகமே உங்கள் இறுதி இலக்கு, அங்கேயே நீங்கள் நிரந்தரமாகத் தங்குவீர்கள். ﴾هِىَ مَوْلَـكُمْ﴿\n\r\n\n\r\n\n\r\n(அதுவே உங்களுக்குத் தகுதியான இடமாகும்,) அதாவது உங்கள் நிராகரிப்பு மற்றும் சந்தேகத்தின் காரணமாக, மற்ற எல்லா இடங்களை விடவும் அதுவே உங்களுக்கு உகந்த புகலிடமாகும். ﴾وَبِئْسَ الْمَصِيرُ﴿\n\r\n\n\r\n\n\r\n(அது சேருமிடத்தில் மிகக் கெட்டதாகும்!)"},"16":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=57&ayah=17\" class=\"link\">57:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 57:17 ஐ பார்க்கவும்"},"17":{"html":"அதாவது, உங்களின் நிராகரிப்பு மற்றும் சந்தேகத்தின் காரணமாக, வேறு எந்த இருப்பிடத்தையும் விட அதுவே உங்களுக்குத் தகுதியான புகலிடமாகும். மேலும், சென்றடையும் இடங்களில் நரகம் எவ்வளவு மோசமானது!<br />\r\n<br />\r\n<strong>உள்ளச்சத்தை ஊக்குவித்தல் மற்றும் வேதக்காரர்களைப் பின்பற்றுவதைத் தடுத்தல்</strong><br />\r\n<br />\r\nஅல்லாஹ் கேட்கிறான்: \"நம்பிக்கையாளர்கள் குர்ஆனைப் புரிந்து கொண்டு அதன்படி நடப்பதற்கும், செவியேற்றுப் பணிவதற்கும், அல்லாஹ்வின் நினைவாலும், மென்மையான அறிவுரைகளைக் கேட்பதாலும், குர்ஆன் ஓதுவதாலும் அவர்களின் உள்ளங்கள் பணிவடைவதற்கான நேரம் இன்னும் வரவில்லையா?\" இமாம் முஸ்லிம் பதிவு செய்துள்ளார்கள், அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள் கூறியதாவது: \"நாங்கள் இஸ்லாத்தை ஏற்றுக்கொண்டதற்கும், அல்லாஹ் எங்களை நுட்பமாக எச்சரித்த இந்த வசனம் வஹீ (இறைச்செய்தி)யாக அருளப்பட்டதற்கும் இடையே நான்கு ஆண்டுகளே இடைவெளி இருந்தது: <span class=\"quran-arabic-font text-success\">﴾أَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَأْنِ</span> <span class=\"quran-arabic-font text-success\">لِلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَخْشَعَ</span> <span class=\"quran-arabic-font text-success\">قُلُوبُهُمْ</span> <span class=\"quran-arabic-font text-success\">لِذِكْرِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">نَزَلَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْحَقِّ﴿</span><br />\r\n<br />\r\n(நம்பிக்கை கொண்டவர்களின் உள்ளங்கள் அல்லாஹ்வின் நினைவிற்காகவும், இறங்கியுள்ள உண்மைக்காகவும் பணிவடைவதற்கான காலம் இன்னும் வரவில்லையா?)\" இந்த அறிவிப்பை இமாம் முஸ்லிம் தனது நூலின் இறுதிப் பகுதிக்குச் சற்று முன்பாகத் தொகுத்துள்ளார்கள். இமாம் அன்-நஸாயீ அவர்களும் இந்த வசனத்தின் தஃப்ஸீரில் இந்த ஹதீஸைப் பதிவு செய்துள்ளார்கள். அல்லாஹ்வின் கூற்று: <span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَكُونُواْ</span> <span class=\"quran-arabic-font text-success\">كَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">أُوتُواْ</span> <span class=\"quran-arabic-font text-success\">الْكِتَابَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلُ</span> <span class=\"quran-arabic-font text-success\">فَطَالَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمُ</span> <span class=\"quran-arabic-font text-success\">الْأَمَدُ</span> <span class=\"quran-arabic-font text-success\">فَقَسَتْ</span> <span class=\"quran-arabic-font text-success\">قُلُوبُهُمْ﴿</span><br />\r\n<br />\r\n(அவர்கள் தங்களுக்கு முன்னர் வேதம் கொடுக்கப்பட்டவர்களைப் போல் ஆகிவிட வேண்டாம்; அவர்களுக்குக் காலம் நீடித்ததால் அவர்களின் உள்ளங்கள் இறுகிவிட்டன.) தங்களுக்கு முன்பு வேதம் கொடுக்கப்பட்ட யூதர்களையும் கிறிஸ்தவர்களையும் பின்பற்றுவதை அல்லாஹ் நம்பிக்கையாளர்களுக்குத் தடை செய்கிறான். காலம் செல்லச் செல்ல, அவர்கள் தங்களிடமிருந்த அல்லாஹ்வின் வேதத்தை மாற்றி, அதை அற்பமான விலைக்கு விற்றனர். அவர்கள் அல்லாஹ்வின் வேதத்தைத் தங்களுக்குப் பின்னால் எறிந்துவிட்டு, பல்வேறு கருத்துக்களாலும் தவறான கொள்கைகளாலும் ஈர்க்கப்பட்டு அதில் மூழ்கிப்போனார்கள். அவர்கள் அல்லாஹ்வின் மார்க்க விஷயத்தில் மற்றவர்களின் வழிமுறைகளைப் பின்பற்றி, தங்கள் ரபிக்களையும் பாதிரியார்களையும் அல்லாஹ்வையன்றி தெய்வங்களாக ஆக்கிக்கொண்டார்கள். இதன் விளைவாக, அவர்களின் உள்ளங்கள் இறுகிவிட்டன, அவர்கள் அறிவுரைகளை ஏற்கவில்லை; அல்லாஹ்வின் வாக்குறுதிகளாலோ அல்லது அச்சுறுத்தல்களாலோ அவர்களின் உள்ளங்கள் பணிவடைவில்லை. <span class=\"quran-arabic-font text-success\">﴾وَكَثِيرٌ</span> <span class=\"quran-arabic-font text-success\">مِّنْهُمْ</span> <span class=\"quran-arabic-font text-success\">فَاسِقُونَ﴿</span><br />\r\n<br />\r\n(அவர்களில் பெரும்பாலோர் பாவிகளாக இருந்தனர்.) அதாவது, அவர்களின் செயல்பாடுகளில்; எனவே, அவர்களின் உள்ளங்கள் சீர்கெட்டுப் போயின, அவர்களின் செயல்களும் பயனற்றவையாகிவிட்டன. இதனை மேலானவனான அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾فَبِمَا</span> <span class=\"quran-arabic-font text-success\">نَقْضِهِم</span> <span class=\"quran-arabic-font text-success\">مِّيثَاقَهُمْ</span> <span class=\"quran-arabic-font text-success\">لَعَنَّاهُمْ</span> <span class=\"quran-arabic-font text-success\">وَجَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">قُلُوبَهُمْ</span> <span class=\"quran-arabic-font text-success\">قَاسِيَةً</span> <span class=\"quran-arabic-font text-success\">يُحَرِّفُونَ</span> <span class=\"quran-arabic-font text-success\">الْكَلِمَ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">مَّوَاضِعِهِ</span> <span class=\"quran-arabic-font text-success\">وَنَسُواْ</span> <span class=\"quran-arabic-font text-success\">حَظًّا</span> <span class=\"quran-arabic-font text-success\">مِّمَّا</span> <span class=\"quran-arabic-font text-success\">ذُكِرُواْ</span> <span class=\"quran-arabic-font text-success\">بِهِ﴿</span><br />\r\n<br />\r\n(தங்கள் உடன்படிக்கையை அவர்கள் முறித்த காரணத்தினால் நாம் அவர்களைச் சபித்தோம்; அவர்களின் உள்ளங்களைக் கடினமானதாக ஆக்கினோம். அவர்கள் (வேதத்தின்) வார்த்தைகளை அவற்றின் சரியான இடங்களிலிருந்து மாற்றுகிறார்கள்; அவர்களுக்கு அறிவுறுத்தப்பட்டவற்றில் ஒரு பகுதியை அவர்கள் கைவிட்டுவிட்டார்கள்.) (<a href=\"qurandisp.php?sura=5&ayah=13\" class=\"link\">5:13</a>). அதாவது, அவர்களின் உள்ளங்கள் சீர்கெட்டு இறுகிவிட்டன. அல்லாஹ்வின் வார்த்தைகளை அவற்றின் சரியான இடங்களிலிருந்தும் பொருள்களிலிருந்தும் மாற்றும் பழக்கத்தை அவர்கள் ஏற்படுத்திக் கொண்டனர். அவர்களுக்குக் கட்டளையிடப்பட்ட வணக்கங்களை அவர்கள் கைவிட்டனர், தடுத்தவற்றைச் செய்தனர். இதனால்தான் அடிப்படை அல்லது விரிவான விஷயங்கள் என எதிலும் அவர்களைப் பின்பற்றுவதை அல்லாஹ் நம்பிக்கையாளர்களுக்குத் தடுத்தான். மேலானவனான அல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾اعْلَمُواْ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">يُحْيِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضَ</span> <span class=\"quran-arabic-font text-success\">بَعْدَ</span> <span class=\"quran-arabic-font text-success\">مَوْتِهَا</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">بَيَّنَّا</span> <span class=\"quran-arabic-font text-success\">لَكُمُ</span> <span class=\"quran-arabic-font text-success\">الْآيَاتِ</span> <span class=\"quran-arabic-font text-success\">لَعَلَّكُمْ</span> <span class=\"quran-arabic-font text-success\">تَعْقِلُونَ﴿</span><br />\r\n<br />\r\n(பூமி இறந்த பிறகு அல்லாஹ் அதற்கு உயிர் கொடுக்கிறான் என்பதை அறிந்து கொள்ளுங்கள்! நீங்கள் உணர்ந்து கொள்வதற்காகச் சான்றுகளை உங்களுக்கு நாம் தெளிவுபடுத்தியுள்ளோம்.) உள்ளங்கள் இறுகிப் போன பிறகு அல்லாஹ் அவற்றில் மென்மையைக் கொண்டு வருகிறான் என்பதையும், குழப்பத்தில் உள்ளவர்கள் வழிதவறிய பின் அவர்களுக்கு நேர்வழி காட்டுகிறான் என்பதையும், கஷ்டங்கள் தீவிரமடைந்த பிறகு அவற்றை நீக்குகிறான் என்பதையும் இந்த வசனம் உணர்த்துகிறது. வறண்ட பூமிக்குத் தேவையான மழையை அனுப்பி அல்லாஹ் எப்படி அதற்கு மீண்டும் உயிரூட்டுகிறானோ, அதேபோல் குர்ஆனின் தெளிவான சான்றுகளைக் கொண்டு இறுகிய உள்ளங்களுக்கு அவன் நேர்வழி காட்டுகிறான். உள்ளங்கள் அடைக்கப்பட்டு எவ்வித நேர்வழியும் செல்ல முடியாத நிலைக்குப் பிறகு, ஈமானின் (நம்பிக்கையின்) ஒளி மீண்டும் அந்த உள்ளங்களைச் சென்றடையும். மனிதர்கள் வழிகெட்ட பிறகு தான் நாடியவர்களுக்கு நேர்வழி காட்டுபவனுக்கே எல்லாப் புகழும் உரியது. முன்பு நேர்வழியில் இருந்தவர்களை அவன் வழிகேட்டில் விடுகிறான். நிச்சயமாக, அவன் தான் நாடியதைச் செய்பவன்; அவன் ஞானமிக்கவன், அவன் செய்யும் அனைத்திலும் நீதியானவன், நுட்பமானவன், அனைத்தையும் நன்கறிந்தவன், மிக உயர்ந்தவன், பெருமைக்குரியவன்.<br />\r\n<br />","text":"அதாவது, உங்களின் நிராகரிப்பு மற்றும் சந்தேகத்தின் காரணமாக, வேறு எந்த இருப்பிடத்தையும் விட அதுவே உங்களுக்குத் தகுதியான புகலிடமாகும். மேலும், சென்றடையும் இடங்களில் நரகம் எவ்வளவு மோசமானது!\n\r\n\n\r\nஉள்ளச்சத்தை ஊக்குவித்தல் மற்றும் வேதக்காரர்களைப் பின்பற்றுவதைத் தடுத்தல்\n\r\n\n\r\nஅல்லாஹ் கேட்கிறான்: \"நம்பிக்கையாளர்கள் குர்ஆனைப் புரிந்து கொண்டு அதன்படி நடப்பதற்கும், செவியேற்றுப் பணிவதற்கும், அல்லாஹ்வின் நினைவாலும், மென்மையான அறிவுரைகளைக் கேட்பதாலும், குர்ஆன் ஓதுவதாலும் அவர்களின் உள்ளங்கள் பணிவடைவதற்கான நேரம் இன்னும் வரவில்லையா?\" இமாம் முஸ்லிம் பதிவு செய்துள்ளார்கள், அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள் கூறியதாவது: \"நாங்கள் இஸ்லாத்தை ஏற்றுக்கொண்டதற்கும், அல்லாஹ் எங்களை நுட்பமாக எச்சரித்த இந்த வசனம் வஹீ (இறைச்செய்தி)யாக அருளப்பட்டதற்கும் இடையே நான்கு ஆண்டுகளே இடைவெளி இருந்தது: ﴾أَلَمْ يَأْنِ لِلَّذِينَ ءَامَنُواْ أَن تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ اللَّهِ وَمَا نَزَلَ مِنَ الْحَقِّ﴿\n\r\n\n\r\n(நம்பிக்கை கொண்டவர்களின் உள்ளங்கள் அல்லாஹ்வின் நினைவிற்காகவும், இறங்கியுள்ள உண்மைக்காகவும் பணிவடைவதற்கான காலம் இன்னும் வரவில்லையா?)\" இந்த அறிவிப்பை இமாம் முஸ்லிம் தனது நூலின் இறுதிப் பகுதிக்குச் சற்று முன்பாகத் தொகுத்துள்ளார்கள். இமாம் அன்-நஸாயீ அவர்களும் இந்த வசனத்தின் தஃப்ஸீரில் இந்த ஹதீஸைப் பதிவு செய்துள்ளார்கள். அல்லாஹ்வின் கூற்று: ﴾وَلاَ يَكُونُواْ كَالَّذِينَ أُوتُواْ الْكِتَابَ مِن قَبْلُ فَطَالَ عَلَيْهِمُ الْأَمَدُ فَقَسَتْ قُلُوبُهُمْ﴿\n\r\n\n\r\n(அவர்கள் தங்களுக்கு முன்னர் வேதம் கொடுக்கப்பட்டவர்களைப் போல் ஆகிவிட வேண்டாம்; அவர்களுக்குக் காலம் நீடித்ததால் அவர்களின் உள்ளங்கள் இறுகிவிட்டன.) தங்களுக்கு முன்பு வேதம் கொடுக்கப்பட்ட யூதர்களையும் கிறிஸ்தவர்களையும் பின்பற்றுவதை அல்லாஹ் நம்பிக்கையாளர்களுக்குத் தடை செய்கிறான். காலம் செல்லச் செல்ல, அவர்கள் தங்களிடமிருந்த அல்லாஹ்வின் வேதத்தை மாற்றி, அதை அற்பமான விலைக்கு விற்றனர். அவர்கள் அல்லாஹ்வின் வேதத்தைத் தங்களுக்குப் பின்னால் எறிந்துவிட்டு, பல்வேறு கருத்துக்களாலும் தவறான கொள்கைகளாலும் ஈர்க்கப்பட்டு அதில் மூழ்கிப்போனார்கள். அவர்கள் அல்லாஹ்வின் மார்க்க விஷயத்தில் மற்றவர்களின் வழிமுறைகளைப் பின்பற்றி, தங்கள் ரபிக்களையும் பாதிரியார்களையும் அல்லாஹ்வையன்றி தெய்வங்களாக ஆக்கிக்கொண்டார்கள். இதன் விளைவாக, அவர்களின் உள்ளங்கள் இறுகிவிட்டன, அவர்கள் அறிவுரைகளை ஏற்கவில்லை; அல்லாஹ்வின் வாக்குறுதிகளாலோ அல்லது அச்சுறுத்தல்களாலோ அவர்களின் உள்ளங்கள் பணிவடைவில்லை. ﴾وَكَثِيرٌ مِّنْهُمْ فَاسِقُونَ﴿\n\r\n\n\r\n(அவர்களில் பெரும்பாலோர் பாவிகளாக இருந்தனர்.) அதாவது, அவர்களின் செயல்பாடுகளில்; எனவே, அவர்களின் உள்ளங்கள் சீர்கெட்டுப் போயின, அவர்களின் செயல்களும் பயனற்றவையாகிவிட்டன. இதனை மேலானவனான அல்லாஹ் கூறுகிறான்: ﴾فَبِمَا نَقْضِهِم مِّيثَاقَهُمْ لَعَنَّاهُمْ وَجَعَلْنَا قُلُوبَهُمْ قَاسِيَةً يُحَرِّفُونَ الْكَلِمَ عَن مَّوَاضِعِهِ وَنَسُواْ حَظًّا مِّمَّا ذُكِرُواْ بِهِ﴿\n\r\n\n\r\n(தங்கள் உடன்படிக்கையை அவர்கள் முறித்த காரணத்தினால் நாம் அவர்களைச் சபித்தோம்; அவர்களின் உள்ளங்களைக் கடினமானதாக ஆக்கினோம். அவர்கள் (வேதத்தின்) வார்த்தைகளை அவற்றின் சரியான இடங்களிலிருந்து மாற்றுகிறார்கள்; அவர்களுக்கு அறிவுறுத்தப்பட்டவற்றில் ஒரு பகுதியை அவர்கள் கைவிட்டுவிட்டார்கள்.) (5:13). அதாவது, அவர்களின் உள்ளங்கள் சீர்கெட்டு இறுகிவிட்டன. அல்லாஹ்வின் வார்த்தைகளை அவற்றின் சரியான இடங்களிலிருந்தும் பொருள்களிலிருந்தும் மாற்றும் பழக்கத்தை அவர்கள் ஏற்படுத்திக் கொண்டனர். அவர்களுக்குக் கட்டளையிடப்பட்ட வணக்கங்களை அவர்கள் கைவிட்டனர், தடுத்தவற்றைச் செய்தனர். இதனால்தான் அடிப்படை அல்லது விரிவான விஷயங்கள் என எதிலும் அவர்களைப் பின்பற்றுவதை அல்லாஹ் நம்பிக்கையாளர்களுக்குத் தடுத்தான். மேலானவனான அல்லாஹ் கூறினான்: ﴾اعْلَمُواْ أَنَّ اللَّهَ يُحْيِي الْأَرْضَ بَعْدَ مَوْتِهَا قَدْ بَيَّنَّا لَكُمُ الْآيَاتِ لَعَلَّكُمْ تَعْقِلُونَ﴿\n\r\n\n\r\n(பூமி இறந்த பிறகு அல்லாஹ் அதற்கு உயிர் கொடுக்கிறான் என்பதை அறிந்து கொள்ளுங்கள்! நீங்கள் உணர்ந்து கொள்வதற்காகச் சான்றுகளை உங்களுக்கு நாம் தெளிவுபடுத்தியுள்ளோம்.) உள்ளங்கள் இறுகிப் போன பிறகு அல்லாஹ் அவற்றில் மென்மையைக் கொண்டு வருகிறான் என்பதையும், குழப்பத்தில் உள்ளவர்கள் வழிதவறிய பின் அவர்களுக்கு நேர்வழி காட்டுகிறான் என்பதையும், கஷ்டங்கள் தீவிரமடைந்த பிறகு அவற்றை நீக்குகிறான் என்பதையும் இந்த வசனம் உணர்த்துகிறது. வறண்ட பூமிக்குத் தேவையான மழையை அனுப்பி அல்லாஹ் எப்படி அதற்கு மீண்டும் உயிரூட்டுகிறானோ, அதேபோல் குர்ஆனின் தெளிவான சான்றுகளைக் கொண்டு இறுகிய உள்ளங்களுக்கு அவன் நேர்வழி காட்டுகிறான். உள்ளங்கள் அடைக்கப்பட்டு எவ்வித நேர்வழியும் செல்ல முடியாத நிலைக்குப் பிறகு, ஈமானின் (நம்பிக்கையின்) ஒளி மீண்டும் அந்த உள்ளங்களைச் சென்றடையும். மனிதர்கள் வழிகெட்ட பிறகு தான் நாடியவர்களுக்கு நேர்வழி காட்டுபவனுக்கே எல்லாப் புகழும் உரியது. முன்பு நேர்வழியில் இருந்தவர்களை அவன் வழிகேட்டில் விடுகிறான். நிச்சயமாக, அவன் தான் நாடியதைச் செய்பவன்; அவன் ஞானமிக்கவன், அவன் செய்யும் அனைத்திலும் நீதியானவன், நுட்பமானவன், அனைத்தையும் நன்கறிந்தவன், மிக உயர்ந்தவன், பெருமைக்குரியவன்."},"18":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=57&ayah=19\" class=\"link\">57:19</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 57:19 ஐ பார்க்கவும்"},"19":{"html":"<strong>தர்மம் செய்பவர்கள், உண்மையாளர்கள் மற்றும் ஷஹீத்களுக்கான வெகுமதி; மற்றும் நிராகரிப்பாளர்களின் சேருமிடம்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْمُصَّدِّقِينَ</span> <span class=\"quran-arabic-font text-success\">وَالْمُصَّدِّقَاتِ</span><br />\r\n(நிச்சயமாக தர்மம் செய்யும் ஆண்களும், தர்மம் செய்யும் பெண்களும்)<br />\r\nதேவையுடையவர்கள், ஏழைகள் மற்றும் எளியவர்களுக்காகத் தங்கள் செல்வத்திலிருந்து செலவு செய்யும் ஆண்கள் மற்றும் பெண்களுக்கு மேலான அல்லாஹ் வழங்கவிருக்கும் வெகுமதியைப் பற்றி அவன் விவரிக்கிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَقْرَضُوا</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">قَرْضاً</span> <span class=\"quran-arabic-font text-success\">حَسَناً</span><br />\r\n(மேலும் அல்லாஹ்வுக்கு அழகிய கடன் கொடுத்தார்களே அவர்கள்,) அதாவது, அவர்கள் அல்லாஹ்வின் திருப்தியை நாடித் தூய உள்ளத்துடன் தர்மம் செய்கிறார்கள். அவர்கள் உலகியல் வெகுமதிகளையோ அல்லது யாரிடம் தர்மம் செய்கிறார்களோ அவர்களிடமிருந்து பாராட்டையோ எதிர்பார்ப்பதில்லை. அல்லாஹ்வின் கூற்று,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يُضَاعَفُ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span><br />\r\n(அது அவர்களுக்குப் பன்மடங்காகப் பெருக்கப்படும்,) அதாவது, அவன் நற்செயல்களைப் பத்து மடங்கிலிருந்து, எழுநூறு மடங்கு வரையிலும், அதற்கும் மேலாகவும் பெருக்குவான் என்பதைக் குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَجْرٌ</span> <span class=\"quran-arabic-font text-success\">كَرِيمٌ</span><br />\r\n(மேலும் அவர்களுக்குக் கண்ணியமான நற்கூலி உண்டு.) அவர்களுக்குத் தாராளமான, அழகான வெகுமதியும், அவர்கள் திரும்பிச் செல்ல ஒரு நல்ல தங்குமிடமும், கண்ணியமான இறுதிச் சேருமிடமும் உண்டு. அல்லாஹ்வின் கூற்று,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَرُسُلِهِ</span> <span class=\"quran-arabic-font text-success\">أُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الصِّدِّيقُونَ</span><br />\r\n(மேலும் அல்லாஹ்வையும் அவனுடைய தூதர்களையும் ஈமான் கொண்டவர்கள் - அவர்களே சித்தீக்குகள் (மிகவும் உண்மையாளர்கள்)) அல்லாஹ்வையும் அவனுடைய தூதர்களையும் நம்பியவர்களை, 'சித்தீக்குகள்' என்று விவரிப்பதன் மூலம் அவர்களது சிறப்பை அல்லாஹ் நிறைவு செய்கிறான். அல்-அவ்ஃபி அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து பின்வரும் வசனம் குறித்து அறிவிக்கிறார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَرُسُلِهِ</span> <span class=\"quran-arabic-font text-success\">أُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الصِّدِّيقُونَ</span><br />\r\n(மேலும் அல்லாஹ்வையும் அவனுடைய தூதர்களையும் ஈமான் கொண்டவர்கள் - அவர்களே சித்தீக்குகள்) இதன் பொருள் அடுத்த வசனத்துடன் தொடரவில்லை,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالشُّهَدَآءُ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِمْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَجْرُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَنُورُهُمْ</span><br />\r\n(மேலும் ஷஹீத்கள் தங்கள் இறைவனிடத்தில் இருக்கிறார்கள். அவர்களுக்குரிய நற்கூலியும் அவர்களது ஒளியும் அவர்களுக்கு உண்டு.)<br />\r\n<br />\r\nஅபூ அத்-துஹா அவர்கள் <span class=\"quran-arabic-font text-success\">أُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الصِّدِّيقُونَ</span> (அவர்களே சித்தீக்குகள்) என்று ஓதி நிறுத்திவிட்டு, பிறகு: <span class=\"quran-arabic-font text-success\">وَالشُّهَدَآءُ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِمْ</span> (மேலும் ஷஹீத்கள் தங்கள் இறைவனிடத்தில் இருக்கிறார்கள்) என்று ஓதத் தொடங்கினார்கள். மஸ்ரூக், அத்-தஹ்ஹாக், முகாதில் பின் ஹய்யான் போன்றோரும் இதையே கூறியுள்ளனர். அல்-அஃமஷ் அவர்கள் அபூ அத்-துஹா வழியாக மஸ்ரூக்கிடமிருந்து, அவர் அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்களிடமிருந்து அல்லாஹ்வின் இந்தக் கூற்றுப் பற்றி அறிவிக்கிறார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الصِّدِّيقُونَ</span> <span class=\"quran-arabic-font text-success\">وَالشُّهَدَآءُ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِمْ</span><br />\r\n(அவர்களே சித்தீக்குகள், மேலும் ஷஹீத்கள் தங்கள் இறைவனிடத்தில் இருக்கிறார்கள்.) \"அவர்கள் மூன்று பிரிவினர்,\" அதாவது தர்மம் செய்பவர்கள், சித்தீக்குகள் மற்றும் ஷஹீத்கள்.<br />\r\n<br />\r\nமேலான அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يُطِعِ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">وَالرَّسُولَ</span> <span class=\"quran-arabic-font text-success\">فَأُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">مَعَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">أَنْعَمَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِم</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">النَّبِيِّينَ</span> <span class=\"quran-arabic-font text-success\">وَالصِّدِّيقِينَ</span> <span class=\"quran-arabic-font text-success\">وَالشُّهَدَآءِ</span> <span class=\"quran-arabic-font text-success\">وَالصَّـلِحِينَ</span><br />\r\n(யார் அல்லாஹ்வுக்கும் அவனது தூதருக்கும் கீழ்ப்படிகிறார்களோ, அவர்கள் அல்லாஹ் அருள் புரிந்தவர்களான நபிமார்கள், சித்தீக்குகள், ஷஹீத்கள் மற்றும் ஸாலிஹீன்கள் (நல்லடியார்கள்) ஆகியோருடன் இருப்பார்கள்.) (<a href=\"qurandisp.php?sura=4&ayah=69\" class=\"link\">4:69</a>) எனவே, அல்லாஹ் சித்தீக்குகளுக்கும் ஷஹீத்களுக்கும் இடையில் ஒரு வேறுபாட்டை ஏற்படுத்தியுள்ளான். இது அவர்கள் இரு தனித்தனி நிலைகள் என்பதைக் காட்டுகிறது. ஷஹீதுகளை விட சித்தீக்குகளின் அந்தஸ்து மேலானது என்பதில் ஐயமில்லை.<br />\r\n<br />\r\nஇமாம் மாலிக் பின் அனஸ் அவர்கள் தமது 'முவத்தா'வில் பதிவு செய்துள்ளார்கள்: அபூ ஸயீத் அல்-குத்ரி (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">أَهْلَ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">لَيَتَرَاءَوْنَ</span> <span class=\"quran-arabic-font text-success\">أَهْلَ</span> <span class=\"quran-arabic-font text-success\">الْغُرَفِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">فَوْقِهِمْ،</span> <span class=\"quran-arabic-font text-success\">كَمَا</span> <span class=\"quran-arabic-font text-success\">تَتَرَاءَوْنَ</span> <span class=\"quran-arabic-font text-success\">الْكَوْكَبَ</span> <span class=\"quran-arabic-font text-success\">الدُّرِّيَّ</span> <span class=\"quran-arabic-font text-success\">الْغَابِرَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأُفُقِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمَشْرِقِ</span> <span class=\"quran-arabic-font text-success\">أَوِ</span> <span class=\"quran-arabic-font text-success\">الْمَغْرِبِ،</span> <span class=\"quran-arabic-font text-success\">لِتَفَاضُلِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُم</span>»<br />\r\n(சொர்க்கவாசிகள் தங்களுக்கு மேலேயுள்ள உயர்ந்த மாளிகைகளில் வசிப்பவர்களைப் பார்ப்பார்கள். அடிவானத்தில் கிழக்கிலோ அல்லது மேற்கிலோ வெகு தொலைவில் பிரகாசிக்கும் நட்சத்திரத்தை மக்கள் அண்ணாந்து பார்ப்பது போல், அவர்களுக்கு மத்தியிலுள்ள அந்தஸ்து வேறுபாட்டின் காரணமாக இது அமையும்.) அதைக் கேட்ட மக்கள், \"அல்லாஹ்வின் தூதரே! இந்த உயர்ந்த மாளிகைகள் நபிமார்களுக்கு (அலை) மட்டுமானதா? மற்றவர்களால் அதை அடைய முடியாதா?\" என்று கேட்டார்கள். நபி (ஸல்) அவர்கள் கூறினார்கள்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">بَلَى،</span> <span class=\"quran-arabic-font text-success\">وَالَّذِي</span> <span class=\"quran-arabic-font text-success\">نَفْسِي</span> <span class=\"quran-arabic-font text-success\">بِيَدِهِ،</span> <span class=\"quran-arabic-font text-success\">رِجَالٌ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span> <span class=\"quran-arabic-font text-success\">بِاللهِ</span> <span class=\"quran-arabic-font text-success\">وَصَدَّقُوا</span> <span class=\"quran-arabic-font text-success\">الْمُرْسَلِين</span>»<br />\r\n(இல்லை! என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக! இவை அல்லாஹ்வை ஈமான் கொண்டு, தூதர்களை உண்மைப்படுத்திய மனிதர்களுக்கானவை.) அல்-புஹாரி மற்றும் முஸ்லிம் ஆகியோரும் இந்த ஹதீஸைப் பதிவு செய்துள்ளனர்.<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்று,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالشُّهَدَآءُ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِمْ</span><br />\r\n(மேலும் ஷஹீத்கள் தங்கள் இறைவனிடத்தில் இருக்கிறார்கள்.) இதன் பொருள், இமாம் முஸ்லிம் அவர்கள் தமது ஸஹீஹ் நூலில் பதிவு செய்துள்ளபடி, அவர்கள் சொர்க்கத்தின் சோலைகளில் இருப்பார்கள் என்பதாகும்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">أَرْوَاحَ</span> <span class=\"quran-arabic-font text-success\">الشُّهَدَاءِ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">حَوَاصِلِ</span> <span class=\"quran-arabic-font text-success\">طَيْرٍ</span> <span class=\"quran-arabic-font text-success\">خُضْرٍ</span> <span class=\"quran-arabic-font text-success\">تَسْرَحُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">حَيْثُ</span> <span class=\"quran-arabic-font text-success\">شَاءَتْ،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">تَأْوِي</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">تِلْكَ</span> <span class=\"quran-arabic-font text-success\">الْقَنَادِيلِ</span> <span class=\"quran-arabic-font text-success\">فَاطَّلَعَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">رَبُّكَ</span> <span class=\"quran-arabic-font text-success\">اطِّلَاعَةً</span> <span class=\"quran-arabic-font text-success\">فَقَالَ</span>: <span class=\"quran-arabic-font text-success\">مَاذَا</span> <span class=\"quran-arabic-font text-success\">تُرِيدُونَ؟</span> <span class=\"quran-arabic-font text-success\">فَقَالُوا</span>: <span class=\"quran-arabic-font text-success\">نُحِبُّ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">تَرُدَّنَا</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الدَّارِ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">فَنُقَاتِلَ</span> <span class=\"quran-arabic-font text-success\">فِيكَ</span> <span class=\"quran-arabic-font text-success\">فَنُقْتَلَ،</span> <span class=\"quran-arabic-font text-success\">كَمَا</span> <span class=\"quran-arabic-font text-success\">قُتِلْنَا</span> <span class=\"quran-arabic-font text-success\">أَوَّلَ</span> <span class=\"quran-arabic-font text-success\">مَرَّةٍ،</span> <span class=\"quran-arabic-font text-success\">فَقَالَ</span>: <span class=\"quran-arabic-font text-success\">إِنِّي</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">قَضَيْتُ</span> <span class=\"quran-arabic-font text-success\">أَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهَا</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَرْجِعُون</span>»<br />\r\n(ஷஹீத்களின் ஆன்மாக்கள் பச்சை நிறப் பறவைகளின் உடல்களில் இருக்கும். அவை சொர்க்கத்தில் தாம் விரும்பும் இடங்களுக்கெல்லாம் சென்றுவிட்டு, பிறகு சரவிளக்குகளில் வந்து தங்கும். ஒருமுறை உமது இறைவன் அவர்களை உற்று நோக்கி, 'உங்களுக்கு ஏதேனும் வேண்டுமா?' என்று கேட்பான். அதற்கு அவர்கள், 'நாங்கள் மீண்டும் உலகிற்கு அனுப்பப்பட்டு, உனது பாதையில் போரிட்டு, முதல் முறை கொல்லப்பட்டதைப் போலவே மீண்டும் கொல்லப்படுவதை விரும்புகிறோம்' என்பார்கள். அப்போது அல்லாஹ், 'அவர்கள் மீண்டும் உலகிற்குத் திரும்ப மாட்டார்கள் என்று நான் ஏற்கனவே விதித்துவிட்டேன்' என்று கூறுவான்.)<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்று,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَجْرُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَنُورُهُمْ</span><br />\r\n(அவர்களுக்குரிய நற்கூலியும் அவர்களது ஒளியும் அவர்களுக்கு உண்டு.) அதாவது, அல்லாஹ் அவர்களுக்கு மகத்தான நற்கூலியையும், அவர்களுக்கு முன்பாகச் செல்லும் பெரும் ஒளியையும் வழங்குவான். இதில் முஃமின்கள் இவ்வுலகில் அவர்கள் செய்த நற்செயல்களுக்கு ஏற்ப, அவர்கள் பெறும் ஒளியின் அளவில் வேறுபடுவார்கள்.<br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள் கூறினார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறக் கேட்டேன்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الشُّهَدَاءُ</span> <span class=\"quran-arabic-font text-success\">أَرْبَعَةٌ</span>: <span class=\"quran-arabic-font text-success\">رَجُلٌ</span> <span class=\"quran-arabic-font text-success\">مُؤْمِنٌ</span> <span class=\"quran-arabic-font text-success\">جَيِّدُ</span> <span class=\"quran-arabic-font text-success\">الْإِيمَانِ،</span> <span class=\"quran-arabic-font text-success\">لَقِيَ</span> <span class=\"quran-arabic-font text-success\">الْعَدُوَّ</span> <span class=\"quran-arabic-font text-success\">فَصَدَقَ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">فَقُتِلَ،</span> <span class=\"quran-arabic-font text-success\">فَذَاكَ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">يَنْظُرُ</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">هكَذَا</span>»<br />\r\n(ஷஹீத்கள் நான்கு தரங்களை உடையவர்கள்: முதலாவது, உண்மையான ஈமான் கொண்ட ஒரு முஃமின். அவர் எதிரியைச் சந்தித்து அல்லாஹ்விடம் உண்மையாக இருந்து போரிட்டுக் கொல்லப்படுகிறார். மக்கள் அண்ணாந்து பார்த்து வியக்கும் அந்தஸ்தில் அவர் இருப்பார்.) இதைக் கூறும்போது நபி (ஸல்) அவர்கள் தமது தொப்பி விழும் அளவுக்குத் தலையை உயர்த்தினார்கள். உமர் (ரழி) அவர்களுக்கும் அவ்வாறே நடந்தது. நபி (ஸல்) அவர்கள் தொடர்ந்தார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَالثَّانِي</span> <span class=\"quran-arabic-font text-success\">مُؤْمِنٌ</span> <span class=\"quran-arabic-font text-success\">لَقِيَ</span> <span class=\"quran-arabic-font text-success\">الْعَدُوَّ</span> <span class=\"quran-arabic-font text-success\">فَكَأَنَّمَا</span> <span class=\"quran-arabic-font text-success\">يُضْرَبُ</span> <span class=\"quran-arabic-font text-success\">ظَهْرُهُ</span> <span class=\"quran-arabic-font text-success\">بِشَوْكِ</span> <span class=\"quran-arabic-font text-success\">الطَّلْحِ،</span> <span class=\"quran-arabic-font text-success\">جَاءَهُ</span> <span class=\"quran-arabic-font text-success\">سَهْمٌ</span> <span class=\"quran-arabic-font text-success\">غَرْبٌ</span> <span class=\"quran-arabic-font text-success\">فَقَتَلَهُ،</span> <span class=\"quran-arabic-font text-success\">فَذَاكَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الدَّرَجَةِ</span> <span class=\"quran-arabic-font text-success\">الثَّانِيَةِ</span>. <span class=\"quran-arabic-font text-success\">وَالثَّالِثُ</span> <span class=\"quran-arabic-font text-success\">رَجُلٌ</span> <span class=\"quran-arabic-font text-success\">مُؤْمِنٌ</span> <span class=\"quran-arabic-font text-success\">خَلَطَ</span> <span class=\"quran-arabic-font text-success\">عَمَلًا</span> <span class=\"quran-arabic-font text-success\">صَالِحًا</span> <span class=\"quran-arabic-font text-success\">وَآخَرَ</span> <span class=\"quran-arabic-font text-success\">سَيِّئًا،</span> <span class=\"quran-arabic-font text-success\">لَقِيَ</span> <span class=\"quran-arabic-font text-success\">الْعَدُوَّ</span> <span class=\"quran-arabic-font text-success\">فَصَدَقَ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">حَتْى</span> <span class=\"quran-arabic-font text-success\">قُتِلَ،</span> <span class=\"quran-arabic-font text-success\">فَذَاكَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الدَّرَجَةِ</span> <span class=\"quran-arabic-font text-success\">الثَّالِثَةِ</span>. <span class=\"quran-arabic-font text-success\">وَالرَّابِعُ</span> <span class=\"quran-arabic-font text-success\">رَجُلٌ</span> <span class=\"quran-arabic-font text-success\">مُؤْمِنٌ</span> <span class=\"quran-arabic-font text-success\">أَسْرَفَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">نَفْسِهِ</span> <span class=\"quran-arabic-font text-success\">إِسْرَافًا</span> <span class=\"quran-arabic-font text-success\">كَثِيرًا،</span> <span class=\"quran-arabic-font text-success\">لَقِيَ</span> <span class=\"quran-arabic-font text-success\">الْعَدُوَّ</span> <span class=\"quran-arabic-font text-success\">فَصَدَقَ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">حَتْى</span> <span class=\"quran-arabic-font text-success\">قُتِلَ،</span> <span class=\"quran-arabic-font text-success\">فَذَاكَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الدَّرَجَةِ</span> <span class=\"quran-arabic-font text-success\">الرَّابِعَة</span>»<br />\r\n(இரண்டாவது, ஒரு முஃமின் எதிரியைச் சந்திக்கிறார்; அவர் (பயத்தினால்) கருவேல மரத்தின் முள்ளால் தன் முதுகில் அடிக்கப்படுவது போன்று உணர்கிறார்; அப்போது எங்கிருந்தோ வந்த அம்பு அவர் மீது பட்டு அவர் இறக்கிறார். இவர் இரண்டாம் நிலையில் உள்ளவர். மூன்றாவது, நற்செயல்களையும் தீய செயல்களையும் கலந்து செய்த ஒரு முஃமின்; அவர் எதிரியைச் சந்தித்து, கொல்லப்படும் வரை அல்லாஹ்விடம் உண்மையாக இருக்கிறார். இவர் மூன்றாம் நிலையில் உள்ளவர். நான்காவது, தமக்குத் தாமே அநியாயம் செய்து (பாவங்கள் செய்து) வரம்பு மீறிய ஒரு முஃமின்; அவர் எதிரியைச் சந்தித்து, கொல்லப்படும் வரை அல்லாஹ்விடம் உண்மையாக இருக்கிறார். இவர் நான்காம் நிலையில் உள்ளவர்.)<br />\r\n<br />\r\nஅலி பின் அல்-மதீனி அவர்களும் இந்த ஹதீஸை அறிவித்துவிட்டு, \"இந்த எகிப்திய அறிவிப்பாளர் தொடர் ஸாலிஹ் (ஏற்றுக்கொள்ளத்தக்கது)\" என்றார். அத்-திர்மிதி அவர்கள் இது \"ஹஸன் ஃகரீப்\" என்று கூறியுள்ளார்.<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்று,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">وَكَذَّبُواْ</span> <span class=\"quran-arabic-font text-success\">بِآيَاتِنَا</span> <span class=\"quran-arabic-font text-success\">أُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">أَصْحَـبُ</span> <span class=\"quran-arabic-font text-success\">الْجَحِيمِ</span><br />\r\n(மேலும் எவர் நிராகரித்து, நமது வசனங்களைப் பொய்யாக்கினார்களோ அவர்களே நரகவாசிகள்.) நற்பேறு பெற்றவர்களின் நிலையையும் அவர்களுக்குரிய நற்கூலிகளையும் குறிப்பிட்ட பிறகு, துரதிர்ஷ்டசாலிகளின் இறுதி நிலையையும் அவர்களது சேருமிடத்தையும் அல்லாஹ் இங்கே குறிப்பிடுகிறான்.<br />\r\n<br />","text":"தர்மம் செய்பவர்கள், உண்மையாளர்கள் மற்றும் ஷஹீத்களுக்கான வெகுமதி; மற்றும் நிராகரிப்பாளர்களின் சேருமிடம்\n\r\n\n\r\nإِنَّ الْمُصَّدِّقِينَ وَالْمُصَّدِّقَاتِ\n\r\n(நிச்சயமாக தர்மம் செய்யும் ஆண்களும், தர்மம் செய்யும் பெண்களும்)\n\r\nதேவையுடையவர்கள், ஏழைகள் மற்றும் எளியவர்களுக்காகத் தங்கள் செல்வத்திலிருந்து செலவு செய்யும் ஆண்கள் மற்றும் பெண்களுக்கு மேலான அல்லாஹ் வழங்கவிருக்கும் வெகுமதியைப் பற்றி அவன் விவரிக்கிறான்.\n\r\n\n\r\nوَأَقْرَضُوا اللَّهَ قَرْضاً حَسَناً\n\r\n(மேலும் அல்லாஹ்வுக்கு அழகிய கடன் கொடுத்தார்களே அவர்கள்,) அதாவது, அவர்கள் அல்லாஹ்வின் திருப்தியை நாடித் தூய உள்ளத்துடன் தர்மம் செய்கிறார்கள். அவர்கள் உலகியல் வெகுமதிகளையோ அல்லது யாரிடம் தர்மம் செய்கிறார்களோ அவர்களிடமிருந்து பாராட்டையோ எதிர்பார்ப்பதில்லை. அல்லாஹ்வின் கூற்று,\n\r\n\n\r\nيُضَاعَفُ لَهُمْ\n\r\n(அது அவர்களுக்குப் பன்மடங்காகப் பெருக்கப்படும்,) அதாவது, அவன் நற்செயல்களைப் பத்து மடங்கிலிருந்து, எழுநூறு மடங்கு வரையிலும், அதற்கும் மேலாகவும் பெருக்குவான் என்பதைக் குறிக்கிறது.\n\r\n\n\r\nوَلَهُمْ أَجْرٌ كَرِيمٌ\n\r\n(மேலும் அவர்களுக்குக் கண்ணியமான நற்கூலி உண்டு.) அவர்களுக்குத் தாராளமான, அழகான வெகுமதியும், அவர்கள் திரும்பிச் செல்ல ஒரு நல்ல தங்குமிடமும், கண்ணியமான இறுதிச் சேருமிடமும் உண்டு. அல்லாஹ்வின் கூற்று,\n\r\n\n\r\nوَالَّذِينَ ءَامَنُواْ بِاللَّهِ وَرُسُلِهِ أُوْلَـئِكَ هُمُ الصِّدِّيقُونَ\n\r\n(மேலும் அல்லாஹ்வையும் அவனுடைய தூதர்களையும் ஈமான் கொண்டவர்கள் - அவர்களே சித்தீக்குகள் (மிகவும் உண்மையாளர்கள்)) அல்லாஹ்வையும் அவனுடைய தூதர்களையும் நம்பியவர்களை, 'சித்தீக்குகள்' என்று விவரிப்பதன் மூலம் அவர்களது சிறப்பை அல்லாஹ் நிறைவு செய்கிறான். அல்-அவ்ஃபி அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து பின்வரும் வசனம் குறித்து அறிவிக்கிறார்கள்:\n\r\n\n\r\nوَالَّذِينَ ءَامَنُواْ بِاللَّهِ وَرُسُلِهِ أُوْلَـئِكَ هُمُ الصِّدِّيقُونَ\n\r\n(மேலும் அல்லாஹ்வையும் அவனுடைய தூதர்களையும் ஈமான் கொண்டவர்கள் - அவர்களே சித்தீக்குகள்) இதன் பொருள் அடுத்த வசனத்துடன் தொடரவில்லை,\n\r\n\n\r\nوَالشُّهَدَآءُ عِندَ رَبِّهِمْ لَهُمْ أَجْرُهُمْ وَنُورُهُمْ\n\r\n(மேலும் ஷஹீத்கள் தங்கள் இறைவனிடத்தில் இருக்கிறார்கள். அவர்களுக்குரிய நற்கூலியும் அவர்களது ஒளியும் அவர்களுக்கு உண்டு.)\n\r\n\n\r\nஅபூ அத்-துஹா அவர்கள் أُوْلَـئِكَ هُمُ الصِّدِّيقُونَ (அவர்களே சித்தீக்குகள்) என்று ஓதி நிறுத்திவிட்டு, பிறகு: وَالشُّهَدَآءُ عِندَ رَبِّهِمْ (மேலும் ஷஹீத்கள் தங்கள் இறைவனிடத்தில் இருக்கிறார்கள்) என்று ஓதத் தொடங்கினார்கள். மஸ்ரூக், அத்-தஹ்ஹாக், முகாதில் பின் ஹய்யான் போன்றோரும் இதையே கூறியுள்ளனர். அல்-அஃமஷ் அவர்கள் அபூ அத்-துஹா வழியாக மஸ்ரூக்கிடமிருந்து, அவர் அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்களிடமிருந்து அல்லாஹ்வின் இந்தக் கூற்றுப் பற்றி அறிவிக்கிறார்கள்:\n\r\n\n\r\nأُوْلَـئِكَ هُمُ الصِّدِّيقُونَ وَالشُّهَدَآءُ عِندَ رَبِّهِمْ\n\r\n(அவர்களே சித்தீக்குகள், மேலும் ஷஹீத்கள் தங்கள் இறைவனிடத்தில் இருக்கிறார்கள்.) \"அவர்கள் மூன்று பிரிவினர்,\" அதாவது தர்மம் செய்பவர்கள், சித்தீக்குகள் மற்றும் ஷஹீத்கள்.\n\r\n\n\r\nமேலான அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَمَن يُطِعِ اللَّهَ وَالرَّسُولَ فَأُوْلَـئِكَ مَعَ الَّذِينَ أَنْعَمَ اللَّهُ عَلَيْهِم مِّنَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَآءِ وَالصَّـلِحِينَ\n\r\n(யார் அல்லாஹ்வுக்கும் அவனது தூதருக்கும் கீழ்ப்படிகிறார்களோ, அவர்கள் அல்லாஹ் அருள் புரிந்தவர்களான நபிமார்கள், சித்தீக்குகள், ஷஹீத்கள் மற்றும் ஸாலிஹீன்கள் (நல்லடியார்கள்) ஆகியோருடன் இருப்பார்கள்.) (4:69) எனவே, அல்லாஹ் சித்தீக்குகளுக்கும் ஷஹீத்களுக்கும் இடையில் ஒரு வேறுபாட்டை ஏற்படுத்தியுள்ளான். இது அவர்கள் இரு தனித்தனி நிலைகள் என்பதைக் காட்டுகிறது. ஷஹீதுகளை விட சித்தீக்குகளின் அந்தஸ்து மேலானது என்பதில் ஐயமில்லை.\n\r\n\n\r\nஇமாம் மாலிக் பின் அனஸ் அவர்கள் தமது 'முவத்தா'வில் பதிவு செய்துள்ளார்கள்: அபூ ஸயீத் அல்-குத்ரி (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنَّ أَهْلَ الْجَنَّةِ لَيَتَرَاءَوْنَ أَهْلَ الْغُرَفِ مِنْ فَوْقِهِمْ، كَمَا تَتَرَاءَوْنَ الْكَوْكَبَ الدُّرِّيَّ الْغَابِرَ فِي الْأُفُقِ مِنَ الْمَشْرِقِ أَوِ الْمَغْرِبِ، لِتَفَاضُلِ مَا بَيْنَهُم»\n\r\n(சொர்க்கவாசிகள் தங்களுக்கு மேலேயுள்ள உயர்ந்த மாளிகைகளில் வசிப்பவர்களைப் பார்ப்பார்கள். அடிவானத்தில் கிழக்கிலோ அல்லது மேற்கிலோ வெகு தொலைவில் பிரகாசிக்கும் நட்சத்திரத்தை மக்கள் அண்ணாந்து பார்ப்பது போல், அவர்களுக்கு மத்தியிலுள்ள அந்தஸ்து வேறுபாட்டின் காரணமாக இது அமையும்.) அதைக் கேட்ட மக்கள், \"அல்லாஹ்வின் தூதரே! இந்த உயர்ந்த மாளிகைகள் நபிமார்களுக்கு (அலை) மட்டுமானதா? மற்றவர்களால் அதை அடைய முடியாதா?\" என்று கேட்டார்கள். நபி (ஸல்) அவர்கள் கூறினார்கள்,\n\r\n\n\r\n«بَلَى، وَالَّذِي نَفْسِي بِيَدِهِ، رِجَالٌ آمَنُوا بِاللهِ وَصَدَّقُوا الْمُرْسَلِين»\n\r\n(இல்லை! என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக! இவை அல்லாஹ்வை ஈமான் கொண்டு, தூதர்களை உண்மைப்படுத்திய மனிதர்களுக்கானவை.) அல்-புஹாரி மற்றும் முஸ்லிம் ஆகியோரும் இந்த ஹதீஸைப் பதிவு செய்துள்ளனர்.\n\r\n\n\r\nஅல்லாஹ்வின் கூற்று,\n\r\n\n\r\nوَالشُّهَدَآءُ عِندَ رَبِّهِمْ\n\r\n(மேலும் ஷஹீத்கள் தங்கள் இறைவனிடத்தில் இருக்கிறார்கள்.) இதன் பொருள், இமாம் முஸ்லிம் அவர்கள் தமது ஸஹீஹ் நூலில் பதிவு செய்துள்ளபடி, அவர்கள் சொர்க்கத்தின் சோலைகளில் இருப்பார்கள் என்பதாகும்:\n\r\n\n\r\n«إِنَّ أَرْوَاحَ الشُّهَدَاءِ فِي حَوَاصِلِ طَيْرٍ خُضْرٍ تَسْرَحُ فِي الْجَنَّةِ حَيْثُ شَاءَتْ، ثُمَّ تَأْوِي إِلَى تِلْكَ الْقَنَادِيلِ فَاطَّلَعَ عَلَيْهِمْ رَبُّكَ اطِّلَاعَةً فَقَالَ: مَاذَا تُرِيدُونَ؟ فَقَالُوا: نُحِبُّ أَنْ تَرُدَّنَا إِلَى الدَّارِ الدُّنْيَا فَنُقَاتِلَ فِيكَ فَنُقْتَلَ، كَمَا قُتِلْنَا أَوَّلَ مَرَّةٍ، فَقَالَ: إِنِّي قَدْ قَضَيْتُ أَنَّهُمْ إِلَيْهَا لَا يَرْجِعُون»\n\r\n(ஷஹீத்களின் ஆன்மாக்கள் பச்சை நிறப் பறவைகளின் உடல்களில் இருக்கும். அவை சொர்க்கத்தில் தாம் விரும்பும் இடங்களுக்கெல்லாம் சென்றுவிட்டு, பிறகு சரவிளக்குகளில் வந்து தங்கும். ஒருமுறை உமது இறைவன் அவர்களை உற்று நோக்கி, 'உங்களுக்கு ஏதேனும் வேண்டுமா?' என்று கேட்பான். அதற்கு அவர்கள், 'நாங்கள் மீண்டும் உலகிற்கு அனுப்பப்பட்டு, உனது பாதையில் போரிட்டு, முதல் முறை கொல்லப்பட்டதைப் போலவே மீண்டும் கொல்லப்படுவதை விரும்புகிறோம்' என்பார்கள். அப்போது அல்லாஹ், 'அவர்கள் மீண்டும் உலகிற்குத் திரும்ப மாட்டார்கள் என்று நான் ஏற்கனவே விதித்துவிட்டேன்' என்று கூறுவான்.)\n\r\n\n\r\nஅல்லாஹ்வின் கூற்று,\n\r\n\n\r\nلَهُمْ أَجْرُهُمْ وَنُورُهُمْ\n\r\n(அவர்களுக்குரிய நற்கூலியும் அவர்களது ஒளியும் அவர்களுக்கு உண்டு.) அதாவது, அல்லாஹ் அவர்களுக்கு மகத்தான நற்கூலியையும், அவர்களுக்கு முன்பாகச் செல்லும் பெரும் ஒளியையும் வழங்குவான். இதில் முஃமின்கள் இவ்வுலகில் அவர்கள் செய்த நற்செயல்களுக்கு ஏற்ப, அவர்கள் பெறும் ஒளியின் அளவில் வேறுபடுவார்கள்.\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள் கூறினார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறக் கேட்டேன்:\n\r\n\n\r\n«الشُّهَدَاءُ أَرْبَعَةٌ: رَجُلٌ مُؤْمِنٌ جَيِّدُ الْإِيمَانِ، لَقِيَ الْعَدُوَّ فَصَدَقَ اللهَ فَقُتِلَ، فَذَاكَ الَّذِي يَنْظُرُ النَّاسُ إِلَيْهِ هكَذَا»\n\r\n(ஷஹீத்கள் நான்கு தரங்களை உடையவர்கள்: முதலாவது, உண்மையான ஈமான் கொண்ட ஒரு முஃமின். அவர் எதிரியைச் சந்தித்து அல்லாஹ்விடம் உண்மையாக இருந்து போரிட்டுக் கொல்லப்படுகிறார். மக்கள் அண்ணாந்து பார்த்து வியக்கும் அந்தஸ்தில் அவர் இருப்பார்.) இதைக் கூறும்போது நபி (ஸல்) அவர்கள் தமது தொப்பி விழும் அளவுக்குத் தலையை உயர்த்தினார்கள். உமர் (ரழி) அவர்களுக்கும் அவ்வாறே நடந்தது. நபி (ஸல்) அவர்கள் தொடர்ந்தார்கள்:\n\r\n\n\r\n«وَالثَّانِي مُؤْمِنٌ لَقِيَ الْعَدُوَّ فَكَأَنَّمَا يُضْرَبُ ظَهْرُهُ بِشَوْكِ الطَّلْحِ، جَاءَهُ سَهْمٌ غَرْبٌ فَقَتَلَهُ، فَذَاكَ فِي الدَّرَجَةِ الثَّانِيَةِ. وَالثَّالِثُ رَجُلٌ مُؤْمِنٌ خَلَطَ عَمَلًا صَالِحًا وَآخَرَ سَيِّئًا، لَقِيَ الْعَدُوَّ فَصَدَقَ اللهَ حَتْى قُتِلَ، فَذَاكَ فِي الدَّرَجَةِ الثَّالِثَةِ. وَالرَّابِعُ رَجُلٌ مُؤْمِنٌ أَسْرَفَ عَلَى نَفْسِهِ إِسْرَافًا كَثِيرًا، لَقِيَ الْعَدُوَّ فَصَدَقَ اللهَ حَتْى قُتِلَ، فَذَاكَ فِي الدَّرَجَةِ الرَّابِعَة»\n\r\n(இரண்டாவது, ஒரு முஃமின் எதிரியைச் சந்திக்கிறார்; அவர் (பயத்தினால்) கருவேல மரத்தின் முள்ளால் தன் முதுகில் அடிக்கப்படுவது போன்று உணர்கிறார்; அப்போது எங்கிருந்தோ வந்த அம்பு அவர் மீது பட்டு அவர் இறக்கிறார். இவர் இரண்டாம் நிலையில் உள்ளவர். மூன்றாவது, நற்செயல்களையும் தீய செயல்களையும் கலந்து செய்த ஒரு முஃமின்; அவர் எதிரியைச் சந்தித்து, கொல்லப்படும் வரை அல்லாஹ்விடம் உண்மையாக இருக்கிறார். இவர் மூன்றாம் நிலையில் உள்ளவர். நான்காவது, தமக்குத் தாமே அநியாயம் செய்து (பாவங்கள் செய்து) வரம்பு மீறிய ஒரு முஃமின்; அவர் எதிரியைச் சந்தித்து, கொல்லப்படும் வரை அல்லாஹ்விடம் உண்மையாக இருக்கிறார். இவர் நான்காம் நிலையில் உள்ளவர்.)\n\r\n\n\r\nஅலி பின் அல்-மதீனி அவர்களும் இந்த ஹதீஸை அறிவித்துவிட்டு, \"இந்த எகிப்திய அறிவிப்பாளர் தொடர் ஸாலிஹ் (ஏற்றுக்கொள்ளத்தக்கது)\" என்றார். அத்-திர்மிதி அவர்கள் இது \"ஹஸன் ஃகரீப்\" என்று கூறியுள்ளார்.\n\r\n\n\r\nஅல்லாஹ்வின் கூற்று,\n\r\n\n\r\nوَالَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِآيَاتِنَا أُوْلَـئِكَ أَصْحَـبُ الْجَحِيمِ\n\r\n(மேலும் எவர் நிராகரித்து, நமது வசனங்களைப் பொய்யாக்கினார்களோ அவர்களே நரகவாசிகள்.) நற்பேறு பெற்றவர்களின் நிலையையும் அவர்களுக்குரிய நற்கூலிகளையும் குறிப்பிட்ட பிறகு, துரதிர்ஷ்டசாலிகளின் இறுதி நிலையையும் அவர்களது சேருமிடத்தையும் அல்லாஹ் இங்கே குறிப்பிடுகிறான்."},"20":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=57&ayah=21\" class=\"link\">57:21</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 57:21 ஐ பார்க்கவும்"},"21":{"html":"<strong>இவ்வுலக வாழ்க்கை ஒரு அற்பமான இன்பமே</strong><br />\r\n<br />\r\nஉயர்ந்தோனாகிய அல்லாஹ் இவ்வுலக வாழ்க்கையின் முக்கியத்துவத்தைக் குறைத்து, அதனை அற்பமானதாகக் கருதி இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">اعْلَمُوا</span> <span class=\"quran-arabic-font text-success\">أَنَّمَا</span> <span class=\"quran-arabic-font text-success\">الْحَيَاةُ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">لَعِبٌ</span> <span class=\"quran-arabic-font text-success\">وَلَهْوٌ</span> <span class=\"quran-arabic-font text-success\">وَزِينَةٌ</span> <span class=\"quran-arabic-font text-success\">وَتَفَاخُرٌ</span> <span class=\"quran-arabic-font text-success\">بَيْنَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَتَكَاثُرٌ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَمْوَالِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَوْلَادِ</span><br />\r\n<br />\r\n(அறிந்து கொள்ளுங்கள்! நிச்சயமாக இவ்வுலக வாழ்க்கை விளையாட்டும், வேடிக்கையும், அலங்காரமும், உங்களுக்கு இடையில் பெருமையடித்துக் கொள்வதும், செல்வங்களிலும் பிள்ளைகளிலும் ஒருவரையொருவர் மிஞ்சத் துடிப்பதுமேயாகும்.) அதாவது, இவ்வுலகில் வாழ்பவர்களுக்கு இதன் நிலை இதுதான். மற்றொரு வசனத்தில் அல்லாஹ் கூறியிருப்பதைப் போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">زُيِّنَ</span> <span class=\"quran-arabic-font text-success\">لِلنَّاسِ</span> <span class=\"quran-arabic-font text-success\">حُبُّ</span> <span class=\"quran-arabic-font text-success\">الشَّهَوَاتِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">النِّسَاءِ</span> <span class=\"quran-arabic-font text-success\">وَالْبَنِينَ</span> <span class=\"quran-arabic-font text-success\">وَالْقَنَاطِيرِ</span> <span class=\"quran-arabic-font text-success\">الْمُقَنطَرَةِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الذَّهَبِ</span> <span class=\"quran-arabic-font text-success\">وَالْفِضَّةِ</span> <span class=\"quran-arabic-font text-success\">وَالْخَيْلِ</span> <span class=\"quran-arabic-font text-success\">الْمُسَوَّمَةِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَنْعَامِ</span> <span class=\"quran-arabic-font text-success\">وَالْحَرْثِ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">مَتَاعُ</span> <span class=\"quran-arabic-font text-success\">الْحَيَاةِ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">عِندَهُ</span> <span class=\"quran-arabic-font text-success\">حُسْنُ</span> <span class=\"quran-arabic-font text-success\">الْمَآبِ</span><br />\r\n<br />\r\n(பெண்கள், ஆண் மக்கள், தங்கம் மற்றும் வெள்ளியின் பெருங்குவியல்கள், அடையாளமிடப்பட்ட அழகிய குதிரைகள், கால்நடைகள் மற்றும் விளைநிலங்கள் போன்ற இச்சையூட்டும் பொருட்கள் மீதுள்ள ஆசை மனிதர்களுக்கு அழகாக்கப்பட்டுள்ளது. இவை இவ்வுலக வாழ்க்கையின் அற்ப இன்பங்களாகும்; ஆனால் அல்லாஹ்விடமோ மிகச் சிறந்த தங்குமிடம் இருக்கிறது.) (<a href=\"qurandisp.php?sura=3&ayah=14\" class=\"link\">3:14</a>) உயர்ந்தோனாகிய அல்லாஹ் இவ்வுலக வாழ்க்கைக்கு ஓர் உவமையைக் கூறுகிறான்; அதன் மகிழ்ச்சிகள் மங்கிவிடக்கூடியவை என்றும் அதன் இன்பங்கள் அழியக்கூடியவை என்றும் கூறி, வாழ்க்கை என்பது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَمَثَلِ</span> <span class=\"quran-arabic-font text-success\">غَيْثٍ</span><br />\r\n<br />\r\n(ஒரு மழையைப் (கய்ஸ்) போன்றது.) இது மனிதர்கள் நம்பிக்கையிழந்த பிறகு அவர்களுக்கு இறங்கும் மழையாகும். உயர்ந்தோனாகிய அல்லாஹ் வேறொரு வசனத்தில் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يُنَزِّلُ</span> <span class=\"quran-arabic-font text-success\">الْغَيْثَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">قَنَطُواْ</span><br />\r\n<br />\r\n(அவர்கள் நம்பிக்கையிழந்த பிறகு மழையை (கய்ஸ்) இறக்குபவன் அவனே.) (<a href=\"qurandisp.php?sura=42&ayah=28\" class=\"link\">42:28</a>) அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَعْجَبَ</span> <span class=\"quran-arabic-font text-success\">الْكُفَّارَ</span> <span class=\"quran-arabic-font text-success\">نَبَاتُهُ</span><br />\r\n<br />\r\n(அம்மழையினால் விளைந்த பயிர்கள் விவசாயிகளுக்கு மகிழ்ச்சியளிக்கின்றன;) அதாவது, மழைக்குப் பிறகு செழித்து வளரும் பயிர்களை விவசாயிகள் கண்டு வியக்கிறார்கள். விவசாயிகள் பயிர்களைக் கண்டு வியப்பது போலவே, இறைநிராகரிப்பாளர்கள் இவ்வுலக வாழ்க்கையைக் கண்டு வியக்கிறார்கள்; அவர்கள் இவ்வுலகின் இன்பங்களைப் பெறுவதில் மிகுந்த ஆர்வம் கொண்டவர்களாக இருக்கிறார்கள், மேலும் இவ்வுலகமே அவர்களுக்கு மிகவும் பிரியமானதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يَهِيجُ</span> <span class=\"quran-arabic-font text-success\">فَتَرَاهُ</span> <span class=\"quran-arabic-font text-success\">مُصْفَرّاً</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يَكُونُ</span> <span class=\"quran-arabic-font text-success\">حُطَاماً</span><br />\r\n<br />\r\n(பின்னர் அது காய்ந்து, அது மஞ்சள் நிறமாக மாறுவதை நீர் காண்பீர்; பிறகு அது சருகுகளாகிவிடுகிறது.) அதாவது, அந்தப் பயிர் பசுமையாக இருந்த பிறகு, விரைவில் மஞ்சள் நிறமாக மாறிவிடுகிறது. அதன் பிறகு, அந்தப் பசுமை மறைந்து சிதறிய தூசிகளாகி விடுகிறது. இதுதான் இவ்வுலக வாழ்க்கைக்குரிய உவமை; அது இளமையாகத் தொடங்கி, பிறகு முதிர்ச்சியடைந்து, இறுதியில் முதுமையையும் பலவீனத்தையும் அடைகிறது. இது இவ்வுலகில் மனிதனுக்கும் உவமையாகும்; மனிதன் ஆரம்பத்தில் இளமையாகவும் வலிமையாகவும் இருக்கிறான். அக்கட்டத்தில் அவன் அழகாகவும் பொலிவோடும் காணப்படுகிறான். மெதுவாக அவனுக்கு வயதாகத் தொடங்குகிறது, அவனது சுபாவங்கள் மாறுகின்றன, அவனது வலிமை குறைகிறது. பின்னர் அவன் மிகவும் முதுமையடைந்து பலவீனமாகிறான்; அவனுக்கு அசைவது கூட சிரமமாகிறது, மிக எளிய காரியங்களைக் கூட அவனால் செய்ய முடியாமல் போகிறது. உயர்ந்தோனாகிய அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">خَلَقَكُم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">ضَعْفٍ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">ضَعْفٍ</span> <span class=\"quran-arabic-font text-success\">قُوَّةً</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">قُوَّةٍ</span> <span class=\"quran-arabic-font text-success\">ضَعْفًا</span> <span class=\"quran-arabic-font text-success\">وَشَيْبَةً</span> <span class=\"quran-arabic-font text-success\">ۚ</span> <span class=\"quran-arabic-font text-success\">يَخْلُقُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَشَاءُ</span> <span class=\"quran-arabic-font text-success\">ۖ</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْعَلِيمُ</span> <span class=\"quran-arabic-font text-success\">الْقَدِيرُ</span><br />\r\n<br />\r\n(அல்லாஹ்தான் உங்களை பலவீனமான நிலையில் படைத்தான், பின்னர் அந்த பலவீனத்திற்குப் பிறகு பலத்தை அளித்தான், பின்னர் பலத்திற்குப் பிறகு பலவீனத்தையும் நரையையும் ஏற்படுத்தினான். அவன் நாடியதைப் படைக்கிறான். மேலும் அவன் எல்லாம் அறிந்தவன், பேராற்றல் மிக்கவன்.) (<a href=\"qurandisp.php?sura=30&ayah=54\" class=\"link\">30:54</a>)<br />\r\n<br />\r\nஇந்த உவமை இவ்வுலக வாழ்க்கை விரைவில் அழியக்கூடியது என்பதையும் அதன் முடிவை நோக்கிய பயணத்தையும் சுட்டிக்காட்டுகிறது. அதேசமயம் இதற்கு நேர்மாறாக, மறுமை என்பது நிச்சயமாக வரக்கூடியது. எனவே, இந்த உவமையைக் கேட்பவர்கள் மறுமையின் முக்கியத்துவத்தை உணர்ந்து, அதில் உள்ள நன்மைகளை அடைவதில் ஆர்வம் கொள்ள வேண்டும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَفِي</span> <span class=\"quran-arabic-font text-success\">الْآخِرَةِ</span> <span class=\"quran-arabic-font text-success\">عَذَابٌ</span> <span class=\"quran-arabic-font text-success\">شَدِيدٌ</span> <span class=\"quran-arabic-font text-success\">وَمَغْفِرَةٌ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَرِضْوَانٌ</span> <span class=\"quran-arabic-font text-success\">ۚ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">الْحَيَاةُ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">مَتَاعُ</span> <span class=\"quran-arabic-font text-success\">الْغُرُورِ</span><br />\r\n<br />\r\n(மறுமையிலோ கடுமையான வேதனையும் உண்டு, அல்லாஹ்விடமிருந்து மன்னிப்பும் அவனது திருப்தியும் உண்டு. இவ்வுலக வாழ்க்கை ஏமாற்றும் அற்ப இன்பமே தவிர வேறில்லை.) அதாவது, நிச்சயமாக வரவிருக்கும் மறுமையில் இரண்டு நிலைகள் உள்ளன: ஒன்று கடுமையான தண்டனை, அல்லது அல்லாஹ்விடமிருந்து மன்னிப்பும் அவனது பொருத்தமும். உயர்ந்தோனாகிய அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">الْحَيَاةُ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">مَتَاعُ</span> <span class=\"quran-arabic-font text-success\">الْغُرُورِ</span><br />\r\n<br />\r\n(இவ்வுலக வாழ்க்கை ஏமாற்றும் அற்ப இன்பமே தவிர வேறில்லை.) அதாவது, இவ்வுலக வாழ்க்கை என்பது அதன் மீது பற்று வைப்பவர்களை ஏமாற்றக்கூடிய ஒரு இன்பமேயாகும். நிச்சயமாக, இவ்வுலக வாழ்க்கையின் மீது சாய்ந்து கிடப்பவர்கள் அதனை வியப்போடு பார்ப்பார்கள், அது தங்களுக்கு மிகவும் பிரியமானது என்று கருதுவார்கள். எந்த அளவுக்கு என்றால், இதுதான் உண்மையான வாழ்க்கை, இதற்குப் பிறகு வேறு வாழ்க்கையோ தங்குமிடமோ இல்லை என்று அவர்கள் எண்ணக்கூடும். ஆனால் உண்மையில், மறுமையுடன் ஒப்பிடும்போது இவ்வுலக வாழ்க்கை அற்பமானது. இமாம் அஹ்மது அவர்கள் பதிவு செய்துள்ள ஒரு ஹதீஸில், அப்துல்லாஹ் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الْجَنَّةُ</span> <span class=\"quran-arabic-font text-success\">أَقْرَبُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">أَحَدِكُمْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">شِرَاكِ</span> <span class=\"quran-arabic-font text-success\">نَعْلِهِ،</span> <span class=\"quran-arabic-font text-success\">وَالنَّارُ</span> <span class=\"quran-arabic-font text-success\">مِثْلُ</span> <span class=\"quran-arabic-font text-success\">ذلِك</span>»<br />\r\n<br />\r\n(சொர்க்கம் உங்களில் ஒருவருக்கு அவரது காலணி வாரை விட மிக நெருக்கமாக இருக்கிறது, நரகமும் அவ்வாறே.) இந்த ஹதீஸை அல்-புகாரி அவர்கள் அத்-தவ்ரி வாயிலாகப் பதிவு செய்துள்ளார்கள். இந்த ஹதீஸ் மனிதனுக்கு நன்மை மற்றும் தீமை ஆகிய இரண்டின் நெருக்கத்தையும் உணர்த்துகிறது. நிலைமை இவ்வாறிருக்க, இதனால்தான் உயர்ந்தோனாகிய அல்லாஹ் நற்செயல்கள் புரியவும் தனக்குக் கீழ்ப்படிந்து நடக்கவும் விரைந்து வருமாறு மனிதர்களைத் தூண்டுகிறான்; மேலும் விலக்கப்பட்ட காரியங்களைத் தவிர்க்குமாறு வலியுறுத்துகிறான். இவ்வாறு செய்வதன் மூலம் அவர்களின் பாவங்கள் மன்னிக்கப்படும், அவர்களுக்கு நற்கூலிகளும் உயர்ந்த அந்தஸ்துகளும் கிடைக்கும். உயர்ந்தோனாகிய அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سَابِقُوا</span> <span class=\"quran-arabic-font text-success\">إِلَىٰ</span> <span class=\"quran-arabic-font text-success\">مَغْفِرَةٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رَّبِّكُمْ</span> <span class=\"quran-arabic-font text-success\">وَجَنَّةٍ</span> <span class=\"quran-arabic-font text-success\">عَرْضُهَا</span> <span class=\"quran-arabic-font text-success\">كَعَرْضِ</span> <span class=\"quran-arabic-font text-success\">السَّمَاءِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ</span><br />\r\n<br />\r\n(உங்கள் இறைவனிடமிருந்து வரும் மன்னிப்பை நோக்கியும், வானம் மற்றும் பூமியின் அகலத்தைப் போன்ற அகலமுடைய சொர்க்கத்தை நோக்கியும் ஒருவருக்கொருவர் முந்திக்கொள்ளுங்கள்.) உயர்ந்தோனாகிய அல்லாஹ் வேறொரு வசனத்தில் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَسَارِعُوا</span> <span class=\"quran-arabic-font text-success\">إِلَىٰ</span> <span class=\"quran-arabic-font text-success\">مَغْفِرَةٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رَّبِّكُمْ</span> <span class=\"quran-arabic-font text-success\">وَجَنَّةٍ</span> <span class=\"quran-arabic-font text-success\">عَرْضُهَا</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتُ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضُ</span> <span class=\"quran-arabic-font text-success\">أُعِدَّتْ</span> <span class=\"quran-arabic-font text-success\">لِلْمُتَّقِينَ</span><br />\r\n<br />\r\n(உங்கள் இறைவனின் மன்னிப்பிற்கும், வானங்கள் மற்றும் பூமியின் அகலத்தைப் போன்ற சொர்க்கத்திற்கும் விரைந்து செல்லுங்கள்; அது இறையச்சம் உடையவர்களுக்காகத் தயார் செய்யப்பட்டுள்ளது.) (<a href=\"qurandisp.php?sura=3&ayah=133\" class=\"link\">3:133</a>) அல்லாஹ் இங்கே கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أُعِدَّتْ</span> <span class=\"quran-arabic-font text-success\">لِلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَرُسُلِهِ</span> <span class=\"quran-arabic-font text-success\">ۚ</span> <span class=\"quran-arabic-font text-success\">ذَٰلِكَ</span> <span class=\"quran-arabic-font text-success\">فَضْلُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">يُؤْتِيهِ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَشَاءُ</span> <span class=\"quran-arabic-font text-success\">ۚ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">ذُو</span> <span class=\"quran-arabic-font text-success\">الْفَضْلِ</span> <span class=\"quran-arabic-font text-success\">الْعَظِيمِ</span><br />\r\n<br />\r\n(அது அல்லாஹ்வையும் அவனது தூதர்களையும் விசுவாசித்தவர்களுக்காகத் தயார் செய்யப்பட்டுள்ளது. அது அல்லாஹ்வின் அருளாகும்; அதனை அவன் நாடியவர்களுக்கு வழங்குகிறான். மேலும் அல்லாஹ் மகத்தான அருளுடையவன்.) அதாவது, \"அல்லாஹ் அவர்களுக்கு வழங்கியிருக்கும் இந்தத் தகுதி, அவனது பேரருள் மற்றும் கருணையின் ஒரு பகுதியாகும்.\" ஸஹீஹ் நூலில் பதிவு செய்யப்பட்டுள்ள ஒரு ஹதீஸை நாம் ஏற்கனவே குறிப்பிட்டுள்ளோம். அதில் ஏழை முஹாஜிர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் கூறினார்கள்: \"அல்லாஹ்வின் தூதரே! செல்வந்தர்கள் உயர் பதவிகளையும் நிலையான இன்பங்களையும் தட்டிச் சென்றுவிட்டார்கள்.\" அதற்கு நபி (ஸல்) அவர்கள் கேட்டார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">ذَاكَ؟</span>»<br />\r\n<br />\r\n(அது எதனால்?) அவர்கள் கூறினார்கள்: \"நாங்கள் தொழுவது போலவே அவர்களும் தொழுகிறார்கள், நாங்கள் நோன்பு நோற்பது போலவே அவர்களும் நோன்பு நோற்கிறார்கள். ஆனால், அவர்கள் தர்மம் செய்கிறார்கள், எங்களால் முடிவதில்லை; அவர்கள் அடிமைகளை விடுதலை செய்கிறார்கள், எங்களால் முடிவதில்லை.\" நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَفَلَا</span> <span class=\"quran-arabic-font text-success\">أَدُلُّكُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">فَعَلْتُمُوهُ</span> <span class=\"quran-arabic-font text-success\">سَبَقْتُمْ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">بَعْدَكُمْ،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يَكُونُ</span> <span class=\"quran-arabic-font text-success\">أَحَدٌ</span> <span class=\"quran-arabic-font text-success\">أَفْضَلَ</span> <span class=\"quran-arabic-font text-success\">مِنْكُمْ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">صَنَعَ</span> <span class=\"quran-arabic-font text-success\">مِثْلَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">صَنَعْتُمْ</span>: <span class=\"quran-arabic-font text-success\">تُسَبِّحُونَ</span> <span class=\"quran-arabic-font text-success\">وَتُكَبِّرُونَ</span> <span class=\"quran-arabic-font text-success\">وَتُحَمِّدُونَ</span> <span class=\"quran-arabic-font text-success\">دُبُرَ</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">صَلَاةٍ</span> <span class=\"quran-arabic-font text-success\">ثَلَاثًا</span> <span class=\"quran-arabic-font text-success\">وَثَلَاثِين</span>»<br />\r\n<br />\r\n(நான் உங்களுக்கு ஒரு காரியத்தைச் சொல்லித்தரட்டுமா? அதனை நீங்கள் செய்தால் உங்களை முந்தியவர்களை நீங்கள் அடைந்துவிடுவீர்கள்; உங்களுக்குப் பிறகு யாரும் உங்களை மிஞ்ச முடியாது; உங்களைப் போன்றே செய்பவரைத் தவிர வேறு எவரும் உங்களை விடச் சிறந்தவராக இருக்க முடியாது: ஒவ்வொரு தொழுகைக்குப் பின்பும் முப்பத்து மூன்று முறை 'சுப்ஹானல்லாஹ்', 'அல்லாஹு அக்பர்' மற்றும் 'அல்ஹம்துலில்லாஹ்' என்று கூறுங்கள்.) பின்னர் அவர்கள் மீண்டும் வந்து, \"எங்களது செல்வந்த சகோதரர்கள் நாங்கள் செய்வதைக் கேள்விப்பட்டு அவர்களும் அதைப் போலவே செய்ய ஆரம்பித்துவிட்டார்கள்\" என்று கூறினார்கள். அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">ذلِكَ</span> <span class=\"quran-arabic-font text-success\">فَضْلُ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">يُؤْتِيهِ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">يَشَاء</span>»<br />\r\n<br />\r\n(இது அல்லாஹ்வின் அருளாகும், அவன் நாடியவர்களுக்கு அதனை வழங்குகிறான்.)<br />\r\n<br />","text":"இவ்வுலக வாழ்க்கை ஒரு அற்பமான இன்பமே\n\r\n\n\r\nஉயர்ந்தோனாகிய அல்லாஹ் இவ்வுலக வாழ்க்கையின் முக்கியத்துவத்தைக் குறைத்து, அதனை அற்பமானதாகக் கருதி இவ்வாறு கூறுகிறான்:\n\r\n\n\r\nاعْلَمُوا أَنَّمَا الْحَيَاةُ الدُّنْيَا لَعِبٌ وَلَهْوٌ وَزِينَةٌ وَتَفَاخُرٌ بَيْنَكُمْ وَتَكَاثُرٌ فِي الْأَمْوَالِ وَالْأَوْلَادِ\n\r\n\n\r\n(அறிந்து கொள்ளுங்கள்! நிச்சயமாக இவ்வுலக வாழ்க்கை விளையாட்டும், வேடிக்கையும், அலங்காரமும், உங்களுக்கு இடையில் பெருமையடித்துக் கொள்வதும், செல்வங்களிலும் பிள்ளைகளிலும் ஒருவரையொருவர் மிஞ்சத் துடிப்பதுமேயாகும்.) அதாவது, இவ்வுலகில் வாழ்பவர்களுக்கு இதன் நிலை இதுதான். மற்றொரு வசனத்தில் அல்லாஹ் கூறியிருப்பதைப் போல:\n\r\n\n\r\nزُيِّنَ لِلنَّاسِ حُبُّ الشَّهَوَاتِ مِنَ النِّسَاءِ وَالْبَنِينَ وَالْقَنَاطِيرِ الْمُقَنطَرَةِ مِنَ الذَّهَبِ وَالْفِضَّةِ وَالْخَيْلِ الْمُسَوَّمَةِ وَالْأَنْعَامِ وَالْحَرْثِ ذَلِكَ مَتَاعُ الْحَيَاةِ الدُّنْيَا وَاللَّهُ عِندَهُ حُسْنُ الْمَآبِ\n\r\n\n\r\n(பெண்கள், ஆண் மக்கள், தங்கம் மற்றும் வெள்ளியின் பெருங்குவியல்கள், அடையாளமிடப்பட்ட அழகிய குதிரைகள், கால்நடைகள் மற்றும் விளைநிலங்கள் போன்ற இச்சையூட்டும் பொருட்கள் மீதுள்ள ஆசை மனிதர்களுக்கு அழகாக்கப்பட்டுள்ளது. இவை இவ்வுலக வாழ்க்கையின் அற்ப இன்பங்களாகும்; ஆனால் அல்லாஹ்விடமோ மிகச் சிறந்த தங்குமிடம் இருக்கிறது.) (3:14) உயர்ந்தோனாகிய அல்லாஹ் இவ்வுலக வாழ்க்கைக்கு ஓர் உவமையைக் கூறுகிறான்; அதன் மகிழ்ச்சிகள் மங்கிவிடக்கூடியவை என்றும் அதன் இன்பங்கள் அழியக்கூடியவை என்றும் கூறி, வாழ்க்கை என்பது:\n\r\n\n\r\nكَمَثَلِ غَيْثٍ\n\r\n\n\r\n(ஒரு மழையைப் (கய்ஸ்) போன்றது.) இது மனிதர்கள் நம்பிக்கையிழந்த பிறகு அவர்களுக்கு இறங்கும் மழையாகும். உயர்ந்தோனாகிய அல்லாஹ் வேறொரு வசனத்தில் கூறுகிறான்:\n\r\n\n\r\nوَهُوَ الَّذِى يُنَزِّلُ الْغَيْثَ مِن بَعْدِ مَا قَنَطُواْ\n\r\n\n\r\n(அவர்கள் நம்பிக்கையிழந்த பிறகு மழையை (கய்ஸ்) இறக்குபவன் அவனே.) (42:28) அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nأَعْجَبَ الْكُفَّارَ نَبَاتُهُ\n\r\n\n\r\n(அம்மழையினால் விளைந்த பயிர்கள் விவசாயிகளுக்கு மகிழ்ச்சியளிக்கின்றன;) அதாவது, மழைக்குப் பிறகு செழித்து வளரும் பயிர்களை விவசாயிகள் கண்டு வியக்கிறார்கள். விவசாயிகள் பயிர்களைக் கண்டு வியப்பது போலவே, இறைநிராகரிப்பாளர்கள் இவ்வுலக வாழ்க்கையைக் கண்டு வியக்கிறார்கள்; அவர்கள் இவ்வுலகின் இன்பங்களைப் பெறுவதில் மிகுந்த ஆர்வம் கொண்டவர்களாக இருக்கிறார்கள், மேலும் இவ்வுலகமே அவர்களுக்கு மிகவும் பிரியமானதாகும்.\n\r\n\n\r\nثُمَّ يَهِيجُ فَتَرَاهُ مُصْفَرّاً ثُمَّ يَكُونُ حُطَاماً\n\r\n\n\r\n(பின்னர் அது காய்ந்து, அது மஞ்சள் நிறமாக மாறுவதை நீர் காண்பீர்; பிறகு அது சருகுகளாகிவிடுகிறது.) அதாவது, அந்தப் பயிர் பசுமையாக இருந்த பிறகு, விரைவில் மஞ்சள் நிறமாக மாறிவிடுகிறது. அதன் பிறகு, அந்தப் பசுமை மறைந்து சிதறிய தூசிகளாகி விடுகிறது. இதுதான் இவ்வுலக வாழ்க்கைக்குரிய உவமை; அது இளமையாகத் தொடங்கி, பிறகு முதிர்ச்சியடைந்து, இறுதியில் முதுமையையும் பலவீனத்தையும் அடைகிறது. இது இவ்வுலகில் மனிதனுக்கும் உவமையாகும்; மனிதன் ஆரம்பத்தில் இளமையாகவும் வலிமையாகவும் இருக்கிறான். அக்கட்டத்தில் அவன் அழகாகவும் பொலிவோடும் காணப்படுகிறான். மெதுவாக அவனுக்கு வயதாகத் தொடங்குகிறது, அவனது சுபாவங்கள் மாறுகின்றன, அவனது வலிமை குறைகிறது. பின்னர் அவன் மிகவும் முதுமையடைந்து பலவீனமாகிறான்; அவனுக்கு அசைவது கூட சிரமமாகிறது, மிக எளிய காரியங்களைக் கூட அவனால் செய்ய முடியாமல் போகிறது. உயர்ந்தோனாகிய அல்லாஹ் கூறினான்:\n\r\n\n\r\nاللَّهُ الَّذِي خَلَقَكُم مِّن ضَعْفٍ ثُمَّ جَعَلَ مِن بَعْدِ ضَعْفٍ قُوَّةً ثُمَّ جَعَلَ مِن بَعْدِ قُوَّةٍ ضَعْفًا وَشَيْبَةً ۚ يَخْلُقُ مَا يَشَاءُ ۖ وَهُوَ الْعَلِيمُ الْقَدِيرُ\n\r\n\n\r\n(அல்லாஹ்தான் உங்களை பலவீனமான நிலையில் படைத்தான், பின்னர் அந்த பலவீனத்திற்குப் பிறகு பலத்தை அளித்தான், பின்னர் பலத்திற்குப் பிறகு பலவீனத்தையும் நரையையும் ஏற்படுத்தினான். அவன் நாடியதைப் படைக்கிறான். மேலும் அவன் எல்லாம் அறிந்தவன், பேராற்றல் மிக்கவன்.) (30:54)\n\r\n\n\r\nஇந்த உவமை இவ்வுலக வாழ்க்கை விரைவில் அழியக்கூடியது என்பதையும் அதன் முடிவை நோக்கிய பயணத்தையும் சுட்டிக்காட்டுகிறது. அதேசமயம் இதற்கு நேர்மாறாக, மறுமை என்பது நிச்சயமாக வரக்கூடியது. எனவே, இந்த உவமையைக் கேட்பவர்கள் மறுமையின் முக்கியத்துவத்தை உணர்ந்து, அதில் உள்ள நன்மைகளை அடைவதில் ஆர்வம் கொள்ள வேண்டும்.\n\r\n\n\r\nوَفِي الْآخِرَةِ عَذَابٌ شَدِيدٌ وَمَغْفِرَةٌ مِّنَ اللَّهِ وَرِضْوَانٌ ۚ وَمَا الْحَيَاةُ الدُّنْيَا إِلَّا مَتَاعُ الْغُرُورِ\n\r\n\n\r\n(மறுமையிலோ கடுமையான வேதனையும் உண்டு, அல்லாஹ்விடமிருந்து மன்னிப்பும் அவனது திருப்தியும் உண்டு. இவ்வுலக வாழ்க்கை ஏமாற்றும் அற்ப இன்பமே தவிர வேறில்லை.) அதாவது, நிச்சயமாக வரவிருக்கும் மறுமையில் இரண்டு நிலைகள் உள்ளன: ஒன்று கடுமையான தண்டனை, அல்லது அல்லாஹ்விடமிருந்து மன்னிப்பும் அவனது பொருத்தமும். உயர்ந்தோனாகிய அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَمَا الْحَيَاةُ الدُّنْيَا إِلَّا مَتَاعُ الْغُرُورِ\n\r\n\n\r\n(இவ்வுலக வாழ்க்கை ஏமாற்றும் அற்ப இன்பமே தவிர வேறில்லை.) அதாவது, இவ்வுலக வாழ்க்கை என்பது அதன் மீது பற்று வைப்பவர்களை ஏமாற்றக்கூடிய ஒரு இன்பமேயாகும். நிச்சயமாக, இவ்வுலக வாழ்க்கையின் மீது சாய்ந்து கிடப்பவர்கள் அதனை வியப்போடு பார்ப்பார்கள், அது தங்களுக்கு மிகவும் பிரியமானது என்று கருதுவார்கள். எந்த அளவுக்கு என்றால், இதுதான் உண்மையான வாழ்க்கை, இதற்குப் பிறகு வேறு வாழ்க்கையோ தங்குமிடமோ இல்லை என்று அவர்கள் எண்ணக்கூடும். ஆனால் உண்மையில், மறுமையுடன் ஒப்பிடும்போது இவ்வுலக வாழ்க்கை அற்பமானது. இமாம் அஹ்மது அவர்கள் பதிவு செய்துள்ள ஒரு ஹதீஸில், அப்துல்லாஹ் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«الْجَنَّةُ أَقْرَبُ إِلَى أَحَدِكُمْ مِنْ شِرَاكِ نَعْلِهِ، وَالنَّارُ مِثْلُ ذلِك»\n\r\n\n\r\n(சொர்க்கம் உங்களில் ஒருவருக்கு அவரது காலணி வாரை விட மிக நெருக்கமாக இருக்கிறது, நரகமும் அவ்வாறே.) இந்த ஹதீஸை அல்-புகாரி அவர்கள் அத்-தவ்ரி வாயிலாகப் பதிவு செய்துள்ளார்கள். இந்த ஹதீஸ் மனிதனுக்கு நன்மை மற்றும் தீமை ஆகிய இரண்டின் நெருக்கத்தையும் உணர்த்துகிறது. நிலைமை இவ்வாறிருக்க, இதனால்தான் உயர்ந்தோனாகிய அல்லாஹ் நற்செயல்கள் புரியவும் தனக்குக் கீழ்ப்படிந்து நடக்கவும் விரைந்து வருமாறு மனிதர்களைத் தூண்டுகிறான்; மேலும் விலக்கப்பட்ட காரியங்களைத் தவிர்க்குமாறு வலியுறுத்துகிறான். இவ்வாறு செய்வதன் மூலம் அவர்களின் பாவங்கள் மன்னிக்கப்படும், அவர்களுக்கு நற்கூலிகளும் உயர்ந்த அந்தஸ்துகளும் கிடைக்கும். உயர்ந்தோனாகிய அல்லாஹ் கூறினான்:\n\r\n\n\r\nسَابِقُوا إِلَىٰ مَغْفِرَةٍ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا كَعَرْضِ السَّمَاءِ وَالْأَرْضِ\n\r\n\n\r\n(உங்கள் இறைவனிடமிருந்து வரும் மன்னிப்பை நோக்கியும், வானம் மற்றும் பூமியின் அகலத்தைப் போன்ற அகலமுடைய சொர்க்கத்தை நோக்கியும் ஒருவருக்கொருவர் முந்திக்கொள்ளுங்கள்.) உயர்ந்தோனாகிய அல்லாஹ் வேறொரு வசனத்தில் கூறுகிறான்:\n\r\n\n\r\nوَسَارِعُوا إِلَىٰ مَغْفِرَةٍ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا السَّمَاوَاتُ وَالْأَرْضُ أُعِدَّتْ لِلْمُتَّقِينَ\n\r\n\n\r\n(உங்கள் இறைவனின் மன்னிப்பிற்கும், வானங்கள் மற்றும் பூமியின் அகலத்தைப் போன்ற சொர்க்கத்திற்கும் விரைந்து செல்லுங்கள்; அது இறையச்சம் உடையவர்களுக்காகத் தயார் செய்யப்பட்டுள்ளது.) (3:133) அல்லாஹ் இங்கே கூறுகிறான்:\n\r\n\n\r\nأُعِدَّتْ لِلَّذِينَ آمَنُوا بِاللَّهِ وَرُسُلِهِ ۚ ذَٰلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ ۚ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ\n\r\n\n\r\n(அது அல்லாஹ்வையும் அவனது தூதர்களையும் விசுவாசித்தவர்களுக்காகத் தயார் செய்யப்பட்டுள்ளது. அது அல்லாஹ்வின் அருளாகும்; அதனை அவன் நாடியவர்களுக்கு வழங்குகிறான். மேலும் அல்லாஹ் மகத்தான அருளுடையவன்.) அதாவது, \"அல்லாஹ் அவர்களுக்கு வழங்கியிருக்கும் இந்தத் தகுதி, அவனது பேரருள் மற்றும் கருணையின் ஒரு பகுதியாகும்.\" ஸஹீஹ் நூலில் பதிவு செய்யப்பட்டுள்ள ஒரு ஹதீஸை நாம் ஏற்கனவே குறிப்பிட்டுள்ளோம். அதில் ஏழை முஹாஜிர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் கூறினார்கள்: \"அல்லாஹ்வின் தூதரே! செல்வந்தர்கள் உயர் பதவிகளையும் நிலையான இன்பங்களையும் தட்டிச் சென்றுவிட்டார்கள்.\" அதற்கு நபி (ஸல்) அவர்கள் கேட்டார்கள்:\n\r\n\n\r\n«وَمَا ذَاكَ؟»\n\r\n\n\r\n(அது எதனால்?) அவர்கள் கூறினார்கள்: \"நாங்கள் தொழுவது போலவே அவர்களும் தொழுகிறார்கள், நாங்கள் நோன்பு நோற்பது போலவே அவர்களும் நோன்பு நோற்கிறார்கள். ஆனால், அவர்கள் தர்மம் செய்கிறார்கள், எங்களால் முடிவதில்லை; அவர்கள் அடிமைகளை விடுதலை செய்கிறார்கள், எங்களால் முடிவதில்லை.\" நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«أَفَلَا أَدُلُّكُمْ عَلَى شَيْءٍ إِذَا فَعَلْتُمُوهُ سَبَقْتُمْ مَنْ بَعْدَكُمْ، وَلَا يَكُونُ أَحَدٌ أَفْضَلَ مِنْكُمْ إِلَّا مَنْ صَنَعَ مِثْلَ مَا صَنَعْتُمْ: تُسَبِّحُونَ وَتُكَبِّرُونَ وَتُحَمِّدُونَ دُبُرَ كُلِّ صَلَاةٍ ثَلَاثًا وَثَلَاثِين»\n\r\n\n\r\n(நான் உங்களுக்கு ஒரு காரியத்தைச் சொல்லித்தரட்டுமா? அதனை நீங்கள் செய்தால் உங்களை முந்தியவர்களை நீங்கள் அடைந்துவிடுவீர்கள்; உங்களுக்குப் பிறகு யாரும் உங்களை மிஞ்ச முடியாது; உங்களைப் போன்றே செய்பவரைத் தவிர வேறு எவரும் உங்களை விடச் சிறந்தவராக இருக்க முடியாது: ஒவ்வொரு தொழுகைக்குப் பின்பும் முப்பத்து மூன்று முறை 'சுப்ஹானல்லாஹ்', 'அல்லாஹு அக்பர்' மற்றும் 'அல்ஹம்துலில்லாஹ்' என்று கூறுங்கள்.) பின்னர் அவர்கள் மீண்டும் வந்து, \"எங்களது செல்வந்த சகோதரர்கள் நாங்கள் செய்வதைக் கேள்விப்பட்டு அவர்களும் அதைப் போலவே செய்ய ஆரம்பித்துவிட்டார்கள்\" என்று கூறினார்கள். அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«ذلِكَ فَضْلُ اللهِ يُؤْتِيهِ مَنْ يَشَاء»\n\r\n\n\r\n(இது அல்லாஹ்வின் அருளாகும், அவன் நாடியவர்களுக்கு அதனை வழங்குகிறான்.)"},"22":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=57&ayah=24\" class=\"link\">57:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 57:24 ஐ பார்க்கவும்"},"23":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=57&ayah=24\" class=\"link\">57:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 57:24 ஐ பார்க்கவும்"},"24":{"html":"<strong>மனிதனைப் பாதிக்கும் அனைத்தும் முறையாக அளவிடப்பட்டு விதிக்கப்பட்டதே</strong><br />\r\n<br />\r\nபடைப்புகளைப் படைப்பதற்கு முன்னரே, அல்லாஹ் அனைத்துப் பொருட்களின் விதியையும் நிர்ணயித்துவிட்டதை இங்கு நினைவூட்டுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أَصَابَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مُّصِيبَةٍ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">أَنفُسِكُمْ</span><br />\r\n<br />\r\n(பூமியிலோ அல்லது உங்களுக்கோ எந்த ஒரு துன்பமும் ஏற்படுவதில்லை) அதாவது, \"உங்களைத் தீண்டுகின்ற அல்லது இவ்வுலகில் நிகழ்கின்ற எதுவும்,\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">كِتَابٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">قَبْلِ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">نَّبْرَأَهَا</span><br />\r\n<br />\r\n(நாம் அதை உண்டாக்குவதற்கு முன்பே அது ஒரு ஏட்டில் பதிவு செய்யப்பட்டுள்ளது) அதாவது, \"நாம் படைப்புகளைப் படைத்து, வாழ்க்கையைத் தொடங்குவதற்கு முன்பே\" என்று பொருள். கதாதா (ரஹ்) அவர்கள் இந்த வசனத்திற்கு விளக்கமளிக்கும்போது,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أَصَابَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مُّصِيبَةٍ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span><br />\r\n<br />\r\n(பூமியில் ஏற்படும் துன்பம் என்பது) பஞ்சத்தைக் குறிக்கிறது என்றும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">أَنفُسِكُمْ</span><br />\r\n<br />\r\n(உங்களுக்கு ஏற்படும் துன்பம் என்பது) நோய்களையும் வேதனைகளையும் குறிக்கிறது என்றும் கூறினார்கள்.  <br />\r\n<br />\r\nஇந்த மகத்தான வசனம், அல்லாஹ்வின் விதி நிர்ணயத்தையும் (கத்ர்), நிகழ்வுகள் நடப்பதற்கு முன்பே அவன் அனைத்தையும் அறிந்திருப்பதையும் மறுக்கின்ற வழிகெட்ட 'கதரிய்யா' பிரிவினரின் தவறான கொள்கைக்குத் தெளிவான ஆதாரமாகத் திகழ்கிறது. இமாம் அஹ்மத் (ரஹ்) அவர்கள், அப்துல்லாஹ் பின் அம்ர் பின் அல்-ஆஸ் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவ்வாறு கூற நான் கேட்டேன்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">قَدَّرَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">الْمَقَادِيرَ</span> <span class=\"quran-arabic-font text-success\">قَبلَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَخْلُقَ</span> <span class=\"quran-arabic-font text-success\">السَّموَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضَ</span> <span class=\"quran-arabic-font text-success\">بِخَمْسِينَ</span> <span class=\"quran-arabic-font text-success\">أَلْفَ</span> <span class=\"quran-arabic-font text-success\">سَنَة</span>»<br />\r\n<br />\r\n(அல்லாஹ் வானங்களையும் பூமியையும் படைப்பதற்கு ஐம்பதாயிரம் ஆண்டுகளுக்கு முன்பே எல்லாவற்றின் அளவுகளையும் நிர்ணயித்துவிட்டான்.)\" முஸ்லிம் (ரஹ்) அவர்கள் இந்த ஹதீஸை தனது ஸஹீஹில் பின்வரும் கூடுதல் தகவலுடன் பதிவு செய்துள்ளார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَكَانَ</span> <span class=\"quran-arabic-font text-success\">عَرْشُهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْمَاء</span>»<br />\r\n<br />\r\n(அவனுடைய அர்ஷ் (சிம்மாசனம்) தண்ணீரின் மீது இருந்தது.) அத்-திர்மிதி (ரஹ்) அவர்களும் இதனைப் பதிவு செய்து 'ஹஸன் ஸஹீஹ்' என்று குறிப்பிட்டுள்ளார்கள். அல்லாஹ்வின் கூற்று,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">ذلِكَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">يَسِيرٌ</span><br />\r\n<br />\r\n(நிச்சயமாக, அது அல்லாஹ்வுக்கு மிக எளிதானது.) இதன் பொருள், அவன் எல்லா விஷயங்களையும் அவை நடப்பதற்கு முன்பே அறிவான்; அவை எவ்வாறு நடக்குமோ அவ்வாறே துல்லியமாக அவற்றைப் பதிவு செய்கிறான். இது அவனுக்கு மிகவும் எளிதானது. நிச்சயமாக அல்லாஹ் நடந்தவை, நடக்கப்போகின்றவை மற்றும் நடக்காதவை என அனைத்தையும் அறிவான். மேலும் நடக்காத ஒன்று நடந்தால் அது எந்த வடிவத்தில் அமையும் என்பதையும் அவன் அறிவான்.<br />\r\n<br />\r\n<strong>பொறுமையையும் நன்றியையும் கடைப்பிடிக்க உத்தரவிடுதல்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِّكَيْلَا</span> <span class=\"quran-arabic-font text-success\">تَأْسَوْا</span> <span class=\"quran-arabic-font text-success\">عَلَىٰ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">فَاتَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَفْرَحُوا</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">آتَاكُمْ</span><br />\r\n<br />\r\n(உங்களை விட்டுத் தவறிப்போனவற்றிற்காக நீங்கள் வருந்தாமலும், அவன் உங்களுக்கு வழங்கியவற்றிற்காக (பெருமையுடன்) மகிழாமலும் இருப்பதற்காகவே (இவ்வாறு செய்தான்).) இதன் பொருள், \"நடப்பதற்கு முன்னரே அனைத்தையும் பதிவு செய்துள்ள எமது அகண்ட ஞானத்தைப் பற்றியும், ஒவ்வொன்றையும் அதற்குரிய சரியான அளவில் நாம் படைத்திருப்பதையும் பற்றி நாம் உங்களுக்கு அறிவித்தோம். இதன் மூலம், உங்களை வந்தடைய வேண்டிய ஒன்று உங்களைத் தவறவிட்டிருக்காது என்பதையும், உங்களைத் தவறவிட்ட ஒன்று உங்களை வந்தடைந்திருக்காது என்பதையும் நீங்கள் உணர்ந்துகொள்வீர்கள். எனவே, உங்களுக்குக் கிடைக்காமல் போன உலக ஆதாயங்களுக்காக நீங்கள் வருந்தாதீர்கள்; ஏனெனில் அது உங்களுக்கு விதிக்கப்பட்டிருந்தால் நிச்சயமாக உங்களை வந்தடைந்திருக்கும்.\"<br />\r\n<br />\r\nமேலும் இப்னு அப்பாஸ் (ரழி) அவர்கள் (<span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَفْرَحُوا</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">أَتَاكُمْ</span>) என்றும் ஓதினார்கள், அதாவது \"உங்களை வந்தடைந்தவற்றிற்காக (மகிழாதீர்கள்)\". மற்றொரு ஓதல் முறையான<br />\r\n<br />\r\n(<span class=\"quran-arabic-font text-success\">آتَاكُمْ</span>)<br />\r\n<br />\r\nஎன்பதன் படி \"உங்களுக்கு அவன் வழங்கியவற்றிற்காக\" என்று பொருள்படும். இவை இரண்டுமே தொடர்புடைய கருத்துக்கள்தான். அல்லாஹ் இங்கே கூறுவது: \"அல்லாஹ் உங்களுக்கு அருளியவற்றைக் கொண்டு மக்கள் முன் பெருமையடிக்காதீர்கள். ஏனெனில், அதனை உங்கள் சொந்த முயற்சியால் மட்டும் நீங்கள் ஈட்டிவிடவில்லை. மாறாக, அல்லாஹ் உங்களுக்கு அதனை விதித்து, வாழ்வாதாரமாக வழங்கியதால்தான் அது உங்களுக்குக் கிடைத்தது. எனவே, அல்லாஹ் வழங்கிய அருட்கொடைகளைப் பிறரிடம் பெருமையடிக்கவும் ஆணவம் கொள்ளவும் ஒரு காரணமாகப் பயன்படுத்தாதீர்கள்.\" அல்லாஹ்வின் கூற்று,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يُحِبُّ</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">مُخْتَالٍ</span> <span class=\"quran-arabic-font text-success\">فَخُورٍ</span><br />\r\n<br />\r\n(பெருமையடித்துத் தற்பெருமை பேசுபவர் எவரையும் அல்லாஹ் நேசிப்பதில்லை.) அதாவது, மற்றவர்களிடம் ஆணவமாக நடந்துகொள்பவர்கள். இக்ரிமா (ரஹ்) அவர்கள் இதைப் பற்றி கூறும்போது, \"நம்மில் ஒவ்வொருவரும் மகிழ்ச்சியையும் துக்கத்தையும் உணர்கிறோம். எனவே உங்கள் மகிழ்ச்சியை நன்றியுடனும், உங்கள் துக்கத்தைப் பொறுமையுடனும் எதிர்கொள்ளுங்கள்\" என்று விளக்கமளித்தார்கள்.<br />\r\n<br />\r\n<strong>கஞ்சத்தனத்தைக் கண்டித்தல்</strong><br />\r\n<br />\r\nஉயர்ந்தோன் அல்லாஹ் பின்னர் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَبْخَلُونَ</span> <span class=\"quran-arabic-font text-success\">وَيَأْمُرُونَ</span> <span class=\"quran-arabic-font text-success\">النَّاسَ</span> <span class=\"quran-arabic-font text-success\">بِالْبُخْلِ</span><br />\r\n<br />\r\n(அவர்கள் கஞ்சத்தனம் செய்வதுடன், மக்களையும் கஞ்சத்தனம் செய்யுமாறு தூண்டுகிறார்கள்.) அதாவது, அல்லாஹ் எவர்களைப் பற்றி (சென்ற வசனத்தில்) 'பெருமையடித்துத் தற்பெருமை பேசுபவர்கள்' என்று கூறினானோ அவர்கள் இத்தகையவர்களாவர். தாங்களும் தீமை செய்து, மக்களையும் அந்தத் தீமையைச் செய்ய ஊக்குவிப்பவர்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يَتَوَلَّ</span><br />\r\n<br />\r\n(மேலும், எவர் புறக்கணிக்கிறாரோ,) அல்லாஹ்வின் கட்டளைகளுக்குக் கட்டுப்பட்டு நடப்பதை விட்டும் எவர் புறக்கணிக்கிறாரோ,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الْغَنِيُّ</span> <span class=\"quran-arabic-font text-success\">الْحَمِيدُ</span><br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் தேவையற்றவன், புகழுக்குரியவன்.) அதாவது, அவன் தனது படைப்புகளின் தேவையற்றவன்; படைப்புகளோ அவன் பால் தேவையுள்ளன. அவன் தனது <span class=\"quran-arabic-font text-success\">ذات</span> (தனித்துவம்), பண்புகள், செயல்கள் அனைத்திலும் புகழப்படத் தகுதியானவன். மூஸா (அலை) அவர்கள் கூறியதைப் போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">تَكْفُرُوا</span> <span class=\"quran-arabic-font text-success\">أَنتُمْ</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">جَمِيعًا</span> <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">لَغَنِيٌّ</span> <span class=\"quran-arabic-font text-success\">حَمِيدٌ</span><br />\r\n<br />\r\n(நீங்களும், பூமியில் உள்ள அனைவரும் சேர்ந்து நிராகரித்தாலும், நிச்சயமாக அல்லாஹ் தேவையற்றவன், எல்லாப் புகழுக்கும் உரியவன்.) (<a href=\"qurandisp.php?sura=14&ayah=8\" class=\"link\">14:8</a>)<br />\r\n<br />","text":"மனிதனைப் பாதிக்கும் அனைத்தும் முறையாக அளவிடப்பட்டு விதிக்கப்பட்டதே\n\r\n\n\r\nபடைப்புகளைப் படைப்பதற்கு முன்னரே, அல்லாஹ் அனைத்துப் பொருட்களின் விதியையும் நிர்ணயித்துவிட்டதை இங்கு நினைவூட்டுகிறான்,\n\r\n\n\r\nمَا أَصَابَ مِن مُّصِيبَةٍ فِي الْأَرْضِ وَلَا فِي أَنفُسِكُمْ\n\r\n\n\r\n(பூமியிலோ அல்லது உங்களுக்கோ எந்த ஒரு துன்பமும் ஏற்படுவதில்லை) அதாவது, \"உங்களைத் தீண்டுகின்ற அல்லது இவ்வுலகில் நிகழ்கின்ற எதுவும்,\"\n\r\n\n\r\nإِلَّا فِي كِتَابٍ مِّن قَبْلِ أَن نَّبْرَأَهَا\n\r\n\n\r\n(நாம் அதை உண்டாக்குவதற்கு முன்பே அது ஒரு ஏட்டில் பதிவு செய்யப்பட்டுள்ளது) அதாவது, \"நாம் படைப்புகளைப் படைத்து, வாழ்க்கையைத் தொடங்குவதற்கு முன்பே\" என்று பொருள். கதாதா (ரஹ்) அவர்கள் இந்த வசனத்திற்கு விளக்கமளிக்கும்போது,\n\r\n\n\r\nمَا أَصَابَ مِن مُّصِيبَةٍ فِي الْأَرْضِ\n\r\n\n\r\n(பூமியில் ஏற்படும் துன்பம் என்பது) பஞ்சத்தைக் குறிக்கிறது என்றும்,\n\r\n\n\r\nوَلَا فِي أَنفُسِكُمْ\n\r\n\n\r\n(உங்களுக்கு ஏற்படும் துன்பம் என்பது) நோய்களையும் வேதனைகளையும் குறிக்கிறது என்றும் கூறினார்கள்.\n\r\n\n\r\nஇந்த மகத்தான வசனம், அல்லாஹ்வின் விதி நிர்ணயத்தையும் (கத்ர்), நிகழ்வுகள் நடப்பதற்கு முன்பே அவன் அனைத்தையும் அறிந்திருப்பதையும் மறுக்கின்ற வழிகெட்ட 'கதரிய்யா' பிரிவினரின் தவறான கொள்கைக்குத் தெளிவான ஆதாரமாகத் திகழ்கிறது. இமாம் அஹ்மத் (ரஹ்) அவர்கள், அப்துல்லாஹ் பின் அம்ர் பின் அல்-ஆஸ் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவ்வாறு கூற நான் கேட்டேன்:\n\r\n\n\r\n«قَدَّرَ اللهُ الْمَقَادِيرَ قَبلَ أَنْ يَخْلُقَ السَّموَاتِ وَالْأَرْضَ بِخَمْسِينَ أَلْفَ سَنَة»\n\r\n\n\r\n(அல்லாஹ் வானங்களையும் பூமியையும் படைப்பதற்கு ஐம்பதாயிரம் ஆண்டுகளுக்கு முன்பே எல்லாவற்றின் அளவுகளையும் நிர்ணயித்துவிட்டான்.)\" முஸ்லிம் (ரஹ்) அவர்கள் இந்த ஹதீஸை தனது ஸஹீஹில் பின்வரும் கூடுதல் தகவலுடன் பதிவு செய்துள்ளார்கள்:\n\r\n\n\r\n«وَكَانَ عَرْشُهُ عَلَى الْمَاء»\n\r\n\n\r\n(அவனுடைய அர்ஷ் (சிம்மாசனம்) தண்ணீரின் மீது இருந்தது.) அத்-திர்மிதி (ரஹ்) அவர்களும் இதனைப் பதிவு செய்து 'ஹஸன் ஸஹீஹ்' என்று குறிப்பிட்டுள்ளார்கள். அல்லாஹ்வின் கூற்று,\n\r\n\n\r\nإِنَّ ذلِكَ عَلَى اللَّهِ يَسِيرٌ\n\r\n\n\r\n(நிச்சயமாக, அது அல்லாஹ்வுக்கு மிக எளிதானது.) இதன் பொருள், அவன் எல்லா விஷயங்களையும் அவை நடப்பதற்கு முன்பே அறிவான்; அவை எவ்வாறு நடக்குமோ அவ்வாறே துல்லியமாக அவற்றைப் பதிவு செய்கிறான். இது அவனுக்கு மிகவும் எளிதானது. நிச்சயமாக அல்லாஹ் நடந்தவை, நடக்கப்போகின்றவை மற்றும் நடக்காதவை என அனைத்தையும் அறிவான். மேலும் நடக்காத ஒன்று நடந்தால் அது எந்த வடிவத்தில் அமையும் என்பதையும் அவன் அறிவான்.\n\r\n\n\r\nபொறுமையையும் நன்றியையும் கடைப்பிடிக்க உத்தரவிடுதல்\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nلِّكَيْلَا تَأْسَوْا عَلَىٰ مَا فَاتَكُمْ وَلَا تَفْرَحُوا بِمَا آتَاكُمْ\n\r\n\n\r\n(உங்களை விட்டுத் தவறிப்போனவற்றிற்காக நீங்கள் வருந்தாமலும், அவன் உங்களுக்கு வழங்கியவற்றிற்காக (பெருமையுடன்) மகிழாமலும் இருப்பதற்காகவே (இவ்வாறு செய்தான்).) இதன் பொருள், \"நடப்பதற்கு முன்னரே அனைத்தையும் பதிவு செய்துள்ள எமது அகண்ட ஞானத்தைப் பற்றியும், ஒவ்வொன்றையும் அதற்குரிய சரியான அளவில் நாம் படைத்திருப்பதையும் பற்றி நாம் உங்களுக்கு அறிவித்தோம். இதன் மூலம், உங்களை வந்தடைய வேண்டிய ஒன்று உங்களைத் தவறவிட்டிருக்காது என்பதையும், உங்களைத் தவறவிட்ட ஒன்று உங்களை வந்தடைந்திருக்காது என்பதையும் நீங்கள் உணர்ந்துகொள்வீர்கள். எனவே, உங்களுக்குக் கிடைக்காமல் போன உலக ஆதாயங்களுக்காக நீங்கள் வருந்தாதீர்கள்; ஏனெனில் அது உங்களுக்கு விதிக்கப்பட்டிருந்தால் நிச்சயமாக உங்களை வந்தடைந்திருக்கும்.\"\n\r\n\n\r\nமேலும் இப்னு அப்பாஸ் (ரழி) அவர்கள் (وَلَا تَفْرَحُوا بِمَا أَتَاكُمْ) என்றும் ஓதினார்கள், அதாவது \"உங்களை வந்தடைந்தவற்றிற்காக (மகிழாதீர்கள்)\". மற்றொரு ஓதல் முறையான\n\r\n\n\r\n(آتَاكُمْ)\n\r\n\n\r\nஎன்பதன் படி \"உங்களுக்கு அவன் வழங்கியவற்றிற்காக\" என்று பொருள்படும். இவை இரண்டுமே தொடர்புடைய கருத்துக்கள்தான். அல்லாஹ் இங்கே கூறுவது: \"அல்லாஹ் உங்களுக்கு அருளியவற்றைக் கொண்டு மக்கள் முன் பெருமையடிக்காதீர்கள். ஏனெனில், அதனை உங்கள் சொந்த முயற்சியால் மட்டும் நீங்கள் ஈட்டிவிடவில்லை. மாறாக, அல்லாஹ் உங்களுக்கு அதனை விதித்து, வாழ்வாதாரமாக வழங்கியதால்தான் அது உங்களுக்குக் கிடைத்தது. எனவே, அல்லாஹ் வழங்கிய அருட்கொடைகளைப் பிறரிடம் பெருமையடிக்கவும் ஆணவம் கொள்ளவும் ஒரு காரணமாகப் பயன்படுத்தாதீர்கள்.\" அல்லாஹ்வின் கூற்று,\n\r\n\n\r\nوَاللَّهُ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ\n\r\n\n\r\n(பெருமையடித்துத் தற்பெருமை பேசுபவர் எவரையும் அல்லாஹ் நேசிப்பதில்லை.) அதாவது, மற்றவர்களிடம் ஆணவமாக நடந்துகொள்பவர்கள். இக்ரிமா (ரஹ்) அவர்கள் இதைப் பற்றி கூறும்போது, \"நம்மில் ஒவ்வொருவரும் மகிழ்ச்சியையும் துக்கத்தையும் உணர்கிறோம். எனவே உங்கள் மகிழ்ச்சியை நன்றியுடனும், உங்கள் துக்கத்தைப் பொறுமையுடனும் எதிர்கொள்ளுங்கள்\" என்று விளக்கமளித்தார்கள்.\n\r\n\n\r\nகஞ்சத்தனத்தைக் கண்டித்தல்\n\r\n\n\r\nஉயர்ந்தோன் அல்லாஹ் பின்னர் கூறினான்:\n\r\n\n\r\nالَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ النَّاسَ بِالْبُخْلِ\n\r\n\n\r\n(அவர்கள் கஞ்சத்தனம் செய்வதுடன், மக்களையும் கஞ்சத்தனம் செய்யுமாறு தூண்டுகிறார்கள்.) அதாவது, அல்லாஹ் எவர்களைப் பற்றி (சென்ற வசனத்தில்) 'பெருமையடித்துத் தற்பெருமை பேசுபவர்கள்' என்று கூறினானோ அவர்கள் இத்தகையவர்களாவர். தாங்களும் தீமை செய்து, மக்களையும் அந்தத் தீமையைச் செய்ய ஊக்குவிப்பவர்கள்.\n\r\n\n\r\nوَمَن يَتَوَلَّ\n\r\n\n\r\n(மேலும், எவர் புறக்கணிக்கிறாரோ,) அல்லாஹ்வின் கட்டளைகளுக்குக் கட்டுப்பட்டு நடப்பதை விட்டும் எவர் புறக்கணிக்கிறாரோ,\n\r\n\n\r\nفَإِنَّ اللَّهَ هُوَ الْغَنِيُّ الْحَمِيدُ\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் தேவையற்றவன், புகழுக்குரியவன்.) அதாவது, அவன் தனது படைப்புகளின் தேவையற்றவன்; படைப்புகளோ அவன் பால் தேவையுள்ளன. அவன் தனது ذات (தனித்துவம்), பண்புகள், செயல்கள் அனைத்திலும் புகழப்படத் தகுதியானவன். மூஸா (அலை) அவர்கள் கூறியதைப் போல:\n\r\n\n\r\nإِن تَكْفُرُوا أَنتُمْ وَمَن فِي الْأَرْضِ جَمِيعًا فَإِنَّ اللَّهَ لَغَنِيٌّ حَمِيدٌ\n\r\n\n\r\n(நீங்களும், பூமியில் உள்ள அனைவரும் சேர்ந்து நிராகரித்தாலும், நிச்சயமாக அல்லாஹ் தேவையற்றவன், எல்லாப் புகழுக்கும் உரியவன்.) (14:8)"},"25":{"html":"<strong>நபிமார்களுக்கு அற்புதங்கள் வழங்கப்பட்டு, உண்மையோடும் நீதியோடும் அனுப்பப்பட்டனர்</strong><br />\r\n<br />\r\nஉயர்ந்தோனாகிய அல்லாஹ் அடுத்துக் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَقَدْ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">رُسُلَنَا</span> <span class=\"quran-arabic-font text-success\">بِالْبَيِّنَاتِ</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் நம்முடைய தூதர்களைத் தெளிவான சான்றுகளுடன் அனுப்பினோம்) இது அற்புதங்கள், ஐயமற்ற ஆதாரங்கள் மற்றும் தெளிவான அத்தாட்சிகளைக் குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنزَلْنَا</span> <span class=\"quran-arabic-font text-success\">مَعَهُمُ</span> <span class=\"quran-arabic-font text-success\">الْكِتَابَ</span><br />\r\n<br />\r\n(மேலும் அவர்களுடன் வேதத்தையும் அருளினோம்) அது உண்மையான செய்திகளைக் கொண்டுள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالْمِيزَانَ</span><br />\r\n<br />\r\n(மேலும் மீஸானையும் - நீதியையும் அருளினோம்), முஜாஹித், கதாதா மற்றும் பலரது கூற்றுப்படி இதன் பொருள் நீதியாகும். வழிகெட்ட கருத்துக்களையும் எண்ணங்களையும் எதிர்க்கும் சீரான, நேர்மையான அறிவால் உறுதிப்படுத்தப்பட்ட உண்மையை இந்த வசனம் குறிக்கிறது. அல்லாஹ் மற்ற வசனங்களில் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَفَمَن</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">بَيِّنَةٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رَّبِّهِ</span> <span class=\"quran-arabic-font text-success\">وَيَتْلُوهُ</span> <span class=\"quran-arabic-font text-success\">شَاهِدٌ</span> <span class=\"quran-arabic-font text-success\">مِّنْهُ</span><br />\r\n<br />\r\n(தமது இறைவனிடமிருந்து கிடைத்த தெளிவான சான்றின் மீது இருப்பவரும், அவரிடமிருந்து ஒரு சாட்சி அதைப் பின்பற்றுபவரும் (நிராகரிப்பாளர்களுக்குச் சமமாவாரா?))(<a href=\"qurandisp.php?sura=11&ayah=17\" class=\"link\">11:17</a>),<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فِطْرَةَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">فَطَرَ</span> <span class=\"quran-arabic-font text-success\">النَّاسَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهَا</span><br />\r\n<br />\r\n(அல்லாஹ்வின் ஃபித்ரா (இயற்கை மார்க்கம்); அதன் மீதே அவன் மனிதர்களைப் படைத்துள்ளான்.) (<a href=\"qurandisp.php?sura=30&ayah=30\" class=\"link\">30:30</a>), மேலும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالسَّمَآءَ</span> <span class=\"quran-arabic-font text-success\">رَفَعَهَا</span> <span class=\"quran-arabic-font text-success\">وَوَضَعَ</span> <span class=\"quran-arabic-font text-success\">الْمِيزَانَ</span><br />\r\n<br />\r\n(மேலும் வானம்: அதை அவன் உயர்த்தினான், மேலும் அவன் மீஸானை (நீதித் தராசை) அமைத்தான்.)(<a href=\"qurandisp.php?sura=55&ayah=7\" class=\"link\">55:7</a>) இதனால்தான் அல்லாஹ் இங்கே கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِيَقُومَ</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">بِالْقِسْطِ</span><br />\r\n<br />\r\n(மனிதர்கள் நீதியை நிலைநாட்டுவதற்காக); தூதர்களுக்குக் கீழ்ப்படிவதிலும், அவர்கள் தங்கள் இறைவனிடமிருந்து கொண்டு வந்த அனைத்தையும் பின்பற்றுவதிலும், அவர்கள் கட்டளையிட்டவற்றைத் தொடர்வதிலும் தான் உண்மை மற்றும் நேர்மை உள்ளது. நிச்சயமாக நபிமார்கள் (அலை) கொண்டு வந்தவை தான் உண்மையானவை, அதற்கப்பால் எந்த உண்மையும் இல்லை. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَتَمَّتْ</span> <span class=\"quran-arabic-font text-success\">كَلِمَةُ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">صِدْقاً</span> <span class=\"quran-arabic-font text-success\">وَعَدْلاً</span><br />\r\n<br />\r\n(உமது இறைவனின் வாக்கு உண்மையாலும் நீதியாலும் முழுமை பெற்றுவிட்டது.)(<a href=\"qurandisp.php?sura=6&ayah=115\" class=\"link\">6:115</a>). அவனது வாக்கு அது தெரிவிப்பவற்றில் உண்மையானது; அதன் கட்டளைகளிலும் விலக்கல்களிலும் நீதியானது. இதனால்தான் விசுவாசிகள் சொர்க்கத்தில் தங்களது அறைகளைப் பெற்று, உயர் நிலைகளையும் வரிசையாக அமைக்கப்பட்ட சிம்மாசனங்களையும் அடையும்போது இவ்வாறு கூறுவார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الْحَمْدُ</span> <span class=\"quran-arabic-font text-success\">لِلَّهِ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">هَدَانَا</span> <span class=\"quran-arabic-font text-success\">لِهَـذَا</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">لِنَهْتَدِىَ</span> <span class=\"quran-arabic-font text-success\">لَوْلا</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">هَدَانَا</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">لَقَدْ</span> <span class=\"quran-arabic-font text-success\">جَآءَتْ</span> <span class=\"quran-arabic-font text-success\">رُسُلُ</span> <span class=\"quran-arabic-font text-success\">رَبِّنَا</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ</span><br />\r\n<br />\r\n(எல்லாப் புகழும் அல்லாஹ்வுக்கே! அவன் தான் எங்களுக்கு இதற்கு நேர்வழி காட்டினான். அல்லாஹ் எங்களுக்கு நேர்வழி காட்டியிராவிட்டால், நாங்கள் ஒருபோதும் நேர்வழி பெற்றிருக்க மாட்டோம். நிச்சயமாக, எங்கள் இறைவனின் தூதர்கள் உண்மையையே கொண்டு வந்தார்கள்.)(<a href=\"qurandisp.php?sura=7&ayah=43\" class=\"link\">7:43</a>)<br />\r\n<br />\r\n<strong>இரும்பின் பயன்கள்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنزَلْنَا</span> <span class=\"quran-arabic-font text-success\">الْحَدِيدَ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">بَأْسٌ</span> <span class=\"quran-arabic-font text-success\">شَدِيدٌ</span><br />\r\n<br />\r\n(மேலும் நாம் இரும்பை இறக்கினோம்; அதில் கடுமையான வலிமை உள்ளது), இதன் பொருள்: ‘சான்றுகள் தெளிவாக்கப்பட்ட பின்னரும் உண்மையை ஏற்க மறுத்து அதனை எதிர்ப்பவர்களைத் தடுக்கும் ஒரு கருவியாக நாம் இரும்பை ஆக்கினோம்.’ அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மக்காவில் பதின்மூன்று ஆண்டுகள் தங்கியிருந்தார்கள். அக்காலத்தில் அவர்களுக்கு வஹீ (இறைச்செய்தி) தொடர்ந்து அருளப்பட்டது. அதில் இணைவைப்பாளர்களுக்கு எதிரான வாதங்களும், தவ்ஹீத் (ஏகத்துவம்) குறித்த விரிவான விளக்கங்களும் சான்றுகளும் இருந்தன. தூதரை (ஸல்) எதிர்த்தவர்களுக்கு எதிராக ஆதாரங்கள் நிலைநாட்டப்பட்டபோது, அல்லாஹ் ஹிஜ்ரத்தை விதியாக்கினான். பின்னர், குர்ஆனை எதிர்த்து, நிராகரித்து மறுத்தவர்களின் கழுத்துகளிலும் நெற்றிகளிலும் தாக்குவதற்கு வாள்களைக் கொண்டு போர் செய்யுமாறு விசுவாசிகளுக்கு அவன் கட்டளையிட்டான். இமாம் அஹ்மத் மற்றும் அபூதாவூத் ஆகியோர் பதிவு செய்துள்ளனர், அப்துல்லாஹ் பின் உமர் (ரழி) அவர்கள் கூறினார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">بُعِثْتُ</span> <span class=\"quran-arabic-font text-success\">بِالسَّيْفِ</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">يَدَيِ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةِ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يُعْبَدَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">وَحْدَهُ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">شَرِيكَ</span> <span class=\"quran-arabic-font text-success\">لَهُ،</span> <span class=\"quran-arabic-font text-success\">وَجُعِلَ</span> <span class=\"quran-arabic-font text-success\">رِزْقِي</span> <span class=\"quran-arabic-font text-success\">تَحْتَ</span> <span class=\"quran-arabic-font text-success\">ظِلِّ</span> <span class=\"quran-arabic-font text-success\">رُمْحِي،</span> <span class=\"quran-arabic-font text-success\">وَجُعِلَ</span> <span class=\"quran-arabic-font text-success\">الذِّلَّةُ</span> <span class=\"quran-arabic-font text-success\">والصَّغَارُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">خَالَفَ</span> <span class=\"quran-arabic-font text-success\">أَمْرِي،</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">تَشَبَّهَ</span> <span class=\"quran-arabic-font text-success\">بِقَوْمٍ</span> <span class=\"quran-arabic-font text-success\">فَهُوَ</span> <span class=\"quran-arabic-font text-success\">مِنْهُم</span>»<br />\r\n<br />\r\n(மறுமை நாளுக்கு முன்னதாக, இணையின்றி அல்லாஹ் ஒருவன் மட்டுமே வணங்கப்பட வேண்டும் என்பதற்காக நான் வாளுடன் அனுப்பப்பட்டேன். எனது வாழ்வாதாரம் எனது ஈட்டியின் நிழலின் கீழ் வைக்கப்பட்டுள்ளது. எனது கட்டளையை மீறுபவர்களுக்கு இழிவும் சிறுமையும் ஏற்படுத்தப்பட்டுள்ளது. எவர் ஒரு சமூகத்திற்கு ஒப்பாக நடக்கிறாரோ, அவர் அவர்களைச் சேர்ந்தவராவார்.) இதனால்தான் உயர்ந்தோனாகிய அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">بَأْسٌ</span> <span class=\"quran-arabic-font text-success\">شَدِيدٌ</span><br />\r\n<br />\r\n(அதில் கடுமையான வலிமை உள்ளது), இது வாள்கள், ஈட்டிகள், குத்துவாள்கள், அம்புகள், கேடயங்கள் போன்ற ஆயுதங்களைக் குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَنَافِعُ</span> <span class=\"quran-arabic-font text-success\">لِلنَّاسِ</span><br />\r\n<br />\r\n(மேலும் மனிதர்களுக்குப் பல பயன்களும் உள்ளன), அதாவது நாணயங்கள், சுத்தியல்கள், கோடாரிகள், ரம்பங்கள், உளிகள், மண்வெட்டிகள் மற்றும் நிலத்தை உழுவதற்கும், விதைப்பதற்கும், சமைப்பதற்கும், மாவு பிசைவதற்கும் மற்றும் அன்றாட வாழ்க்கைக்குத் தேவையான பல கருவிகளைத் தயாரிப்பதற்கும் மக்கள் இதைப் பயன்படுத்துகின்றனர். அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلِيَعْلَمَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَنصُرُهُ</span> <span class=\"quran-arabic-font text-success\">وَرُسُلَهُ</span> <span class=\"quran-arabic-font text-success\">بِالْغَيْبِ</span><br />\r\n<br />\r\n(மறைவான நிலையில் அல்லாஹ்வுக்கும் அவனது தூதர்களுக்கும் உதவி செய்பவர் யார் என்பதை அல்லாஹ் அறிந்துகொள்வதற்காக), அதாவது ஆயுதங்களை ஏந்துவதன் நோக்கம் அல்லாஹ்வுக்கும் (அவனது மார்க்கத்திற்கும்) அவனது தூதருக்கும் பாதுகாப்பளிப்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">قَوِىٌّ</span> <span class=\"quran-arabic-font text-success\">عَزِيزٌ</span><br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் வலிமைமிக்கவன், மிகைத்தவன்.) இதன் பொருள், நிச்சயமாக அல்லாஹ் வலிமைமிக்கவன், யாவரையும் மிகைத்தவன். அவனுக்கு (அவனது மார்க்கத்திற்கு) உதவி செய்பவர்களுக்கு அவன் வெற்றியை அளிக்கிறான். எனினும், அல்லாஹ்வுக்கு மனிதர்களின் உதவி தேவையில்லை; ஒருவரைக் கொண்டு மற்றொருவரைச் சோதிப்பதற்காகவே அவன் ஜிஹாதை (அறப்போர்) கடமையாக்கினான்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"நபிமார்களுக்கு அற்புதங்கள் வழங்கப்பட்டு, உண்மையோடும் நீதியோடும் அனுப்பப்பட்டனர்\n\r\n\n\r\nஉயர்ந்தோனாகிய அல்லாஹ் அடுத்துக் கூறினான்:\n\r\n\n\r\nلَقَدْ أَرْسَلْنَا رُسُلَنَا بِالْبَيِّنَاتِ\n\r\n\n\r\n(நிச்சயமாக நாம் நம்முடைய தூதர்களைத் தெளிவான சான்றுகளுடன் அனுப்பினோம்) இது அற்புதங்கள், ஐயமற்ற ஆதாரங்கள் மற்றும் தெளிவான அத்தாட்சிகளைக் குறிக்கிறது.\n\r\n\n\r\nوَأَنزَلْنَا مَعَهُمُ الْكِتَابَ\n\r\n\n\r\n(மேலும் அவர்களுடன் வேதத்தையும் அருளினோம்) அது உண்மையான செய்திகளைக் கொண்டுள்ளது.\n\r\n\n\r\nوَالْمِيزَانَ\n\r\n\n\r\n(மேலும் மீஸானையும் - நீதியையும் அருளினோம்), முஜாஹித், கதாதா மற்றும் பலரது கூற்றுப்படி இதன் பொருள் நீதியாகும். வழிகெட்ட கருத்துக்களையும் எண்ணங்களையும் எதிர்க்கும் சீரான, நேர்மையான அறிவால் உறுதிப்படுத்தப்பட்ட உண்மையை இந்த வசனம் குறிக்கிறது. அல்லாஹ் மற்ற வசனங்களில் கூறுவது போல:\n\r\n\n\r\nأَفَمَن كَانَ عَلَى بَيِّنَةٍ مِّن رَّبِّهِ وَيَتْلُوهُ شَاهِدٌ مِّنْهُ\n\r\n\n\r\n(தமது இறைவனிடமிருந்து கிடைத்த தெளிவான சான்றின் மீது இருப்பவரும், அவரிடமிருந்து ஒரு சாட்சி அதைப் பின்பற்றுபவரும் (நிராகரிப்பாளர்களுக்குச் சமமாவாரா?))(11:17),\n\r\n\n\r\nفِطْرَةَ اللَّهِ الَّتِى فَطَرَ النَّاسَ عَلَيْهَا\n\r\n\n\r\n(அல்லாஹ்வின் ஃபித்ரா (இயற்கை மார்க்கம்); அதன் மீதே அவன் மனிதர்களைப் படைத்துள்ளான்.) (30:30), மேலும்,\n\r\n\n\r\nوَالسَّمَآءَ رَفَعَهَا وَوَضَعَ الْمِيزَانَ\n\r\n\n\r\n(மேலும் வானம்: அதை அவன் உயர்த்தினான், மேலும் அவன் மீஸானை (நீதித் தராசை) அமைத்தான்.)(55:7) இதனால்தான் அல்லாஹ் இங்கே கூறினான்:\n\r\n\n\r\nلِيَقُومَ النَّاسُ بِالْقِسْطِ\n\r\n\n\r\n(மனிதர்கள் நீதியை நிலைநாட்டுவதற்காக); தூதர்களுக்குக் கீழ்ப்படிவதிலும், அவர்கள் தங்கள் இறைவனிடமிருந்து கொண்டு வந்த அனைத்தையும் பின்பற்றுவதிலும், அவர்கள் கட்டளையிட்டவற்றைத் தொடர்வதிலும் தான் உண்மை மற்றும் நேர்மை உள்ளது. நிச்சயமாக நபிமார்கள் (அலை) கொண்டு வந்தவை தான் உண்மையானவை, அதற்கப்பால் எந்த உண்மையும் இல்லை. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَتَمَّتْ كَلِمَةُ رَبِّكَ صِدْقاً وَعَدْلاً\n\r\n\n\r\n(உமது இறைவனின் வாக்கு உண்மையாலும் நீதியாலும் முழுமை பெற்றுவிட்டது.)(6:115). அவனது வாக்கு அது தெரிவிப்பவற்றில் உண்மையானது; அதன் கட்டளைகளிலும் விலக்கல்களிலும் நீதியானது. இதனால்தான் விசுவாசிகள் சொர்க்கத்தில் தங்களது அறைகளைப் பெற்று, உயர் நிலைகளையும் வரிசையாக அமைக்கப்பட்ட சிம்மாசனங்களையும் அடையும்போது இவ்வாறு கூறுவார்கள்:\n\r\n\n\r\nالْحَمْدُ لِلَّهِ الَّذِى هَدَانَا لِهَـذَا وَمَا كُنَّا لِنَهْتَدِىَ لَوْلا أَنْ هَدَانَا اللَّهُ لَقَدْ جَآءَتْ رُسُلُ رَبِّنَا بِالْحَقِّ\n\r\n\n\r\n(எல்லாப் புகழும் அல்லாஹ்வுக்கே! அவன் தான் எங்களுக்கு இதற்கு நேர்வழி காட்டினான். அல்லாஹ் எங்களுக்கு நேர்வழி காட்டியிராவிட்டால், நாங்கள் ஒருபோதும் நேர்வழி பெற்றிருக்க மாட்டோம். நிச்சயமாக, எங்கள் இறைவனின் தூதர்கள் உண்மையையே கொண்டு வந்தார்கள்.)(7:43)\n\r\n\n\r\nஇரும்பின் பயன்கள்\n\r\n\n\r\nஅல்லாஹ் கூறினான்:\n\r\n\n\r\nوَأَنزَلْنَا الْحَدِيدَ فِيهِ بَأْسٌ شَدِيدٌ\n\r\n\n\r\n(மேலும் நாம் இரும்பை இறக்கினோம்; அதில் கடுமையான வலிமை உள்ளது), இதன் பொருள்: ‘சான்றுகள் தெளிவாக்கப்பட்ட பின்னரும் உண்மையை ஏற்க மறுத்து அதனை எதிர்ப்பவர்களைத் தடுக்கும் ஒரு கருவியாக நாம் இரும்பை ஆக்கினோம்.’ அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மக்காவில் பதின்மூன்று ஆண்டுகள் தங்கியிருந்தார்கள். அக்காலத்தில் அவர்களுக்கு வஹீ (இறைச்செய்தி) தொடர்ந்து அருளப்பட்டது. அதில் இணைவைப்பாளர்களுக்கு எதிரான வாதங்களும், தவ்ஹீத் (ஏகத்துவம்) குறித்த விரிவான விளக்கங்களும் சான்றுகளும் இருந்தன. தூதரை (ஸல்) எதிர்த்தவர்களுக்கு எதிராக ஆதாரங்கள் நிலைநாட்டப்பட்டபோது, அல்லாஹ் ஹிஜ்ரத்தை விதியாக்கினான். பின்னர், குர்ஆனை எதிர்த்து, நிராகரித்து மறுத்தவர்களின் கழுத்துகளிலும் நெற்றிகளிலும் தாக்குவதற்கு வாள்களைக் கொண்டு போர் செய்யுமாறு விசுவாசிகளுக்கு அவன் கட்டளையிட்டான். இமாம் அஹ்மத் மற்றும் அபூதாவூத் ஆகியோர் பதிவு செய்துள்ளனர், அப்துல்லாஹ் பின் உமர் (ரழி) அவர்கள் கூறினார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«بُعِثْتُ بِالسَّيْفِ بَيْنَ يَدَيِ السَّاعَةِ حَتَّى يُعْبَدَ اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَجُعِلَ رِزْقِي تَحْتَ ظِلِّ رُمْحِي، وَجُعِلَ الذِّلَّةُ والصَّغَارُ عَلَى مَنْ خَالَفَ أَمْرِي، وَمَنْ تَشَبَّهَ بِقَوْمٍ فَهُوَ مِنْهُم»\n\r\n\n\r\n(மறுமை நாளுக்கு முன்னதாக, இணையின்றி அல்லாஹ் ஒருவன் மட்டுமே வணங்கப்பட வேண்டும் என்பதற்காக நான் வாளுடன் அனுப்பப்பட்டேன். எனது வாழ்வாதாரம் எனது ஈட்டியின் நிழலின் கீழ் வைக்கப்பட்டுள்ளது. எனது கட்டளையை மீறுபவர்களுக்கு இழிவும் சிறுமையும் ஏற்படுத்தப்பட்டுள்ளது. எவர் ஒரு சமூகத்திற்கு ஒப்பாக நடக்கிறாரோ, அவர் அவர்களைச் சேர்ந்தவராவார்.) இதனால்தான் உயர்ந்தோனாகிய அல்லாஹ் கூறினான்:\n\r\n\n\r\nفِيهِ بَأْسٌ شَدِيدٌ\n\r\n\n\r\n(அதில் கடுமையான வலிமை உள்ளது), இது வாள்கள், ஈட்டிகள், குத்துவாள்கள், அம்புகள், கேடயங்கள் போன்ற ஆயுதங்களைக் குறிக்கிறது.\n\r\n\n\r\nوَمَنَافِعُ لِلنَّاسِ\n\r\n\n\r\n(மேலும் மனிதர்களுக்குப் பல பயன்களும் உள்ளன), அதாவது நாணயங்கள், சுத்தியல்கள், கோடாரிகள், ரம்பங்கள், உளிகள், மண்வெட்டிகள் மற்றும் நிலத்தை உழுவதற்கும், விதைப்பதற்கும், சமைப்பதற்கும், மாவு பிசைவதற்கும் மற்றும் அன்றாட வாழ்க்கைக்குத் தேவையான பல கருவிகளைத் தயாரிப்பதற்கும் மக்கள் இதைப் பயன்படுத்துகின்றனர். அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nوَلِيَعْلَمَ اللَّهُ مَن يَنصُرُهُ وَرُسُلَهُ بِالْغَيْبِ\n\r\n\n\r\n(மறைவான நிலையில் அல்லாஹ்வுக்கும் அவனது தூதர்களுக்கும் உதவி செய்பவர் யார் என்பதை அல்லாஹ் அறிந்துகொள்வதற்காக), அதாவது ஆயுதங்களை ஏந்துவதன் நோக்கம் அல்லாஹ்வுக்கும் (அவனது மார்க்கத்திற்கும்) அவனது தூதருக்கும் பாதுகாப்பளிப்பதாகும்.\n\r\n\n\r\nإِنَّ اللَّهَ قَوِىٌّ عَزِيزٌ\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் வலிமைமிக்கவன், மிகைத்தவன்.) இதன் பொருள், நிச்சயமாக அல்லாஹ் வலிமைமிக்கவன், யாவரையும் மிகைத்தவன். அவனுக்கு (அவனது மார்க்கத்திற்கு) உதவி செய்பவர்களுக்கு அவன் வெற்றியை அளிக்கிறான். எனினும், அல்லாஹ்வுக்கு மனிதர்களின் உதவி தேவையில்லை; ஒருவரைக் கொண்டு மற்றொருவரைச் சோதிப்பதற்காகவே அவன் ஜிஹாதை (அறப்போர்) கடமையாக்கினான்."},"26":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=57&ayah=27\" class=\"link\">57:27</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 57:27 ஐ பார்க்கவும்"},"27":{"html":"<strong>நபிமார்களின் சமுதாயங்களில் பலர் கீழ்ப்படியாதவர்களாக இருந்தனர்</strong><br />\r\n<br />\r\nமேன்மைமிக்க அல்லாஹ் கூறுகிறான்: அவன் நூஹ் (அலை) அவர்களை அனுப்பியது முதல், அவருக்குப் பிறகு அவன் அனுப்பிய அனைத்து நபிமார்களும் தூதர்களும் நூஹ் (அலை) அவர்களின் சந்ததியிலிருந்தே வந்தனர். அல்லாஹ்வின் கலீலான (நண்பரான) இப்ராஹீம் (அலை) அவர்களுக்குப் பிறகு அருளப்பட்ட அனைத்து வேதங்களும், வஹீ (இறைச்செய்தி) பெற்ற அனைத்து தூதர்களும் இப்ராஹீம் (அலை) அவர்களின் சந்ததியிலிருந்தே வந்தனர். மேன்மைமிக்க அல்லாஹ் மற்றொரு வசனத்தில் இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ذُرِّيَّتِهِ</span> <span class=\"quran-arabic-font text-success\">النُّبُوَّةَ</span> <span class=\"quran-arabic-font text-success\">وَالْكِتَـبَ</span><br />\r\n<br />\r\n(மேலும், அவர்களுடைய சந்ததியினருக்குள்ளேயே நபித்துவத்தையும் வேதத்தையும் நாம் ஏற்படுத்தினோம்.) <a href=\"qurandisp.php?sura=29&ayah=27\" class=\"link\">29:27</a><br />\r\n<br />\r\nபனூ இஸ்ராயீல் சந்ததியினரின் நபிமார்களில் இறுதியானவர் மர்யமின் புதல்வர் ஈஸா (அலை) அவர்கள் ஆவார். அவர்கள் முஹம்மது (ஸல்) அவர்களின் வருகையைப் பற்றிய நற்செய்தியை முன்னறிவிப்பு செய்தார்கள். மேன்மைமிக்க அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">قَفَّيْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">ءَاثَـرِهِم</span> <span class=\"quran-arabic-font text-success\">بِرُسُلِنَا</span> <span class=\"quran-arabic-font text-success\">وَقَفَّيْنَا</span> <span class=\"quran-arabic-font text-success\">بِعِيسَى</span> <span class=\"quran-arabic-font text-success\">ابْنِ</span> <span class=\"quran-arabic-font text-success\">مَرْيَمَ</span> <span class=\"quran-arabic-font text-success\">وَءَاتَيْنَـهُ</span> <span class=\"quran-arabic-font text-success\">الإِنجِيلَ</span><br />\r\n<br />\r\n(பின்னர், அவர்களுக்குப் பின்னால் நமது தூதர்களைத் தொடரச் செய்தோம்; மர்யமின் புதல்வர் ஈஸாவையும் தொடரச் செய்து அவருக்கு இன்ஜீலையும் வழங்கினோம்.) இது அல்லாஹ் அவருக்கு அருளிய இன்ஜீலைக் குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">قُلُوبِ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">اتَّبَعُوهُ</span><br />\r\n<br />\r\n(அவரைப் பின்பற்றியவர்களின் உள்ளங்களில் நாம் ஏற்படுத்தினோம்,) அதாவது ஹவாரிய்யீன்கள் (சீடர்கள்),<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">رَأْفَةً</span><br />\r\n<br />\r\n(இரக்கத்தையும்) மென்மையையும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَرَحْمَةً</span><br />\r\n<br />\r\n(மற்றும் கிருபையையும்.) படைப்பினங்கள் மீது (ஏற்படுத்தினோம்). அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَرَهْبَانِيَّةً</span> <span class=\"quran-arabic-font text-success\">ابتَدَعُوهَا</span><br />\r\n<br />\r\n(ஆனால் துறவறத்தை அவர்களாகவே புதிதாக உருவாக்கிக்கொண்டனர்,) இது கிறிஸ்தவ சமுதாயம் தாங்களாகவே உருவாக்கிக்கொண்ட துறவறத்தைக் குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كَتَبْنَـهَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span><br />\r\n<br />\r\n(அதை நாம் அவர்கள் மீது விதிக்கவில்லை) ‘நாம் -- அதாவது அல்லாஹ் -- அதை அவர்கள் மீது கடமையாக்கவில்லை, மாறாக அவர்கள் தாங்களாகவே அதைத் தேர்ந்தெடுத்தனர்.’<br />\r\n<br />\r\nஇதன் பொருளைப் பற்றி இரண்டு கருத்துக்கள் உள்ளன:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">ابْتِغَآءَ</span> <span class=\"quran-arabic-font text-success\">رِضْوَنِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n(அல்லாஹ்வின் திருப்பொருத்தத்தை நாடியே தவிர.) முதலாவது கருத்து: துறவறத்தை அவர்கள் புதிதாக உருவாக்கியதன் மூலம் அல்லாஹ்வின் திருப்பொருத்தத்தை நாட விரும்பினார்கள் என்பதாகும். ஸயீத் பின் ஜுபைர் (ரழி) மற்றும் கத்தாதா (ரழி) ஆகியோர் இதனைக் கூறியுள்ளனர். இரண்டாவது கருத்து: “அதைச் செய்யுமாறு நாம் அவர்களுக்குக் கட்டளையிடவில்லை, மாறாக அல்லாஹ்வின் விருப்பத்திற்குரியதைத் தேடுமாறே நாம் அவர்களுக்குக் கட்டளையிட்டோம்.” என்பதாகும். அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">رَعَوْهَا</span> <span class=\"quran-arabic-font text-success\">حَقَّ</span> <span class=\"quran-arabic-font text-success\">رِعَايَتِهَا</span><br />\r\n<br />\r\n(ஆனால் அவர்கள் அதை முறையாகப் பேணிக் கடைப்பிடிக்கவில்லை.) அதாவது, அவர்கள் தங்களுக்குத் தாங்களே விதித்துக்கொண்டதைக் கடைப்பிடிக்கவில்லை. இந்த வசனம் அவர்களை இரண்டு விதங்களில் கண்டிக்கிறது: முதலாவதாக, அல்லாஹ் அவர்களுக்குச் சட்டமாக்காத விஷயங்களைத் தங்கள் மார்க்கத்தில் அவர்கள் புதிதாகப் புகுத்தினார்கள். இரண்டாவதாக, மேன்மையும் கண்ணியமும் மிக்க அல்லாஹ்வை நெருங்குவதற்கான வழி என்று அவர்களாகவே உருவாக்கிக் கொண்ட அந்த விஷயங்களின் நிபந்தனைகளை அவர்களே நிறைவேற்றவில்லை.<br />\r\n<br />\r\nஇப்னு ஜரீர் மற்றும் அபூ அப்துர்-ரஹ்மான் அந்-நஸாயீ - இது அவருடைய வாசகம் - ஆகியோர் இப்னு அப்பாஸ் (ரழி) அவர்கள் பின்வருமாறு கூறியதாகப் பதிவு செய்துள்ளனர்: \"ஈஸா (அலை) அவர்களுக்குப் பிறகு தவ்ராத்தையும் இன்ஜீலையும் மாற்றிய சில மன்னர்கள் இருந்தனர். அப்போது தவ்ராத்தையும் இன்ஜீலையும் (உண்மையான வடிவில்) ஓதிக்கொண்டிருந்த முஃமின்களும் (நம்பிக்கையாளர்கள்) இருந்தனர். அந்த மன்னர்களிடம், 'இந்த மக்களைப் போன்ற கடும் விமர்சனங்களையும் வசைகளையும் நாம் ஒருபோதும் எதிர்கொண்டதில்லை' என்று கூறப்பட்டது. ஏனெனில் அவர்கள் இந்த வசனத்தை ஓதிக்கொண்டிருந்தனர்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">يَحْكُم</span> <span class=\"quran-arabic-font text-success\">بِمَآ</span> <span class=\"quran-arabic-font text-success\">أَنزَلَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">فَأُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْكَـفِرُونَ</span><br />\r\n<br />\r\n(அல்லாஹ் இறக்கி வைத்ததைக் கொண்டு எவர் தீர்ப்பளிக்கவில்லையோ அவர்கள் காஃபிர்களே (நிராகரிப்பாளர்கள்).) (<a href=\"qurandisp.php?sura=5&ayah=44\" class=\"link\">5:44</a>). மேலும், 'அவர்கள் இந்த வசனங்களை ஓதுவதுடன் நமது செயல்களில் உள்ள குறைபாடுகளையும் குற்றஞ்சாட்டுகிறார்கள். எனவே, அவர்களை அழைத்து இந்த வசனங்களை நாம் கூறுவது போல் ஓதச் சொல்லுங்கள்; நாம் நம்புவது போல் நம்பச் சொல்லுங்கள்' (எனக் கூறப்பட்டது).\"<br />\r\n<br />\r\nஅந்த மன்னன் அவர்களை அழைத்து ஒன்றுதிரட்டி, அசல் தவ்ராத்தையும் இன்ஜீலையும் ஓதுவதைக் கைவிட்டு, மாற்றப்பட்ட பதிப்பை மட்டுமே பின்பற்றாவிட்டால் மரண தண்டனை விதிப்பதாக அச்சுறுத்தினான். அதற்கு அவர்கள், 'எங்களை ஏன் இவ்வாறு வற்புறுத்துகிறீர்கள்? எங்களை எம்போக்கில் விட்டுவிடுங்கள்' என்றனர். அவர்களில் ஒரு சாரார், 'எங்களுக்கு உயரமான கோபுரத்தைக் கட்டிக் கொடுங்கள்; நாங்கள் அதில் ஏறிக்கொள்கிறோம். எங்களுக்குத் தேவையான உணவு, பானங்களை மேலே அனுப்புவதற்கு வழி செய்யுங்கள். இதன் மூலம் நாங்கள் ஓதுவதை நீங்கள் கேட்பதிலிருந்து தப்பித்துக் கொள்ளலாம்' என்றனர். மற்றொரு குழுவினர், 'நாங்கள் இந்த பூமியில் நாடோடிகளாகத் திரிந்து விலங்குகளைப் போல் உண்டு குடித்துக் கொள்கிறோம். உங்கள் நாட்டில் எங்களைக் கண்டால் எங்களைக் கொன்று விடுங்கள்' என்றனர். வேறொரு குழுவினர், 'பாலைவனங்களிலும் ஆள்நடமாட்டமில்லாத இடங்களிலும் எங்களுக்கு மடாலயங்களை (துறவி இல்லங்களை) அமைத்துக் கொடுங்கள்; அங்கே நாங்கள் கிணறு தோண்டி காய்கறிகளைப் பயிரிட்டுக் கொள்கிறோம். அதன் பிறகு நாங்கள் உங்களை எதிர்க்க மாட்டோம், உங்கள் பக்கமும் வர மாட்டோம்' என்றனர். தத்தமது கோத்திரங்களில் தங்களுக்கு ஆதரவாளர்கள் இருந்தபோதிலும் அவர்கள் இவ்வாறு கூறினர். இதனைப் பற்றித்தான் மேன்மையும் கண்ணியமும் மிக்க அல்லாஹ் இந்த வசனத்தை இறக்கினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَرَهْبَانِيَّةً</span> <span class=\"quran-arabic-font text-success\">ابتَدَعُوهَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كَتَبْنَـهَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">ابْتِغَآءَ</span> <span class=\"quran-arabic-font text-success\">رِضْوَنِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">رَعَوْهَا</span> <span class=\"quran-arabic-font text-success\">حَقَّ</span> <span class=\"quran-arabic-font text-success\">رِعَايَتِهَا</span><br />\r\n<br />\r\n(துறவறத்தை அவர்களாகவே புதிதாக உருவாக்கிக்கொண்டனர். அல்லாஹ்வின் திருப்பொருத்தத்தை நாடுவதற்காகவே அன்றி அதனை நாம் அவர்கள் மீது விதிக்கவில்லை. ஆனால் அதையும் அவர்கள் முறையாகப் பேணிக் கடைப்பிடிக்கவில்லை.)\"<br />\r\n<br />\r\nஇமாம் அஹ்மத் பதிவு செய்துள்ளதாவது: அனஸ் பின் மாலிக் (ரழி) அவர்கள் அறிவிக்கிறார்கள், நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لِكُلِّ</span> <span class=\"quran-arabic-font text-success\">نَبِيٍّ</span> <span class=\"quran-arabic-font text-success\">رَهْبَانِيَّةٌ،</span> <span class=\"quran-arabic-font text-success\">وَرَهْبَانِيَّةُ</span> <span class=\"quran-arabic-font text-success\">هذِهِ</span> <span class=\"quran-arabic-font text-success\">الْأُمَّةِ</span> <span class=\"quran-arabic-font text-success\">الْجِهَادُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">سَبِيلِ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">عَزَّ</span> <span class=\"quran-arabic-font text-success\">وَجَل</span>»<br />\r\n<br />\r\n(ஒவ்வொரு நபிக்கும் ஒரு ரஹ்பானிய்யா (துறவறம்) உண்டு; மேன்மையும் கண்ணியமும் மிக்க அல்லாஹ்வின் பாதையில் ஜிஹாத் செய்வதே இந்த உம்மத்தின் ரஹ்பானிய்யா ஆகும்.)<br />\r\n<br />\r\nஅல்-ஹாஃபிழ் அபூ யஃலா சேகரித்துள்ள இந்த ஹதீஸின் மற்றோர் அறிவிப்பில் நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لِكُلِّ</span> <span class=\"quran-arabic-font text-success\">أُمَّةٍ</span> <span class=\"quran-arabic-font text-success\">رَهْبَانِيَّةٌ،</span> <span class=\"quran-arabic-font text-success\">وَرَهْبَانِيَّةُ</span> <span class=\"quran-arabic-font text-success\">هذِهِ</span> <span class=\"quran-arabic-font text-success\">الْأُمَّةِ</span> <span class=\"quran-arabic-font text-success\">الْجِهَادُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">سَبِيلِ</span> <span class=\"quran-arabic-font text-success\">الله</span>»<br />\r\n<br />\r\n(ஒவ்வொரு உம்மத்திற்கும் ஒரு ரஹ்பானிய்யா உண்டு; அல்லாஹ்வின் பாதையில் ஜிஹாத் செய்வதே இந்த உம்மத்தின் ரஹ்பானிய்யா ஆகும்.)<br />\r\n<br />\r\nஇமாம் அஹ்மத் பதிவு செய்துள்ளதாவது: அபூ ஸயீத் அல்-குத்ரீ (ரழி) அவர்களிடம் ஒருவர் வந்து அறிவுரை வேண்டினார். அப்போது அபூ ஸயீத் (ரழி) அவர்கள், தாம் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் கேட்டதையே அவருக்கும் கூறினார்கள்: \"அல்லாஹ்வின் மீது தக்வா (இறையச்சம்) கொள்ளுமாறு உமக்கு நான் அறிவுறுத்துகிறேன். ஏனெனில் அதுவே அனைத்துக் காரியங்களுக்கும் மூலாதாரமாகும். ஜிஹாத் எனும் கடமையை நிறைவேற்றுவீராக! ஏனெனில் அதுவே இஸ்லாத்தின் ரஹ்பானிய்யா (துறவறம்) ஆகும். அல்லாஹ்வை திக்ர் செய்வதிலும் குர்ஆனை ஓதுவதிலும் ஆர்வம் காட்டுவீராக! ஏனெனில் அது வானங்களில் உமக்கு உயர்வாகவும், பூமியில் உமக்கு நற்பெயராகவும் அமையும்.\" இந்த ஹதீஸை இமாம் அஹ்மத் மட்டுமே பதிவு செய்துள்ளார்.<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَـآتَيْنَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">أَجْرَهُمْ</span><br />\r\n<br />\r\n(ஆகவே, அவர்களில் ஈமான் கொண்டவர்களுக்கு அவர்களுடைய கூலியை நாம் வழங்கினோம்.) அதாவது, அவர்களில் ஈஸா (அலை) அவர்களைப் பின்பற்றியவர்களுக்கும், முஹம்மது (ஸல்) அவர்களை நம்பிக்கை கொண்டவர்களுக்கும் அவர்களது கூலியை நாம் வழங்கினோம்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَثِيرٌ</span> <span class=\"quran-arabic-font text-success\">مِّنْهُمْ</span> <span class=\"quran-arabic-font text-success\">فَـسِقُونَ</span><br />\r\n<br />\r\n(மேலும், அவர்களில் பலர் ஃபாஸிக்குகளாக உள்ளனர்.) அதாவது, அவர்களில் பெரும்பாலோர் சத்தியத்தை மறுத்து, அதனை விட்டு விலகிச் சென்றுவிட்டனர்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"நபிமார்களின் சமுதாயங்களில் பலர் கீழ்ப்படியாதவர்களாக இருந்தனர்\n\r\n\n\r\nமேன்மைமிக்க அல்லாஹ் கூறுகிறான்: அவன் நூஹ் (அலை) அவர்களை அனுப்பியது முதல், அவருக்குப் பிறகு அவன் அனுப்பிய அனைத்து நபிமார்களும் தூதர்களும் நூஹ் (அலை) அவர்களின் சந்ததியிலிருந்தே வந்தனர். அல்லாஹ்வின் கலீலான (நண்பரான) இப்ராஹீம் (அலை) அவர்களுக்குப் பிறகு அருளப்பட்ட அனைத்து வேதங்களும், வஹீ (இறைச்செய்தி) பெற்ற அனைத்து தூதர்களும் இப்ராஹீம் (அலை) அவர்களின் சந்ததியிலிருந்தே வந்தனர். மேன்மைமிக்க அல்லாஹ் மற்றொரு வசனத்தில் இவ்வாறு கூறுகிறான்:\n\r\n\n\r\nوَجَعَلْنَا فِى ذُرِّيَّتِهِ النُّبُوَّةَ وَالْكِتَـبَ\n\r\n\n\r\n(மேலும், அவர்களுடைய சந்ததியினருக்குள்ளேயே நபித்துவத்தையும் வேதத்தையும் நாம் ஏற்படுத்தினோம்.) 29:27\n\r\n\n\r\nபனூ இஸ்ராயீல் சந்ததியினரின் நபிமார்களில் இறுதியானவர் மர்யமின் புதல்வர் ஈஸா (அலை) அவர்கள் ஆவார். அவர்கள் முஹம்மது (ஸல்) அவர்களின் வருகையைப் பற்றிய நற்செய்தியை முன்னறிவிப்பு செய்தார்கள். மேன்மைமிக்க அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nثُمَّ قَفَّيْنَا عَلَى ءَاثَـرِهِم بِرُسُلِنَا وَقَفَّيْنَا بِعِيسَى ابْنِ مَرْيَمَ وَءَاتَيْنَـهُ الإِنجِيلَ\n\r\n\n\r\n(பின்னர், அவர்களுக்குப் பின்னால் நமது தூதர்களைத் தொடரச் செய்தோம்; மர்யமின் புதல்வர் ஈஸாவையும் தொடரச் செய்து அவருக்கு இன்ஜீலையும் வழங்கினோம்.) இது அல்லாஹ் அவருக்கு அருளிய இன்ஜீலைக் குறிக்கிறது.\n\r\n\n\r\nوَجَعَلْنَا فِى قُلُوبِ الَّذِينَ اتَّبَعُوهُ\n\r\n\n\r\n(அவரைப் பின்பற்றியவர்களின் உள்ளங்களில் நாம் ஏற்படுத்தினோம்,) அதாவது ஹவாரிய்யீன்கள் (சீடர்கள்),\n\r\n\n\r\nرَأْفَةً\n\r\n\n\r\n(இரக்கத்தையும்) மென்மையையும்,\n\r\n\n\r\nوَرَحْمَةً\n\r\n\n\r\n(மற்றும் கிருபையையும்.) படைப்பினங்கள் மீது (ஏற்படுத்தினோம்). அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nوَرَهْبَانِيَّةً ابتَدَعُوهَا\n\r\n\n\r\n(ஆனால் துறவறத்தை அவர்களாகவே புதிதாக உருவாக்கிக்கொண்டனர்,) இது கிறிஸ்தவ சமுதாயம் தாங்களாகவே உருவாக்கிக்கொண்ட துறவறத்தைக் குறிக்கிறது.\n\r\n\n\r\nمَا كَتَبْنَـهَا عَلَيْهِمْ\n\r\n\n\r\n(அதை நாம் அவர்கள் மீது விதிக்கவில்லை) ‘நாம் -- அதாவது அல்லாஹ் -- அதை அவர்கள் மீது கடமையாக்கவில்லை, மாறாக அவர்கள் தாங்களாகவே அதைத் தேர்ந்தெடுத்தனர்.’\n\r\n\n\r\nஇதன் பொருளைப் பற்றி இரண்டு கருத்துக்கள் உள்ளன:\n\r\n\n\r\nإِلاَّ ابْتِغَآءَ رِضْوَنِ اللَّهِ\n\r\n\n\r\n(அல்லாஹ்வின் திருப்பொருத்தத்தை நாடியே தவிர.) முதலாவது கருத்து: துறவறத்தை அவர்கள் புதிதாக உருவாக்கியதன் மூலம் அல்லாஹ்வின் திருப்பொருத்தத்தை நாட விரும்பினார்கள் என்பதாகும். ஸயீத் பின் ஜுபைர் (ரழி) மற்றும் கத்தாதா (ரழி) ஆகியோர் இதனைக் கூறியுள்ளனர். இரண்டாவது கருத்து: “அதைச் செய்யுமாறு நாம் அவர்களுக்குக் கட்டளையிடவில்லை, மாறாக அல்லாஹ்வின் விருப்பத்திற்குரியதைத் தேடுமாறே நாம் அவர்களுக்குக் கட்டளையிட்டோம்.” என்பதாகும். அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nفَمَا رَعَوْهَا حَقَّ رِعَايَتِهَا\n\r\n\n\r\n(ஆனால் அவர்கள் அதை முறையாகப் பேணிக் கடைப்பிடிக்கவில்லை.) அதாவது, அவர்கள் தங்களுக்குத் தாங்களே விதித்துக்கொண்டதைக் கடைப்பிடிக்கவில்லை. இந்த வசனம் அவர்களை இரண்டு விதங்களில் கண்டிக்கிறது: முதலாவதாக, அல்லாஹ் அவர்களுக்குச் சட்டமாக்காத விஷயங்களைத் தங்கள் மார்க்கத்தில் அவர்கள் புதிதாகப் புகுத்தினார்கள். இரண்டாவதாக, மேன்மையும் கண்ணியமும் மிக்க அல்லாஹ்வை நெருங்குவதற்கான வழி என்று அவர்களாகவே உருவாக்கிக் கொண்ட அந்த விஷயங்களின் நிபந்தனைகளை அவர்களே நிறைவேற்றவில்லை.\n\r\n\n\r\nஇப்னு ஜரீர் மற்றும் அபூ அப்துர்-ரஹ்மான் அந்-நஸாயீ - இது அவருடைய வாசகம் - ஆகியோர் இப்னு அப்பாஸ் (ரழி) அவர்கள் பின்வருமாறு கூறியதாகப் பதிவு செய்துள்ளனர்: \"ஈஸா (அலை) அவர்களுக்குப் பிறகு தவ்ராத்தையும் இன்ஜீலையும் மாற்றிய சில மன்னர்கள் இருந்தனர். அப்போது தவ்ராத்தையும் இன்ஜீலையும் (உண்மையான வடிவில்) ஓதிக்கொண்டிருந்த முஃமின்களும் (நம்பிக்கையாளர்கள்) இருந்தனர். அந்த மன்னர்களிடம், 'இந்த மக்களைப் போன்ற கடும் விமர்சனங்களையும் வசைகளையும் நாம் ஒருபோதும் எதிர்கொண்டதில்லை' என்று கூறப்பட்டது. ஏனெனில் அவர்கள் இந்த வசனத்தை ஓதிக்கொண்டிருந்தனர்:\n\r\n\n\r\nوَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ اللَّهُ فَأُوْلَـئِكَ هُمُ الْكَـفِرُونَ\n\r\n\n\r\n(அல்லாஹ் இறக்கி வைத்ததைக் கொண்டு எவர் தீர்ப்பளிக்கவில்லையோ அவர்கள் காஃபிர்களே (நிராகரிப்பாளர்கள்).) (5:44). மேலும், 'அவர்கள் இந்த வசனங்களை ஓதுவதுடன் நமது செயல்களில் உள்ள குறைபாடுகளையும் குற்றஞ்சாட்டுகிறார்கள். எனவே, அவர்களை அழைத்து இந்த வசனங்களை நாம் கூறுவது போல் ஓதச் சொல்லுங்கள்; நாம் நம்புவது போல் நம்பச் சொல்லுங்கள்' (எனக் கூறப்பட்டது).\"\n\r\n\n\r\nஅந்த மன்னன் அவர்களை அழைத்து ஒன்றுதிரட்டி, அசல் தவ்ராத்தையும் இன்ஜீலையும் ஓதுவதைக் கைவிட்டு, மாற்றப்பட்ட பதிப்பை மட்டுமே பின்பற்றாவிட்டால் மரண தண்டனை விதிப்பதாக அச்சுறுத்தினான். அதற்கு அவர்கள், 'எங்களை ஏன் இவ்வாறு வற்புறுத்துகிறீர்கள்? எங்களை எம்போக்கில் விட்டுவிடுங்கள்' என்றனர். அவர்களில் ஒரு சாரார், 'எங்களுக்கு உயரமான கோபுரத்தைக் கட்டிக் கொடுங்கள்; நாங்கள் அதில் ஏறிக்கொள்கிறோம். எங்களுக்குத் தேவையான உணவு, பானங்களை மேலே அனுப்புவதற்கு வழி செய்யுங்கள். இதன் மூலம் நாங்கள் ஓதுவதை நீங்கள் கேட்பதிலிருந்து தப்பித்துக் கொள்ளலாம்' என்றனர். மற்றொரு குழுவினர், 'நாங்கள் இந்த பூமியில் நாடோடிகளாகத் திரிந்து விலங்குகளைப் போல் உண்டு குடித்துக் கொள்கிறோம். உங்கள் நாட்டில் எங்களைக் கண்டால் எங்களைக் கொன்று விடுங்கள்' என்றனர். வேறொரு குழுவினர், 'பாலைவனங்களிலும் ஆள்நடமாட்டமில்லாத இடங்களிலும் எங்களுக்கு மடாலயங்களை (துறவி இல்லங்களை) அமைத்துக் கொடுங்கள்; அங்கே நாங்கள் கிணறு தோண்டி காய்கறிகளைப் பயிரிட்டுக் கொள்கிறோம். அதன் பிறகு நாங்கள் உங்களை எதிர்க்க மாட்டோம், உங்கள் பக்கமும் வர மாட்டோம்' என்றனர். தத்தமது கோத்திரங்களில் தங்களுக்கு ஆதரவாளர்கள் இருந்தபோதிலும் அவர்கள் இவ்வாறு கூறினர். இதனைப் பற்றித்தான் மேன்மையும் கண்ணியமும் மிக்க அல்லாஹ் இந்த வசனத்தை இறக்கினான்:\n\r\n\n\r\nوَرَهْبَانِيَّةً ابتَدَعُوهَا مَا كَتَبْنَـهَا عَلَيْهِمْ إِلاَّ ابْتِغَآءَ رِضْوَنِ اللَّهِ فَمَا رَعَوْهَا حَقَّ رِعَايَتِهَا\n\r\n\n\r\n(துறவறத்தை அவர்களாகவே புதிதாக உருவாக்கிக்கொண்டனர். அல்லாஹ்வின் திருப்பொருத்தத்தை நாடுவதற்காகவே அன்றி அதனை நாம் அவர்கள் மீது விதிக்கவில்லை. ஆனால் அதையும் அவர்கள் முறையாகப் பேணிக் கடைப்பிடிக்கவில்லை.)\"\n\r\n\n\r\nஇமாம் அஹ்மத் பதிவு செய்துள்ளதாவது: அனஸ் பின் மாலிக் (ரழி) அவர்கள் அறிவிக்கிறார்கள், நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«لِكُلِّ نَبِيٍّ رَهْبَانِيَّةٌ، وَرَهْبَانِيَّةُ هذِهِ الْأُمَّةِ الْجِهَادُ فِي سَبِيلِ اللهِ عَزَّ وَجَل»\n\r\n\n\r\n(ஒவ்வொரு நபிக்கும் ஒரு ரஹ்பானிய்யா (துறவறம்) உண்டு; மேன்மையும் கண்ணியமும் மிக்க அல்லாஹ்வின் பாதையில் ஜிஹாத் செய்வதே இந்த உம்மத்தின் ரஹ்பானிய்யா ஆகும்.)\n\r\n\n\r\nஅல்-ஹாஃபிழ் அபூ யஃலா சேகரித்துள்ள இந்த ஹதீஸின் மற்றோர் அறிவிப்பில் நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«لِكُلِّ أُمَّةٍ رَهْبَانِيَّةٌ، وَرَهْبَانِيَّةُ هذِهِ الْأُمَّةِ الْجِهَادُ فِي سَبِيلِ الله»\n\r\n\n\r\n(ஒவ்வொரு உம்மத்திற்கும் ஒரு ரஹ்பானிய்யா உண்டு; அல்லாஹ்வின் பாதையில் ஜிஹாத் செய்வதே இந்த உம்மத்தின் ரஹ்பானிய்யா ஆகும்.)\n\r\n\n\r\nஇமாம் அஹ்மத் பதிவு செய்துள்ளதாவது: அபூ ஸயீத் அல்-குத்ரீ (ரழி) அவர்களிடம் ஒருவர் வந்து அறிவுரை வேண்டினார். அப்போது அபூ ஸயீத் (ரழி) அவர்கள், தாம் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் கேட்டதையே அவருக்கும் கூறினார்கள்: \"அல்லாஹ்வின் மீது தக்வா (இறையச்சம்) கொள்ளுமாறு உமக்கு நான் அறிவுறுத்துகிறேன். ஏனெனில் அதுவே அனைத்துக் காரியங்களுக்கும் மூலாதாரமாகும். ஜிஹாத் எனும் கடமையை நிறைவேற்றுவீராக! ஏனெனில் அதுவே இஸ்லாத்தின் ரஹ்பானிய்யா (துறவறம்) ஆகும். அல்லாஹ்வை திக்ர் செய்வதிலும் குர்ஆனை ஓதுவதிலும் ஆர்வம் காட்டுவீராக! ஏனெனில் அது வானங்களில் உமக்கு உயர்வாகவும், பூமியில் உமக்கு நற்பெயராகவும் அமையும்.\" இந்த ஹதீஸை இமாம் அஹ்மத் மட்டுமே பதிவு செய்துள்ளார்.\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَـآتَيْنَا الَّذِينَ ءَامَنُواْ مِنْهُمْ أَجْرَهُمْ\n\r\n\n\r\n(ஆகவே, அவர்களில் ஈமான் கொண்டவர்களுக்கு அவர்களுடைய கூலியை நாம் வழங்கினோம்.) அதாவது, அவர்களில் ஈஸா (அலை) அவர்களைப் பின்பற்றியவர்களுக்கும், முஹம்மது (ஸல்) அவர்களை நம்பிக்கை கொண்டவர்களுக்கும் அவர்களது கூலியை நாம் வழங்கினோம்.\n\r\n\n\r\nوَكَثِيرٌ مِّنْهُمْ فَـسِقُونَ\n\r\n\n\r\n(மேலும், அவர்களில் பலர் ஃபாஸிக்குகளாக உள்ளனர்.) அதாவது, அவர்களில் பெரும்பாலோர் சத்தியத்தை மறுத்து, அதனை விட்டு விலகிச் சென்றுவிட்டனர்."},"28":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=57&ayah=29\" class=\"link\">57:29</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 57:29 ஐ பார்க்கவும்"},"29":{"html":"<strong>வேதக்காரர்களில் ஈமான் கொண்டவர்களுக்கு இரு மடங்கு நற்கூலி கிடைக்கும்</strong><br />\r\n<br />\r\nஇஸ்லாத்தை ஏற்றுக்கொண்ட வேதக்காரர்களைப் பற்றியே இந்த வசனம் இறங்கியது என்றும், அவ்வாறு அவர்கள் ஈமான் கொள்ளும்போது தங்களது நற்கூலியை இரு மடங்காகப் பெறுவார்கள் என்றும் இப்னு அப்பாஸ் (ரழி) அவர்கள் வழியாக அன்-நஸாஈ பதிவு செய்துள்ள ஒரு ஹதீஸை நாம் முன்பே குறிப்பிட்டோம். இந்தக் கருத்தை உறுதிப்படுத்தும் ஒரு வசனம் சூரத்துல் கஸஸிலும் இடம் பெற்றுள்ளது. மேலும், அபூ மூஸா அல்-அஷ்அரீ (ரழி) அவர்கள் அறிவிக்க, அவர்களின் தந்தை வழியாக அபூ புர்தா, அவரிடமிருந்து அஷ்-ஷஃபீ அறிவிக்கும் ஒரு ஹதீஸில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">ثَلَاثَةٌ</span> <span class=\"quran-arabic-font text-success\">يُؤْتَوْنَ</span> <span class=\"quran-arabic-font text-success\">أَجْرَهُمْ</span> <span class=\"quran-arabic-font text-success\">مَرَّتَيْنِ</span>: <span class=\"quran-arabic-font text-success\">رَجُلٌ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">الْكِتَابِ</span> <span class=\"quran-arabic-font text-success\">آمَنَ</span> <span class=\"quran-arabic-font text-success\">بِنَبِيِّهِ</span> <span class=\"quran-arabic-font text-success\">وَآمَنَ</span> <span class=\"quran-arabic-font text-success\">بِي</span> <span class=\"quran-arabic-font text-success\">فَلَهُ</span> <span class=\"quran-arabic-font text-success\">أَجْرَانِ،</span> <span class=\"quran-arabic-font text-success\">وَعَبْدٌ</span> <span class=\"quran-arabic-font text-success\">مَمْلُوكٌ</span> <span class=\"quran-arabic-font text-success\">أَدَّى</span> <span class=\"quran-arabic-font text-success\">حَقَّ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">وَحَقَّ</span> <span class=\"quran-arabic-font text-success\">مَوَالِيهِ</span> <span class=\"quran-arabic-font text-success\">فَلَهُ</span> <span class=\"quran-arabic-font text-success\">أَجْرَانِ،</span> <span class=\"quran-arabic-font text-success\">وَرَجُلٌ</span> <span class=\"quran-arabic-font text-success\">أَدَّبَ</span> <span class=\"quran-arabic-font text-success\">أَمَتَهُ</span> <span class=\"quran-arabic-font text-success\">فَأَحْسَنَ</span> <span class=\"quran-arabic-font text-success\">تَأْدِيبَهَا،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">أَعْتَقَهَا</span> <span class=\"quran-arabic-font text-success\">وَتَزَوَّجَهَا</span> <span class=\"quran-arabic-font text-success\">فَلَهُ</span> <span class=\"quran-arabic-font text-success\">أَجْرَان</span>»<br />\r\n<br />\r\n(மூன்று நபர்களுக்கு அவர்களின் நற்கூலி இருமுறை வழங்கப்படும். வேதக்காரர்களில் உள்ள ஒரு நம்பிக்கையாளர், அவர் தனது நபியின் மீது ஈமான் கொண்டு, பிறகு என் மீதும் ஈமான் கொண்டால் அவருக்கு இரு மடங்கு நற்கூலி உண்டு. அல்லாஹ்வின் உரிமைகளையும் கடமைகளையும் நிறைவேற்றி, தனது எஜமானரின் கடமைகளையும் நிறைவேற்றும் ஓர் அடிமைக்கும் இரு மடங்கு நற்கூலி உண்டு. தன்னிடம் உள்ள ஓர் அடிமைப் பெண்ணுக்கு முறையாகக் கல்வியூட்டி, நற்பண்புகளை முறையாகக் கற்றுக்கொடுத்து (கடுமையின்றி), பின்னர் அவளை விடுதலை செய்து மணமுடித்துக் கொண்டவருக்கும் இரு மடங்கு நற்கூலி உண்டு.) இந்த ஹதீஸ் புகாரி மற்றும் முஸ்லிம் ஆகிய இரு ஸஹீஹ் நூல்களிலும் இடம் பெற்றுள்ளது. அத்-தஹ்ஹாக், உத்பா பின் அபீ ஹக்கீம் மற்றும் பலர் இவ்விஷயத்தில் இப்னு அப்பாஸ் (ரழி) அவர்களுடன் உடன்படுகின்றனர்; இப்னு ஜரீரும் இதையே சிறந்த கருத்தாகக் கொண்டுள்ளார். உயர்ந்தோனாகிய அல்லாஹ் மற்றொரு வசனத்தில் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">تَتَّقُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">يَجْعَل</span> <span class=\"quran-arabic-font text-success\">لَّكُمْ</span> <span class=\"quran-arabic-font text-success\">فُرْقَانًا</span> <span class=\"quran-arabic-font text-success\">وَيُكَفِّرْ</span> <span class=\"quran-arabic-font text-success\">عَنكُمْ</span> <span class=\"quran-arabic-font text-success\">سَيِّئَاتِكُمْ</span> <span class=\"quran-arabic-font text-success\">وَيَغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">ذُو</span> <span class=\"quran-arabic-font text-success\">الْفَضْلِ</span> <span class=\"quran-arabic-font text-success\">الْعَظِيمِ</span><br />\r\n<br />\r\n(நம்பிக்கை கொண்டோரே! நீங்கள் அல்லாஹ்வுக்கு அஞ்சி நடந்தால், அவன் உங்களுக்கு (நன்மை தீமைகளை)ப் பிரித்தறியும் ஆற்றலை வழங்குவான்; உங்கள் பாவங்களை உங்களை விட்டும் போக்கி, உங்களை மன்னிப்பான். மேலும் அல்லாஹ் மகத்தான அருட்கொடையுடையவன்.) (<a href=\"qurandisp.php?sura=8&ayah=29\" class=\"link\">8:29</a>) ஸஈத் பின் அப்துல் அஜீஸ் அவர்கள் கூறினார்கள்: உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள் ஒரு யூத அறிஞரிடம், \"உங்களுக்கு நற்கூலி அதிகபட்சமாக எவ்வளவு அதிகரிக்கப்படும்?\" என்று கேட்டார்கள். அதற்கு அவர், \"ஒரு 'கிஃப்ல்' (பங்கு), அது சுமார் முந்நூற்று ஐம்பது நன்மைகளுக்குச் சமமானது\" என்று பதிலளித்தார். அப்போது உமர் (ரழி) அவர்கள், \"நமக்கு இரண்டு கிஃப்ல்களை வழங்கிய அல்லாஹ்வுக்கே புகழனைத்தும்\" என்று கூறினார்கள். பின்னர் ஸஈத் அவர்கள் அல்லாஹ்வின் இவ்வசனத்தைக் குறிப்பிட்டார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يُؤْتِكُمْ</span> <span class=\"quran-arabic-font text-success\">كِفْلَيْنِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رَّحْمَتِهِ</span><br />\r\n<br />\r\n(அவன் தனது அருளிலிருந்து உங்களுக்கு இரு பங்குகளை வழங்குவான்.) \"வெள்ளிக்கிழமையன்று கிடைக்கும் இரு கிஃப்ல்களும் இதைப் போன்றதே\" என்று ஸஈத் கூறினார்கள். இதனை இப்னு ஜரீர் பதிவு செய்துள்ளார். இமாம் அஹ்மத் அவர்கள் அப்துல்லாஹ் பின் உமர் (ரழி) வழியாகப் பதிவு செய்துள்ள ஒரு ஹதீஸும் இந்தக் கருத்தை ஆதரிக்கிறது. அதில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَثَلُكُمْ</span> <span class=\"quran-arabic-font text-success\">وَمَثَلُ</span> <span class=\"quran-arabic-font text-success\">الْيَهُودِ</span> <span class=\"quran-arabic-font text-success\">وَالنَّصَارَى</span> <span class=\"quran-arabic-font text-success\">كَمَثَلِ</span> <span class=\"quran-arabic-font text-success\">رَجُلٍ</span> <span class=\"quran-arabic-font text-success\">اسْتَعْمَلَ</span> <span class=\"quran-arabic-font text-success\">عُمَّالًا</span> <span class=\"quran-arabic-font text-success\">فَقَالَ</span>: <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">يَعْمَلُ</span> <span class=\"quran-arabic-font text-success\">لِي</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">صَلَاةِ</span> <span class=\"quran-arabic-font text-success\">الصُّبْحِ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">نِصْفِ</span> <span class=\"quran-arabic-font text-success\">النَّهَارِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">قِيرَاطٍ</span> <span class=\"quran-arabic-font text-success\">قِيرَاطٍ؟</span> <span class=\"quran-arabic-font text-success\">أَلَا</span> <span class=\"quran-arabic-font text-success\">فَعَمِلَتِ</span> <span class=\"quran-arabic-font text-success\">الْيَهُودُ،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span>: <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">يَعْمَلُ</span> <span class=\"quran-arabic-font text-success\">لِي</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">صَلَاةِ</span> <span class=\"quran-arabic-font text-success\">الظُّهْرِ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">صَلَاةِ</span> <span class=\"quran-arabic-font text-success\">الْعَصْرِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">قِيرَاطٍ</span> <span class=\"quran-arabic-font text-success\">قِيرَاطٍ؟</span> <span class=\"quran-arabic-font text-success\">أَلَا</span> <span class=\"quran-arabic-font text-success\">فَعَمِلَتِ</span> <span class=\"quran-arabic-font text-success\">النَّصَارَى،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span>: <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">يَعْمَلُ</span> <span class=\"quran-arabic-font text-success\">لِي</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">صَلَاةِ</span> <span class=\"quran-arabic-font text-success\">الْعَصْرِ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">غُرُوبِ</span> <span class=\"quran-arabic-font text-success\">الشَّمْسِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">قِيرَاطَيْنِ</span> <span class=\"quran-arabic-font text-success\">قِيرَاطَيْنِ؟</span> <span class=\"quran-arabic-font text-success\">أَلَا</span> <span class=\"quran-arabic-font text-success\">فَأَنْتُمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">عَمِلْتُمْ،</span> <span class=\"quran-arabic-font text-success\">فَغَضِبَ</span> <span class=\"quran-arabic-font text-success\">النَّصَارَى</span> <span class=\"quran-arabic-font text-success\">وَالْيَهُودُ</span> <span class=\"quran-arabic-font text-success\">وَقَالُوا</span>: <span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرُ</span> <span class=\"quran-arabic-font text-success\">عَمَلًا</span> <span class=\"quran-arabic-font text-success\">وَأَقَلُّ</span> <span class=\"quran-arabic-font text-success\">عَطَاءً،</span> <span class=\"quran-arabic-font text-success\">قَالَ</span>: <span class=\"quran-arabic-font text-success\">هَلْ</span> <span class=\"quran-arabic-font text-success\">ظَلَمْتُكُمْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَجْرِكُمْ</span> <span class=\"quran-arabic-font text-success\">شَيْئًا؟</span> <span class=\"quran-arabic-font text-success\">قَالُوا</span>: <span class=\"quran-arabic-font text-success\">لَا،</span> <span class=\"quran-arabic-font text-success\">قَالَ</span>: <span class=\"quran-arabic-font text-success\">فَإِنَّمَا</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">فَضْلِي</span> <span class=\"quran-arabic-font text-success\">أُوتِيهِ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أَشَاء</span>»<br />\r\n<br />\r\n(உங்களுக்கும் யூத, கிறிஸ்தவர்களுக்கும் உள்ள உவமையாவது: ஒரு மனிதர் சில தொழிலாளர்களை வேலைக்கு அமர்த்தி, \"சுபஹ் தொழுகையிலிருந்து நண்பகல் வரை தலா ஒரு 'கீராத்' (ஒரு குறிப்பிட்ட எடை அளவு) கூலிக்கு எனக்காகப் பணியாற்றுபவர் யார்?\" என்று கேட்டார். யூதர்கள் அந்த வேலையைச் செய்தார்கள். பிறகு அவர், \"லுஹ்ருத் தொழுகையிலிருந்து அஸர் தொழுகை வரை தலா ஒரு கீராத் கூலிக்கு எனக்காகப் பணியாற்றுபவர் யார்?\" என்று கேட்டார். கிறிஸ்தவர்கள் அந்த வேலையைச் செய்தார்கள். பிறகு அவர், \"அஸர் தொழுகையிலிருந்து சூரியன் மறையும் வரை தலா இரண்டு கீராத் கூலிக்கு எனக்காகப் பணியாற்றுபவர் யார்?\" என்று கேட்டார். நீங்கள்தான் அந்த வேலையைச் செய்தவர்கள். இதைக் கண்டு யூதர்களும் கிறிஸ்தவர்களும் கோபமடைந்து, \"நாங்கள் அதிக வேலை செய்தோம், ஆனால் குறைந்த கூலியைப் பெற்றுள்ளோம்\" என்று கூறினார்கள். அல்லாஹ், \"உங்கள் கூலியில் நான் ஏதேனும் அநீதி இழைத்தேனா?\" என்று கேட்டான். அவர்கள் \"இல்லை\" என்றனர். அதற்கு அல்லாஹ், \"அப்படியானால் இது எனது அருட்கொடை, நான் நாடுவோருக்கு இதனை வழங்குகிறேன்\" என்று கூறினான்.) இதனை அல்-புகாரி பதிவு செய்துள்ளார். அபூ மூஸா (ரழி) அவர்கள் நபி (ஸல்) அவர்கள் கூறியதாக அறிவித்ததை அல்-புகாரி பதிவு செய்துள்ளார்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَثَلُ</span> <span class=\"quran-arabic-font text-success\">الْمُسْلِمِينَ</span> <span class=\"quran-arabic-font text-success\">وَالْيَهُودِ</span> <span class=\"quran-arabic-font text-success\">وَالنَّصَارَى</span> <span class=\"quran-arabic-font text-success\">كَمَثَلِ</span> <span class=\"quran-arabic-font text-success\">رَجُلٍ</span> <span class=\"quran-arabic-font text-success\">اسْتَعْمَلَ</span> <span class=\"quran-arabic-font text-success\">قَوْمًا</span> <span class=\"quran-arabic-font text-success\">يَعْمَلُونَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">عَمَلًا</span> <span class=\"quran-arabic-font text-success\">يَوْمًا</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">اللَّيْلِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَجْرٍ</span> <span class=\"quran-arabic-font text-success\">مَعْلُومٍ،</span> <span class=\"quran-arabic-font text-success\">فَعَمِلُوا</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">نِصْفِ</span> <span class=\"quran-arabic-font text-success\">النَّهَارِ</span> <span class=\"quran-arabic-font text-success\">فَقَالُوا</span>: <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">حَاجَةَ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">أَجْرِكَ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">شَرَطْتَ</span> <span class=\"quran-arabic-font text-success\">لَنَا،</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">عَمِلْنَا</span> <span class=\"quran-arabic-font text-success\">بَاطِلٌ،</span> <span class=\"quran-arabic-font text-success\">فَقَالَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span>: <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَفْعَلُوا،</span> <span class=\"quran-arabic-font text-success\">أَكْمِلُوا</span> <span class=\"quran-arabic-font text-success\">بَقِيَّةَ</span> <span class=\"quran-arabic-font text-success\">عَمَلِكُمْ،</span> <span class=\"quran-arabic-font text-success\">وَخُذُوا</span> <span class=\"quran-arabic-font text-success\">أَجْرَكُمْ</span> <span class=\"quran-arabic-font text-success\">كَامِلًا،</span> <span class=\"quran-arabic-font text-success\">فَأَبَوا</span> <span class=\"quran-arabic-font text-success\">وَتَرَكُوا</span> <span class=\"quran-arabic-font text-success\">وَاسْتَأْجَرَ</span> <span class=\"quran-arabic-font text-success\">آخَرِينَ</span> <span class=\"quran-arabic-font text-success\">بَعْدَهُمْ</span> <span class=\"quran-arabic-font text-success\">فَقَالَ</span>: <span class=\"quran-arabic-font text-success\">أَكْمِلُوا</span> <span class=\"quran-arabic-font text-success\">بَقِيَّةَ</span> <span class=\"quran-arabic-font text-success\">يَوْمِكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلَكُمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">شَرَطْتُ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْأَجْرِ،</span> <span class=\"quran-arabic-font text-success\">فَعَمِلُوا</span> <span class=\"quran-arabic-font text-success\">حَتْى</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">حِينَ</span> <span class=\"quran-arabic-font text-success\">صَلَّوُا</span> <span class=\"quran-arabic-font text-success\">الْعَصْرَ</span> <span class=\"quran-arabic-font text-success\">قَالُوا</span>: <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">عَمِلْنَا</span> <span class=\"quran-arabic-font text-success\">بَاطِلٌ،</span> <span class=\"quran-arabic-font text-success\">وَلَكَ</span> <span class=\"quran-arabic-font text-success\">الْأَجْرُ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">جَعَلْتَ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span>. <span class=\"quran-arabic-font text-success\">فَقَالَ</span>: <span class=\"quran-arabic-font text-success\">أَكْمِلُوا</span> <span class=\"quran-arabic-font text-success\">بَقِيَّةَ</span> <span class=\"quran-arabic-font text-success\">عَمَلِكُمْ،</span> <span class=\"quran-arabic-font text-success\">فَإِنَّمَا</span> <span class=\"quran-arabic-font text-success\">بَقِيَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">النَّهَارِ</span> <span class=\"quran-arabic-font text-success\">شَيْءٌ</span> <span class=\"quran-arabic-font text-success\">يَسِيرٌ،</span> <span class=\"quran-arabic-font text-success\">فَأَبَوا</span>. <span class=\"quran-arabic-font text-success\">فَاسْتَأْجَرَ</span> <span class=\"quran-arabic-font text-success\">قَوْمًا</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَعْمَلُوا</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">بَقِيَّةَ</span> <span class=\"quran-arabic-font text-success\">يَوْمِهِمْ</span> <span class=\"quran-arabic-font text-success\">فَعَمِلُوا</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">بَقِيَّةَ</span> <span class=\"quran-arabic-font text-success\">يَوْمِهِمْ</span> <span class=\"quran-arabic-font text-success\">حَتْى</span> <span class=\"quran-arabic-font text-success\">غَابَتِ</span> <span class=\"quran-arabic-font text-success\">الشَّمْسُ،</span> <span class=\"quran-arabic-font text-success\">فَاسْتَكْمَلُوا</span> <span class=\"quran-arabic-font text-success\">أُجْرَةَ</span> <span class=\"quran-arabic-font text-success\">الْفَرِيقَيْنِ</span> <span class=\"quran-arabic-font text-success\">كِلَيْهِمَا،</span> <span class=\"quran-arabic-font text-success\">فَذلِكَ</span> <span class=\"quran-arabic-font text-success\">مَثَلُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَمَثَلُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">قَبِلُوا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">هذَا</span> <span class=\"quran-arabic-font text-success\">النُّور</span>»<br />\r\n<br />\r\n(முஸ்லிம்கள், யூதர்கள் மற்றும் கிறிஸ்தவர்களின் உவமையாவது: ஒரு மனிதர் தொழிலாளர்களைக் காலையிலிருந்து இரவு வரை ஒரு குறிப்பிட்ட கூலிக்கு வேலைக்கு அமர்த்தினார். அவர்கள் நண்பகல் வரை வேலை செய்துவிட்டு, \"நீர் நிர்ணயித்த கூலி எங்களுக்குத் தேவையில்லை, நாங்கள் செய்த வேலை வீணாகப் போகட்டும்\" என்று கூறினர். அதற்கு அவர், \"அவ்வாறு செய்யாதீர்கள், வேலையை முழுமையாக முடியுங்கள், உங்கள் கூலியை முழுமையாகப் பெற்றுக் கொள்ளுங்கள்\" என்றார். ஆனால் அவர்கள் மறுத்து வேலையை விட்டுச் சென்றனர். பிறகு அவர் வேறு சிலரை வேலைக்கு அமர்த்தி, \"மீதமுள்ள நேரத்தை முடியுங்கள், முதல் குழுவினருக்கு நான் வாக்களித்த அதே கூலியை உங்களுக்கும் தருகிறேன்\" என்றார். அவர்கள் அஸர் தொழுகை நேரம் வரை வேலை செய்துவிட்டு, \"நாங்கள் செய்தவை வீணாகப் போகட்டும், நீர் வாக்களித்த கூலியை நாங்கள் விட்டுவிடுகிறோம்\" என்றனர். அவர், \"வேலையை முடியுங்கள், பகலில் இன்னும் சிறிது நேரமே எஞ்சியுள்ளது\" என்றார். அவர்களும் மறுத்துவிட்டனர். பின்னர் அவர் வேறு சிலரை மீதமுள்ள நேரத்திற்காக வேலைக்கு அமர்த்தினார். அவர்கள் சூரியன் மறையும் வரை வேலை செய்து முந்தைய இரு குழுவினரின் கூலிகளையும் சேர்த்துப் பெற்றனர். இதுவே அவர்களுக்கும் (யூத, கிறிஸ்தவர்கள்) இந்த ஒளியை (இஸ்லாத்தை) ஏற்றுக்கொண்டவர்களுக்கும் உதாரணமாகும்.) இதனை அல்-புகாரி மட்டுமே பதிவு செய்துள்ளார். உயர்ந்தோனாகிய அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِّئَلاَّ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمَ</span> <span class=\"quran-arabic-font text-success\">أَهْلُ</span> <span class=\"quran-arabic-font text-success\">الْكِتَابِ</span> <span class=\"quran-arabic-font text-success\">أَلاَّ</span> <span class=\"quran-arabic-font text-success\">يَقْدِرُونَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">فَضْلِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n(அல்லாஹ்வின் அருட்கொடையிலிருந்து எதன் மீதும் தங்களுக்கு அதிகாரம் இல்லை என்பதை வேதக்காரர்கள் அறிந்து கொள்வதற்காகவே இவ்வாறு செய்யப்பட்டது.) அதாவது, அல்லாஹ் கொடுப்பதைத் தடுக்கவோ அல்லது அவன் தடுப்பதைக் கொடுக்கவோ எவராலும் முடியாது என்பதை அவர்கள் உறுதிபட அறிந்து கொள்வதற்காக இவ்வாறு கூறப்பட்டது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنَّ</span> <span class=\"quran-arabic-font text-success\">الْفَضْلَ</span> <span class=\"quran-arabic-font text-success\">بِيَدِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">يُؤْتِيهِ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">ذُو</span> <span class=\"quran-arabic-font text-success\">الْفَضْلِ</span> <span class=\"quran-arabic-font text-success\">الْعَظِيمِ</span><br />\r\n<br />\r\n(நிச்சயமாக அருட்கொடை அல்லாஹ்வின் கையிலேயே உள்ளது; அவன் அதனைத் தான் நாடியோருக்கு வழங்குகிறான். மேலும் அல்லாஹ் மகத்தான அருட்கொடையுடையவன்.) இத்துடன் சூரத்துல் ஹதீதின் தஃப்ஸீர் நிறைவுற்றது. புகழனைத்தும் அல்லாஹ்வுக்கே உரியது; எல்லா நன்மைகளும் அவனிடமிருந்தே உண்டாகின்றன.<br />\r\n<br />\r\n<br />\r\n<br />","text":"வேதக்காரர்களில் ஈமான் கொண்டவர்களுக்கு இரு மடங்கு நற்கூலி கிடைக்கும்\n\r\n\n\r\nஇஸ்லாத்தை ஏற்றுக்கொண்ட வேதக்காரர்களைப் பற்றியே இந்த வசனம் இறங்கியது என்றும், அவ்வாறு அவர்கள் ஈமான் கொள்ளும்போது தங்களது நற்கூலியை இரு மடங்காகப் பெறுவார்கள் என்றும் இப்னு அப்பாஸ் (ரழி) அவர்கள் வழியாக அன்-நஸாஈ பதிவு செய்துள்ள ஒரு ஹதீஸை நாம் முன்பே குறிப்பிட்டோம். இந்தக் கருத்தை உறுதிப்படுத்தும் ஒரு வசனம் சூரத்துல் கஸஸிலும் இடம் பெற்றுள்ளது. மேலும், அபூ மூஸா அல்-அஷ்அரீ (ரழி) அவர்கள் அறிவிக்க, அவர்களின் தந்தை வழியாக அபூ புர்தா, அவரிடமிருந்து அஷ்-ஷஃபீ அறிவிக்கும் ஒரு ஹதீஸில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«ثَلَاثَةٌ يُؤْتَوْنَ أَجْرَهُمْ مَرَّتَيْنِ: رَجُلٌ مِنْ أَهْلِ الْكِتَابِ آمَنَ بِنَبِيِّهِ وَآمَنَ بِي فَلَهُ أَجْرَانِ، وَعَبْدٌ مَمْلُوكٌ أَدَّى حَقَّ اللهِ وَحَقَّ مَوَالِيهِ فَلَهُ أَجْرَانِ، وَرَجُلٌ أَدَّبَ أَمَتَهُ فَأَحْسَنَ تَأْدِيبَهَا، ثُمَّ أَعْتَقَهَا وَتَزَوَّجَهَا فَلَهُ أَجْرَان»\n\r\n\n\r\n(மூன்று நபர்களுக்கு அவர்களின் நற்கூலி இருமுறை வழங்கப்படும். வேதக்காரர்களில் உள்ள ஒரு நம்பிக்கையாளர், அவர் தனது நபியின் மீது ஈமான் கொண்டு, பிறகு என் மீதும் ஈமான் கொண்டால் அவருக்கு இரு மடங்கு நற்கூலி உண்டு. அல்லாஹ்வின் உரிமைகளையும் கடமைகளையும் நிறைவேற்றி, தனது எஜமானரின் கடமைகளையும் நிறைவேற்றும் ஓர் அடிமைக்கும் இரு மடங்கு நற்கூலி உண்டு. தன்னிடம் உள்ள ஓர் அடிமைப் பெண்ணுக்கு முறையாகக் கல்வியூட்டி, நற்பண்புகளை முறையாகக் கற்றுக்கொடுத்து (கடுமையின்றி), பின்னர் அவளை விடுதலை செய்து மணமுடித்துக் கொண்டவருக்கும் இரு மடங்கு நற்கூலி உண்டு.) இந்த ஹதீஸ் புகாரி மற்றும் முஸ்லிம் ஆகிய இரு ஸஹீஹ் நூல்களிலும் இடம் பெற்றுள்ளது. அத்-தஹ்ஹாக், உத்பா பின் அபீ ஹக்கீம் மற்றும் பலர் இவ்விஷயத்தில் இப்னு அப்பாஸ் (ரழி) அவர்களுடன் உடன்படுகின்றனர்; இப்னு ஜரீரும் இதையே சிறந்த கருத்தாகக் கொண்டுள்ளார். உயர்ந்தோனாகிய அல்லாஹ் மற்றொரு வசனத்தில் கூறுகிறான்:\n\r\n\n\r\nيَا أَيُّهَا الَّذِينَ ءَامَنُواْ إِن تَتَّقُواْ اللَّهَ يَجْعَل لَّكُمْ فُرْقَانًا وَيُكَفِّرْ عَنكُمْ سَيِّئَاتِكُمْ وَيَغْفِرْ لَكُمْ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ\n\r\n\n\r\n(நம்பிக்கை கொண்டோரே! நீங்கள் அல்லாஹ்வுக்கு அஞ்சி நடந்தால், அவன் உங்களுக்கு (நன்மை தீமைகளை)ப் பிரித்தறியும் ஆற்றலை வழங்குவான்; உங்கள் பாவங்களை உங்களை விட்டும் போக்கி, உங்களை மன்னிப்பான். மேலும் அல்லாஹ் மகத்தான அருட்கொடையுடையவன்.) (8:29) ஸஈத் பின் அப்துல் அஜீஸ் அவர்கள் கூறினார்கள்: உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள் ஒரு யூத அறிஞரிடம், \"உங்களுக்கு நற்கூலி அதிகபட்சமாக எவ்வளவு அதிகரிக்கப்படும்?\" என்று கேட்டார்கள். அதற்கு அவர், \"ஒரு 'கிஃப்ல்' (பங்கு), அது சுமார் முந்நூற்று ஐம்பது நன்மைகளுக்குச் சமமானது\" என்று பதிலளித்தார். அப்போது உமர் (ரழி) அவர்கள், \"நமக்கு இரண்டு கிஃப்ல்களை வழங்கிய அல்லாஹ்வுக்கே புகழனைத்தும்\" என்று கூறினார்கள். பின்னர் ஸஈத் அவர்கள் அல்லாஹ்வின் இவ்வசனத்தைக் குறிப்பிட்டார்கள்:\n\r\n\n\r\nيُؤْتِكُمْ كِفْلَيْنِ مِن رَّحْمَتِهِ\n\r\n\n\r\n(அவன் தனது அருளிலிருந்து உங்களுக்கு இரு பங்குகளை வழங்குவான்.) \"வெள்ளிக்கிழமையன்று கிடைக்கும் இரு கிஃப்ல்களும் இதைப் போன்றதே\" என்று ஸஈத் கூறினார்கள். இதனை இப்னு ஜரீர் பதிவு செய்துள்ளார். இமாம் அஹ்மத் அவர்கள் அப்துல்லாஹ் பின் உமர் (ரழி) வழியாகப் பதிவு செய்துள்ள ஒரு ஹதீஸும் இந்தக் கருத்தை ஆதரிக்கிறது. அதில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«مَثَلُكُمْ وَمَثَلُ الْيَهُودِ وَالنَّصَارَى كَمَثَلِ رَجُلٍ اسْتَعْمَلَ عُمَّالًا فَقَالَ: مَنْ يَعْمَلُ لِي مِنْ صَلَاةِ الصُّبْحِ إِلَى نِصْفِ النَّهَارِ عَلَى قِيرَاطٍ قِيرَاطٍ؟ أَلَا فَعَمِلَتِ الْيَهُودُ، ثُمَّ قَالَ: مَنْ يَعْمَلُ لِي مِنْ صَلَاةِ الظُّهْرِ إِلَى صَلَاةِ الْعَصْرِ عَلَى قِيرَاطٍ قِيرَاطٍ؟ أَلَا فَعَمِلَتِ النَّصَارَى، ثُمَّ قَالَ: مَنْ يَعْمَلُ لِي مِنْ صَلَاةِ الْعَصْرِ إِلَى غُرُوبِ الشَّمْسِ عَلَى قِيرَاطَيْنِ قِيرَاطَيْنِ؟ أَلَا فَأَنْتُمُ الَّذِينَ عَمِلْتُمْ، فَغَضِبَ النَّصَارَى وَالْيَهُودُ وَقَالُوا: نَحْنُ أَكْثَرُ عَمَلًا وَأَقَلُّ عَطَاءً، قَالَ: هَلْ ظَلَمْتُكُمْ مِنْ أَجْرِكُمْ شَيْئًا؟ قَالُوا: لَا، قَالَ: فَإِنَّمَا هُوَ فَضْلِي أُوتِيهِ مَنْ أَشَاء»\n\r\n\n\r\n(உங்களுக்கும் யூத, கிறிஸ்தவர்களுக்கும் உள்ள உவமையாவது: ஒரு மனிதர் சில தொழிலாளர்களை வேலைக்கு அமர்த்தி, \"சுபஹ் தொழுகையிலிருந்து நண்பகல் வரை தலா ஒரு 'கீராத்' (ஒரு குறிப்பிட்ட எடை அளவு) கூலிக்கு எனக்காகப் பணியாற்றுபவர் யார்?\" என்று கேட்டார். யூதர்கள் அந்த வேலையைச் செய்தார்கள். பிறகு அவர், \"லுஹ்ருத் தொழுகையிலிருந்து அஸர் தொழுகை வரை தலா ஒரு கீராத் கூலிக்கு எனக்காகப் பணியாற்றுபவர் யார்?\" என்று கேட்டார். கிறிஸ்தவர்கள் அந்த வேலையைச் செய்தார்கள். பிறகு அவர், \"அஸர் தொழுகையிலிருந்து சூரியன் மறையும் வரை தலா இரண்டு கீராத் கூலிக்கு எனக்காகப் பணியாற்றுபவர் யார்?\" என்று கேட்டார். நீங்கள்தான் அந்த வேலையைச் செய்தவர்கள். இதைக் கண்டு யூதர்களும் கிறிஸ்தவர்களும் கோபமடைந்து, \"நாங்கள் அதிக வேலை செய்தோம், ஆனால் குறைந்த கூலியைப் பெற்றுள்ளோம்\" என்று கூறினார்கள். அல்லாஹ், \"உங்கள் கூலியில் நான் ஏதேனும் அநீதி இழைத்தேனா?\" என்று கேட்டான். அவர்கள் \"இல்லை\" என்றனர். அதற்கு அல்லாஹ், \"அப்படியானால் இது எனது அருட்கொடை, நான் நாடுவோருக்கு இதனை வழங்குகிறேன்\" என்று கூறினான்.) இதனை அல்-புகாரி பதிவு செய்துள்ளார். அபூ மூஸா (ரழி) அவர்கள் நபி (ஸல்) அவர்கள் கூறியதாக அறிவித்ததை அல்-புகாரி பதிவு செய்துள்ளார்:\n\r\n\n\r\n«مَثَلُ الْمُسْلِمِينَ وَالْيَهُودِ وَالنَّصَارَى كَمَثَلِ رَجُلٍ اسْتَعْمَلَ قَوْمًا يَعْمَلُونَ لَهُ عَمَلًا يَوْمًا إِلَى اللَّيْلِ عَلَى أَجْرٍ مَعْلُومٍ، فَعَمِلُوا إِلَى نِصْفِ النَّهَارِ فَقَالُوا: لَا حَاجَةَ لَنَا فِي أَجْرِكَ الَّذِي شَرَطْتَ لَنَا، وَمَا عَمِلْنَا بَاطِلٌ، فَقَالَ لَهُمْ: لَا تَفْعَلُوا، أَكْمِلُوا بَقِيَّةَ عَمَلِكُمْ، وَخُذُوا أَجْرَكُمْ كَامِلًا، فَأَبَوا وَتَرَكُوا وَاسْتَأْجَرَ آخَرِينَ بَعْدَهُمْ فَقَالَ: أَكْمِلُوا بَقِيَّةَ يَوْمِكُمْ وَلَكُمُ الَّذِي شَرَطْتُ لَهُمْ مِنَ الْأَجْرِ، فَعَمِلُوا حَتْى إِذَا كَانَ حِينَ صَلَّوُا الْعَصْرَ قَالُوا: مَا عَمِلْنَا بَاطِلٌ، وَلَكَ الْأَجْرُ الَّذِي جَعَلْتَ لَنَا فِيهِ. فَقَالَ: أَكْمِلُوا بَقِيَّةَ عَمَلِكُمْ، فَإِنَّمَا بَقِيَ مِنَ النَّهَارِ شَيْءٌ يَسِيرٌ، فَأَبَوا. فَاسْتَأْجَرَ قَوْمًا أَنْ يَعْمَلُوا لَهُ بَقِيَّةَ يَوْمِهِمْ فَعَمِلُوا لَهُ بَقِيَّةَ يَوْمِهِمْ حَتْى غَابَتِ الشَّمْسُ، فَاسْتَكْمَلُوا أُجْرَةَ الْفَرِيقَيْنِ كِلَيْهِمَا، فَذلِكَ مَثَلُهُمْ وَمَثَلُ مَا قَبِلُوا مِنْ هذَا النُّور»\n\r\n\n\r\n(முஸ்லிம்கள், யூதர்கள் மற்றும் கிறிஸ்தவர்களின் உவமையாவது: ஒரு மனிதர் தொழிலாளர்களைக் காலையிலிருந்து இரவு வரை ஒரு குறிப்பிட்ட கூலிக்கு வேலைக்கு அமர்த்தினார். அவர்கள் நண்பகல் வரை வேலை செய்துவிட்டு, \"நீர் நிர்ணயித்த கூலி எங்களுக்குத் தேவையில்லை, நாங்கள் செய்த வேலை வீணாகப் போகட்டும்\" என்று கூறினர். அதற்கு அவர், \"அவ்வாறு செய்யாதீர்கள், வேலையை முழுமையாக முடியுங்கள், உங்கள் கூலியை முழுமையாகப் பெற்றுக் கொள்ளுங்கள்\" என்றார். ஆனால் அவர்கள் மறுத்து வேலையை விட்டுச் சென்றனர். பிறகு அவர் வேறு சிலரை வேலைக்கு அமர்த்தி, \"மீதமுள்ள நேரத்தை முடியுங்கள், முதல் குழுவினருக்கு நான் வாக்களித்த அதே கூலியை உங்களுக்கும் தருகிறேன்\" என்றார். அவர்கள் அஸர் தொழுகை நேரம் வரை வேலை செய்துவிட்டு, \"நாங்கள் செய்தவை வீணாகப் போகட்டும், நீர் வாக்களித்த கூலியை நாங்கள் விட்டுவிடுகிறோம்\" என்றனர். அவர், \"வேலையை முடியுங்கள், பகலில் இன்னும் சிறிது நேரமே எஞ்சியுள்ளது\" என்றார். அவர்களும் மறுத்துவிட்டனர். பின்னர் அவர் வேறு சிலரை மீதமுள்ள நேரத்திற்காக வேலைக்கு அமர்த்தினார். அவர்கள் சூரியன் மறையும் வரை வேலை செய்து முந்தைய இரு குழுவினரின் கூலிகளையும் சேர்த்துப் பெற்றனர். இதுவே அவர்களுக்கும் (யூத, கிறிஸ்தவர்கள்) இந்த ஒளியை (இஸ்லாத்தை) ஏற்றுக்கொண்டவர்களுக்கும் உதாரணமாகும்.) இதனை அல்-புகாரி மட்டுமே பதிவு செய்துள்ளார். உயர்ந்தோனாகிய அல்லாஹ் கூறினான்:\n\r\n\n\r\nلِّئَلاَّ يَعْلَمَ أَهْلُ الْكِتَابِ أَلاَّ يَقْدِرُونَ عَلَى شَىْءٍ مِّن فَضْلِ اللَّهِ\n\r\n\n\r\n(அல்லாஹ்வின் அருட்கொடையிலிருந்து எதன் மீதும் தங்களுக்கு அதிகாரம் இல்லை என்பதை வேதக்காரர்கள் அறிந்து கொள்வதற்காகவே இவ்வாறு செய்யப்பட்டது.) அதாவது, அல்லாஹ் கொடுப்பதைத் தடுக்கவோ அல்லது அவன் தடுப்பதைக் கொடுக்கவோ எவராலும் முடியாது என்பதை அவர்கள் உறுதிபட அறிந்து கொள்வதற்காக இவ்வாறு கூறப்பட்டது.\n\r\n\n\r\nوَأَنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَآءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ\n\r\n\n\r\n(நிச்சயமாக அருட்கொடை அல்லாஹ்வின் கையிலேயே உள்ளது; அவன் அதனைத் தான் நாடியோருக்கு வழங்குகிறான். மேலும் அல்லாஹ் மகத்தான அருட்கொடையுடையவன்.) இத்துடன் சூரத்துல் ஹதீதின் தஃப்ஸீர் நிறைவுற்றது. புகழனைத்தும் அல்லாஹ்வுக்கே உரியது; எல்லா நன்மைகளும் அவனிடமிருந்தே உண்டாகின்றன."}}};})(self);
